window.ENAMED_LOCAL_QUESTION_BANK=window.ENAMED_LOCAL_QUESTION_BANK||{};window.ENAMED_LOCAL_QUESTION_BANK["med:med-clinica-medica-med-clm-13"]={"block":"med:med-clinica-medica-med-clm-13","label":"MED · MED CLM 13","count":480,"questions":[{"id":"med-clinica-medica-med-clm-13-343777","number":"343777","sourceNumber":"343777","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"A crise convulsiva febril corresponde a um dos problemas neurológicos mais frequentes\nobservados na população pediátrica e\nocorre em sua maioria em associação a infecções virais. A\nrespeito da classificação das crises convulsivas febris, marque a opção correta.","options":{"A":"Crise febril simples é aquela que se apresenta como uma crise tônico-clônica generalizada com\nduração inferior a 30 minutos, que não há recorrência nas próximas 24 horas e a recuperação é\nespontânea e completa.","B":"A crise febril complexa é definida por uma ou mais das seguintes características: crises focais;\ncrises seguidas de alterações neurológicas\npós-ictais, como a Paralisia de Todd; duração superior a\n30 minutos; e, recorrência em menos de 24 horas.","C":"O estado de mal epiléptico febril é uma crise febril com duração acima de 30 minutos, podendo\ncaracterizar-se por uma única crise prolongada, ou, então, crises subentrantes, ou seja, crises\nrecorrentes entre as quais não há recuperação completa do nível de consciência.","D":"Crise febril complexa é aquela que se apresenta como uma crise tônico-clônica generalizada\ncom duração inferior a 15 minutos, que não há\nrecorrência nas próximas 24 horas."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-345497","number":"345497","sourceNumber":"345497","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Paciente pré-escolar, com diagnóstico prévio de epilepsia, chega à emergência em\ncrise convulsiva, iniciada ainda em casa. O tempo de chegada ao hospital foi de 15 minutos e o\npaciente está em avaliação há 5 minutos, foi medicado e está entrando no período pós-ictal.\n\nNota-se febre, leve desidratação e diarreia iniciada há 2 dias. Sobre o caso, assinale a alternativa\nCORRETA:","options":{"A":"A causa mais provável da descompensação desse paciente é o esquecimento das doses de\nmanutenção, mesmo em casos de boa aderência e mesmo que a família negue esquecimentos.","B":"Trata-se de uma crise convulsiva febril simples, de caráter benigno, cujo tratamento deve ser\ndirecionado para o controle rigoroso da febre e identificação do foco.","C":"O paciente apresentou estado de mal epilético de causa sintomática aguda.","D":"O paciente não pode ser classificado como crise convulsiva febril, por apresentar critérios de\nexclusão."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-281122","number":"281122","sourceNumber":"281122","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Paciente de 23 anos de idade, relata episódios de lapsos breves e súbitos de\nconsciência, sem perda postural, com duração\nde segundos, sem confusão pós-ictal. Realizou EEG\nque apresentou descargas em ponta-onda generalizada simétrica de 3 Hz. Das drogas listadas\nabaixo, assinale a menos indicada para o caso.","options":{"A":"Ácido valpróico.","B":"Etossuximida.","C":"Gabapentina.","D":"Clonazepam.","E":"Lamotrigina."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-247162","number":"247162","sourceNumber":"247162","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Paciente do sexo masculino, 35 anos, etilista (1 litro de destilado ao dia) há 5 anos.\nRefere que há uma semana iniciou com\nparestesias nos pés, que progrediram de maneira\nascendente. Há dois dias evoluiu com redução progressiva de força em MMII e há um dia não\nconsegue mais deambular. O exame neurológico evidencia força grau I e ausência de reflexos em\nMMII, força grau V em MMSS com reflexos preservados. As sensibilidades dolorosa e vibratória\nestão preservadas; não foi evidenciado nível sensitivo. O hemograma demonstra anemia\nmacrocítica. A radiografia de coluna lombossacral é normal. O exame do liquor revela: celularidade\n\n= 4 células/mm³, glicose= 70mg/dL; proteína= 210 mg/dL. Assinale a alternativa CORRETA, que\napresenta o diagnóstico mais provável.","options":{"A":"Deficiência de vitamina B12.","B":"Polineuropatia alcoólica.","C":"Síndrome de Guillain-Barré.","D":"Mielite transversa.","E":"Neurossífilis."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-217702","number":"217702","sourceNumber":"217702","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"As convulsões são um dos problemas neurológicos mais frequentes da febre. Com\nrelação à crise convulsiva febril na infância qual das alternativas abaixo está CORRETA?","options":{"A":"A faixa etária na qual a crise convulsiva febril ocorre é entre os 6 meses e 6 anos de idade.","B":"As crises convulsivas febris não podem ser classificadas em complexas, tendo como\napresentação única a crise convulsiva do tipo simples.","C":"Atraso no desenvolvimento neuropsicomotor não é considerado fator de risco importante para\nprimeira crise convulsiva febril.","D":"Após o primeiro episódio de crise convulsiva febril simples é necessário iniciar tratamento\nprofilático."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-182661","number":"182661","sourceNumber":"182661","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Na vigência de uma primeira crise epiléptica febril, a conduta mais adequada?","options":{"A":"Vai depender do tipo de crise.","B":"Não iniciar tratamento com drogas antiepilépticas.","C":"Iniciar tratamento com drogas antiepilépticas em baixas doses.","D":"Aguardar o resultado da avaliação eletroencefalográfica para determinar a conduta."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-108686","number":"108686","sourceNumber":"108686","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Em relação à abordagem clínica e terapêutica dos pacientes idosos, selecione a\nafirmativa CORRETA.","options":{"A":"A Fragilidade é uma Síndrome definida pela presença de perda de peso não intencional de\n4,5KG ou mais no último ano, força de preensão precária (fraqueza), além de velocidade de\ndeambulação lenta e baixa atividade física;","B":"Não há evidência epidemiológica de que a avaliação funcional do Idoso seja um bom\nprognóstico e da longevidade;","C":"Não há evidência epidemiológica da associação de má nutrição com o aumento da Morbidade e\nadmissão nos asilos;","D":"Não há evidência epidemiológica da associação da Fragilidade nos pacientes idosos e o\naumento do risco de quedas, incapacidade e morte."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-84454","number":"84454","sourceNumber":"84454","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"A vacina profilática contra o papilomavírus humano está indicada para a população\nfeminina de que faixa etária?","options":{"A":"29 a 36 anos.","B":"9 a 26 anos.","C":"19 a 46 anos.","D":"16 a 29 anos.","E":"26 a 39 anos."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-66950","number":"66950","sourceNumber":"66950","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"No que tange a sexualidade em idoso, é INCORRETO afirmar que:","options":{"A":"Muitas das alterações sexuais que ocorrem com o avançar da idade podem ser resolvidas\napenas com orientação e educação;","B":"O desempenho sexual, nesta idade, pode ser afetado pelo medo do infarto durante a relação;","C":"A investigação de doenças sexualmente transmissíveis/AIDS deve fazer parte da avaliação\nsistemática das pessoas idosas com vida sexual ativa;","D":"A incapacidade de desfrutar prazer nas relações sexuais deve ser considerada como parte\nnormal do envelhecimento;"},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-66975","number":"66975","sourceNumber":"66975","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Todas abaixo são perguntas do teste de CAGE para o diagnóstico de alcoolismo,\nEXCETO:","options":{"A":"Alguma vez o (a) senhor (a) sentiu que deveria diminuir a quantidade de bebida ou parar de\nbeber?","B":"As pessoas o (a) aborrecem porque criticam seu modo de beber?","C":"O (a) senhor (a) sempre aceita quando lhe oferecem bebida?","D":"O (a) senhor (a) sente-se culpado (a) chateado (a) consigo mesmo (a) pela maneira como\ncostuma beber?"},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-50096","number":"50096","sourceNumber":"50096","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"São recomendações gerais para prevenção de quedas em pacientes que vivem na\ncomunidade, EXCETO:","options":{"A":"Treinar marcha com eventual utilização de objetos auxiliares, como bengalas e andadores;","B":"Modificar fatores ambientais que colocam o paciente em risco, como tapetes soltos, fios elétricos\nno trajeto, escadas com degraus maldemarcados;","C":"Realizar programas de exercício para o equilíbrio;","D":"Suspender anti-hipertensivos em pacientes com risco cardiovascular inferior a 20% pelo risco de\nhipotensão postural;"},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-37127","number":"37127","sourceNumber":"37127","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Com relação ao Cuidado Domiciliar é incorreto afirmar que:","options":{"A":"Que há 50 anos, as visitas domiciliares eram uma parte importante de trabalho do médico de\nfamília e comunidade.","B":"Que a qualidade do atendimento às pessoas é melhor no consultório ou no hospital, do que em\nseu domicílio.","C":"As mudanças no sistema de atendimento à saúde estão aumentando a demanda por cuidado\ndomiciliar.","D":"O movimento a favor de cuidados paliativos promoveu a integração dos serviços de cuidado\ndomiciliar para pessoas terminalmente doentes.","E":"No cuidado domiciliar o médico de família ou médico generalista é o membro-chave da equipe."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-37130","number":"37130","sourceNumber":"37130","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Pode-se citar como consenso quanto aos objetivos da promoção da saúde e de\nprevenção de doenças, nos pacientes idosos, exceto:","options":{"A":"Redução da mortalidade prematura causada por doenças agudas ou crônicas.","B":"Manutenção da independência funcional.","C":"Privilégio dos idosos nesta etapa do seu ciclo vital.","D":"Melhora na qualidade de vida.","E":"Nenhuma das alternativas."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-37131","number":"37131","sourceNumber":"37131","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Com relação à população idosa, podemos afirmar, exceto:","options":{"A":"Estima-se que a população de idoso maior ou igual a 60 anos, deverá duplicar até o ano de\n2050, alcançando 15% do total da população brasileira.","B":"Parte do desafio de Prevenção está na determinação de quais pacientes rastrear e de quando\nseria o melhor momento de fazê-lo.","C":"Já é conhecida inteiramente a relação entre manejo pró-ativo dos pacientes idosos, qualidade\nde vida e longevidade.","D":"As perdas funcionais e psicossociais que acompanham o envelhecimento podem,\nfrequentemente, resultar em depressão.","E":"Nenhuma das alternativas."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-372080","number":"372080","sourceNumber":"372080","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"A degeneração neuronal da Atrofia Muscular Espinhal 5q tipos 1 e 2, evolui e:","options":{"A":"Resulta em fraqueza, hiporreflexia e atrofia simétrica progressiva com predomínio dos músculos\nvoluntários proximais de membros inferiores, superiores, e, durante a progressão da doença, pode\nafetar os músculos axiais, da respiração e bulbares que, por sua vez, pode gerar falha respiratória\ne\nmorte.","B":"Resulta em fraqueza, hiporreflexia e atrofia assimétrica progressiva com predomínio dos\nmúsculos voluntários proximais de membros\nsuperiores apenas, durante a progressão da doença,\npode afetar os músculos axiais, da respiração e bulbares que, por sua vez, pode gerar falha\nrespiratória e morte.","C":"Não resulta em fraqueza, e sim hiperreflexia sem atrofia simétrica progressiva com predomínio\ndos músculos voluntários proximais de membros\ninferiores, superiores, e, durante a progressão da\ndoença, pode afetar os músculos axiais, da respiração e bulbares que, por sua vez, pode gerar\nfalha respiratória e morte.","D":"Resulta em fraqueza, hiporreflexia e atrofia simétrica progressiva com predomínio dos músculos\nvoluntários proximais de membros inferiores, superiores, e, durante a progressão da doença, pode\nafetar os músculos axiais, da respiração e bulbares que, por sua vez, pode gerar falha respiratória,\nmas não a morte."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-341035","number":"341035","sourceNumber":"341035","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Mulher, 20 anos de idade, dá entrada na Unidade de Pronto Atendimento duas horas\napós episódio de crise tônico-clônica\ngeneralizada. Refere ser o segundo episódio, tendo o primeiro\nocorrido há dois meses. Nega comorbidades, trauma, uso de álcool, tabaco ou drogas ilícitas. Faz\nuso apenas de contraceptivo oral. Ao exame, apresenta-se em bom estado geral, sinais vitais\nestáveis. Exame segmentar e neurológico sem achados. Realizada tomografia computadorizada de\ncrânio sem alterações. Diante do caso clínico, com relação ao diagnóstico mais provável, pode-se\nafirmar:","options":{"A":"Durante ou após uma crise, pode ocorrer morte súbita inesperada decorrente de apneia ou\narritmia.","B":"As crises sempre ocorrem após um fator desencadeante, como a estimulação luminosa\nintermitente.","C":"Apesar de haver interferência na qualidade de vida a mortalidade é equiparável à da população\ngeral.","D":"As crises geralmente deixam sequelas neurológicas, levando a déficit cognitivo."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-341036","number":"341036","sourceNumber":"341036","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Mulher, 20 anos de idade, dá entrada na Unidade de Pronto Atendimento duas horas\napós episódio de crise tônico-clônica\ngeneralizada. Refere ser o segundo episódio, tendo o primeiro\nocorrido há dois meses. Nega comorbidades, trauma, uso de álcool, tabaco ou drogas ilícitas. Faz\nuso apenas de contraceptivo oral. Ao exame, apresenta-se em bom estado geral, sinais vitais\nestáveis. Exame segmentar e neurológico sem achados. Realizada tomografia computadorizada de\ncrânio sem alterações. Com base no quadro descrito, indique o exame complementar mais\nadequado neste momento:","options":{"A":"Ressonância nuclear magnética de crânio.","B":"Eletroencefalograma.","C":"Angiotomografia computadorizada de crânio.","D":"Exame de líquor."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-341037","number":"341037","sourceNumber":"341037","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Mulher, 20 anos de idade, dá entrada na Unidade de Pronto Atendimento duas horas\napós episódio de crise tônico-clônica\ngeneralizada. Refere ser o segundo episódio, tendo o primeiro\nocorrido há dois meses. Nega comorbidades, trauma, uso de álcool, tabaco ou drogas ilícitas. Faz\nuso apenas de contraceptivo oral. Ao exame, apresenta-se em bom estado geral, sinais vitais\nestáveis. Exame segmentar e neurológico sem achados. Realizada tomografia computadorizada de\ncrânio sem alterações. Indique a melhor conduta terapêutica a ser realizada, neste momento, na\npaciente:","options":{"A":"Aguardar a realização do exame complementar para prescrição de fármaco.","B":"Expectante, sendo prescindível o início de medicação anticonvulsivante.","C":"Prescrever diazepam 10mg, via intravenosa, como primeira escolha medicamentosa.","D":"Iniciar anticonvulsivante, considerando o uso do contraceptivo oral na escolha do fármaco."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-278606","number":"278606","sourceNumber":"278606","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"A fraqueza da Esclerose Lateral Amiotrófica leva a uma respiração cada vez mais\nsuperficial e rápida com sintomas crônicos\nde hipoventilação alveolar. Os sinais de hipoventilação\nocorrem durante o sono REM e, em uma fase mais avançada da doença, manifestam-se no período\ndiurno. Sendo CORRETO que:","options":{"A":"A fraqueza da musculatura expiratória combinada com inadequadas insuflações dos pulmões\nimpede a eficácia da tosse, mas não limpeza de vias aéreas, alterando a resistência das vias\naéreas e aumentando o risco de desenvolvimento de atelectasias e pneumonia.","B":"A fraqueza da musculatura expiratória combinada com inadequadas insuflações dos pulmões\nimpede a eficácia da tosse e limpeza de vias aéreas, alterando a resistência das vias aéreas e\nredução do risco de desenvolvimento de atelectasias e pneumonia.","C":"A fraqueza da musculatura expiratória combinada com inadequadas insuflações dos pulmões\nimpede a eficácia da tosse e limpeza de\nvias aéreas, não alterando a resistência das vias aéreas e\nreduzindo o risco de desenvolvimento de atelectasias e pneumonia.","D":"A fraqueza da musculatura expiratória combinada com inadequadas insuflações dos pulmões\nimpede a eficácia da tosse e limpeza de vias aéreas, alterando a resistência das vias aéreas e\naumentando o risco de desenvolvimento de atelectasias e pneumonia."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-280417","number":"280417","sourceNumber":"280417","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Assinale a alternativa incorreta em relação aos sinais e sintomas que sugerem o\ndiagnóstico de Síndrome de Guillain Barré.","options":{"A":"Sintomas sensoriais leves, especialmente dor em crianças menores.","B":"Disfunção autonômica, em qualquer modalidade.","C":"Assimetria marcante.","D":"Envolvimento de nervos cranianos."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-278633","number":"278633","sourceNumber":"278633","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"As anormalidades na substância branca subcortical, o envolvimento do tálamo, dos\ngânglios da base e do tronco cerebral encontrada na RNM são características de qual forma de\nencefalite?","options":{"A":"ADEM.","B":"Herpes vírus.","C":"Enterovírus.","D":"Anti-NMDA."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-280431","number":"280431","sourceNumber":"280431","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Na semiologia da Síndrome do Desfiladeiro Torácico pede-se para paciente inspirar\nmaximamente e manter sua respiração enquanto o pescoço é estendido e a cabeça é girada para o\nlado afetado. Esta manobra estreita o espaço entre os músculos escalenos anterior e médio,\nresultando em compressão da artéria subclávia e do plexo braquial. Diminuição ou perda do pulso\nradial ipsilateral sugere compressão. Trata-se do teste de:","options":{"A":"Teste de Adson.","B":"Teste de Allen.","C":"Teste de Halsted.","D":"Teste de Roos."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-249267","number":"249267","sourceNumber":"249267","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Algumas vacinas de vírus vivos atenuados ou mortos podem anteceder a síndrome de\nGuillain-Barré (SGB), que se manifesta clinicamente como polirradiculoneurite inflamatória com\nlesão de desmielinização, parestesias e deficit motor ascendente de intensidade variável. Somente\nmostra erro:","options":{"A":"Geralmente, os sintomas aparecem entre 7 e 21 dias, no máximo até 42 dias (6 semanas) após\na exposição ao possível agente desencadeante.","B":"Até o momento, há poucas evidências se a vacina influenza pode aumentar o risco de\nrecorrência da SGB em indivíduos com história pregressa desta patologia.","C":"Recomenda-se precaução na vacinação dos indivíduos com história pregressa da SGB, mesmo\nsabendo ser bastante rara.","D":"Reações anafiláticas graves relacionadas a doses anteriores, mas não contraindicam doses\nsubsequentes."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-219883","number":"219883","sourceNumber":"219883","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Em plantão no pronto atendimento você avalia pré-escolar do sexo feminino, de 2 anos\nde idade, previamente hígida, com dor em\nregião lombar esquerda há 3 semanas, fraqueza em\nmembros inferiores e dificuldade para iniciar micção há 4 dias. Nega pródromos virais ou outros\nsintomas associados. Ao exame, observa-se perda do reflexo patelar e hipoestesia à esquerda.\n\nCom bases nestes achados, hipótese diagnóstica MAIS PROVAVÉL e a conduta inicial MAIS\nADEQUADA são:","options":{"A":"Compreensão medular espinhal, solicitar ressonância magnética de coluna.","B":"Litíase renal, solicitar exame de urina e ultrassonografia de rins e vias urinárias","C":"Mielite transversa; realizar punção liquórica.","D":"Síndrome de Guillain-Barret; realizar punção liquórica."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-215516","number":"215516","sourceNumber":"215516","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Os timomas são os tumores mais frequentes do mediastino anterior do adulto, tem\ncrescimento lento e correspondem a 20% de todos os tumores mediastinais do adulto. De acordo\ncom o estadiamento proposto por Masaoka, os timomas que apresentam invasão macroscópica de\nórgãos vizinhos são classificados como estádio","options":{"A":"I.","B":"II.","C":"III.","D":"IV."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-219856","number":"219856","sourceNumber":"219856","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Com relação à síndrome de Guillain-Barré é INCORRETO afirmar:","options":{"A":"A fraqueza muscular geralmente se inicia nos membros inferiores, mas em uma minoria dos\ncasos pode se iniciar nos membros superiores ou\nmúsculos faciais","B":"Parestesias nas mãos e pés frequentemente acompanham a fraqueza muscular, mas alterações\nsensitivas ao exame são comumente discretas","C":"Nos membros acometidos, observa-se inicialmente hiperatividade dos reflexos tendinosos\nprofundos que evolui para hiporreflexia ou arreflexia com a progressão da doença","D":"Síndrome de secreção inapropriada de hormônio anti-diurético, que pode ser devida a\nacometimento autonômico, é complicação possível da síndrome de Guillain-Barré"},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-212179","number":"212179","sourceNumber":"212179","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Flávia, 1 ano e 5 meses, começou a apresentar febre (38,5 ºC) há 12 horas, bem como\ncoriza hialina e tosse seca. Sua genitora refere que, apesar da administração do antitérmico,\nrapidamente houve ascensão de sua temperatura, evoluindo com crise convulsiva (primeiro\nepisódio), com duração de cerca de 5 minutos. Procurou imediatamente atendimento em serviço de\nemergência, porém já sem sinais de crise e sem comprometimento neurológico pós-ictal na\nadmissão. Qual a melhor medida a ser tomada neste momento?","options":{"A":"Realizar eletroencefalograma para confirmar o diagnóstico e instituir terapêutica\nanticonvulsivante.","B":"Iniciar uso de anticonvulsivante profilático, pela alta probabilidade de recorrência do quadro.","C":"Realizar obrigatoriamente tomografia computadorizada de crânio para confirmar diagnóstico e\ninstituir terapêutica anticonvulsivante.","D":"Coletar imediatamente líquido cefalorraquidiano,\n\nindependentemente da ocorrência de outros sintomas de comprometimento do Sistema Nervoso\nCentral.","E":"Realizar anamnese detalhada, bem como exame físico minucioso. Afastar intoxicações\nexógenas, trauma, focos infecciosos, avaliar as\ncaracterísticas da crise e a história familiar."},"answer":"E","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-182755","number":"182755","sourceNumber":"182755","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"As miopatias inflamatórias são um grupo heterogêneo de doenças que se caracterizam\npor fraqueza muscular proximal e elevação sérica\nde enzimas originadas da musculatura\nesquelética. Sendo INCORRETO que","options":{"A":"são reconhecidos cinco subtipos de doença: polimiosite primária idiopática (PM),\ndermatomiosite primária idiopática (DM), PM ou\nDM associada à neoplasia, PM ou DM juvenil e PM\nou DM associada a outras doenças do colágeno.","B":"na PM/DM, a principal manifestação é a fraqueza proximal e simétrica de cinturas escapular e\npélvica e de musculatura cervical.","C":"dependendo do grau da perda de força, o paciente pode manifestar desde fadiga e intolerância\nao exercício até marcha cambaleante e dificuldade\npara subir escadas.","D":"a evolução tende a ser gradual e progressiva. A grande maioria dos pacientes podem apresentar\nmialgia associada."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-181409","number":"181409","sourceNumber":"181409","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Dadas as afirmativas quanto aos sintomas musculares relacionados às estatinas\n(SMRE): I. Fluoxetina está relacionada à\nocorrência da SMRE; II. Consumo de cocaína, etilismo,\ndisfunção renal, baixo IMC ehipotireoidismo constituem fatores de risco para SMRE; III. Durante a\nterapia com estatinas, elevações transitórias de creatinoquinase podem ocorrer, mesmo em\npacientes assintomáticos, mas sem significado clínico; IV. Caracteriza-se com dor e fraqueza\nsimétrica e distal que afeta pequenos grupos musculares. Habitualmente, ocorre de 4 a 12\nsemanas após início do uso das estatinas. Verifica-se que está(ão) correta(s) apenas:","options":{"A":"II.","B":"I e III.","C":"I e IV.","D":"I, II e III.","E":"II, III e IV."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-183594","number":"183594","sourceNumber":"183594","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"É INCORRETO sobre a Mediastinite Aguda Descendente Necrotizante que,","options":{"A":"a mortalidade pode ser maior que 50%.","B":"na maioria das vezes, o diagnóstico é tardio e feito quando a sepse já está instalada.","C":"complicações dessa infecção são erosão de vasos com sangramento maciço, aspiração, déficit\nnervoso craniano, supuração\n\nintracraniana e fasceíte necrotisante.","D":"origina-se de uma infecção da cavidade oral, mais comumente de um abscesso amigdaliano."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-187852","number":"187852","sourceNumber":"187852","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Leia o texto a seguir e assinale a alternativa CORRETA, identificando o diagnóstico da\ndoença retratada. \"O sinal inicial\ncaracterístico desta doença consiste em fraqueza muscular, que\nocorre em aproximadamente 60% dos pacientes. O aparecimento e a natureza dos sinais e\nsintomas é muito variável, mas como se trata de doença dos neurônios motores superior e inferior,\no tato, a audição, o paladar, o olfato e a visão não são comprometidos. Embora a terapia consiga\nalentecer a evolução da doença em alguns casos, à medida que a doença evolui, a fraqueza\nmuscular e a paralisia se propagam para os músculos do tronco, da fala, da deglutição, da\nmastigação e da respiração. Os pacientes acabam precisando de suporte ventilatório para\nsobreviverem.\"","options":{"A":"Acidente vascular encefálico","B":"Doença de Parkinson","C":"Doença de Wilson","D":"Esclerose lateral amiotrófica"},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-181431","number":"181431","sourceNumber":"181431","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"As crises epilépticas constituem um dos problemas neurológicos mais comuns da\ninfância. Em relação à crise febril:","options":{"A":"O diagnóstico é essencialmente clínico e o exame do liquor somente deve ser realizado se for\nobservada alguma alteração no exame neurológico da criança.","B":"Ocorre geralmente nas horas seguintes ao processo infeccioso agudo.","C":"Ocorre geralmente depois dos três anos de idade, associada à febre.","D":"Está sempre associada a temperaturas próximas aos 40°C.","E":"Manifesta-se em crianças com crises afebris prévias."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-158748","number":"158748","sourceNumber":"158748","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"JLS, masculino, 32 anos, foi atendido na Unidade Básica de Saúde com queixa de dor,\nparesetesias e impotência funcional que atingiam primordialmente a face palmar dos 1°, 2°, e 3°\ndedos da região tenar, principalmente do oponente do polegar e da borda radial do 4° dedo. Ao\nexame físico, o teste de Tinnel e a manobra de Phalen são positivos. Pelo relato, qual o diagnóstico\nmais provável para JLS?","options":{"A":"Dedo em gatilho.","B":"Contratura de Dupuytren.","C":"Síndrome do túnel do carpo.","D":"Síndrome do canal de Guyon.","E":"Síndrome do pronador redondo."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-134806","number":"134806","sourceNumber":"134806","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Menino de 8 anos, que não recebeu imunizações prévias, sofre uma ferida puntiforme\nno pé por material enferrujado. Qual dos\nseguintes esquemas você deve administrar à criança para\nprofilaxia pós-exposição contra tétano?","options":{"A":"Vacina DTaP.","B":"Vacina dT.","C":"Vacina DTaP e Ig tetânica.","D":"Vacina dT e Ig tetânica."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-134881","number":"134881","sourceNumber":"134881","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Garoto 15 anos é mordido na panturrilha por um cão de sua propriedade sadio e\ndomiciliado, quando tentava segurar o animal para receber a 2ª dose de vacina antirrábica. O\nferimento único assustou o garoto que foi levado imediatamente pela sua mãe à UBS para receber\nvacina contra raiva. Qual das condutas abaixo está dentro da Norma de profilaxia da raiva humana\ndo Instituto Pasteur- SP, sabendo que o garoto nunca foi vacinado contra raiva?","options":{"A":"Observar o animal por 10 dias, aplicar o soro e iniciar o esquema de 5 doses, suspendendo o\nesquema se o animal permanecer sadio durante a observação.","B":"Aplicar 3 doses de vacina IM nos dias (0,3,7) e uma dose de soro (40UI\\kg\\peso), sendo\naplicado no local do ferimento.","C":"Observar o animal por 10 dias e, caso o cão permaneça sadio, encerrar o caso.","D":"Não há necessidade do soro antirrábico, embora o ferimento seja considerado grave, apenas\naplicar 5 doses de vacina nos dias (0, 3, 7, 14, 28), sendo dia zero, o dia em que foi aplicado a 1ª\ndose e não o dia do acidente."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-110057","number":"110057","sourceNumber":"110057","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"São abordagens recomendadas para a prescrição de medicamentos com efeitos\npsicoativos em pacientes idosos, EXCETO:","options":{"A":"iniciar com dose habitual para adultos.","B":"evitar uso rotineiro destas drogas seja para ansiedade, insônia ou dor.","C":"preferir abordagens não farmacológicas quando possível.","D":"aumentar a dose lentamente."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-110021","number":"110021","sourceNumber":"110021","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Quanto ao processo de envelhecimento e aos cuidados necessários, aponte a\nalternativa INCORRETA.","options":{"A":"As quedas são responsáveis por 70% das mortes acidentais das pessoas com 75 anos\nou mais. O efeito cumulativo de alterações\nrelacionadas à idade, doenças e meio ambiente\ninadequado parecem predispor à queda.","B":"Deve-se considerar como de alto risco para quedas aqueles pacientes do sexo feminino,\ncom 80 anos ou mais, equilíbrio diminuído,\nmarcha lenta com passos curtos, baixa aptidão\nfísica, fraqueza muscular dos membros inferiores, deficiência cognitiva e uso de sedativos e/ou\npolifarmácia.","C":"Entre os principais sinais da Doença de Alzheimer estão a perda da memória, que afeta as\nhabilidades profissionais, dificuldades em realizar as atividades diárias, problemas com o\nvocabulário, desorientação no tempo e no espaço, incapacidade de julgar/avaliar situações,\ndificuldades com o raciocínio abstrato, mudanças de humor, personalidade e perda de iniciativa.","D":"Considera-se idoso frágil ou em condição de fragilidade aquela pessoa com 75 anos ou mais de\nidade."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-110002","number":"110002","sourceNumber":"110002","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Quais os parâmetros avaliados na Avaliação Geriátrica Ampla (AGA)? I. O diagnóstico\nde síndrome demencial é eminentemente clínico,\nbaseado em avaliação objetiva do desempenho\ncognitivo e funcional; II. Entre os diversos testes de rastreio para o diagnóstico de síndrome\ndemencial, a escala de Yesavage é, certamente, a mais empregada; III. O exame do liquor é\nindicado para todos os pacientes com demência. É CORRETO o que se afirma em:","options":{"A":"I, apenas.","B":"II, apenas.","C":"I e II, apenas.","D":"I, II e III."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-86634","number":"86634","sourceNumber":"86634","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Qual a melhor forma de transportar Marcia, 10 meses e com peso de 9 kg, seguindo as\nnormas do transporte seguro em crianças e adolescentes em veículos automotores.","options":{"A":"Assento infantil no banco traseiro, de costas para o painel.","B":"Assento infantil no banco traseiro, de frente para o painel.","C":"Assento infantil no banco dianteiro, de costas para o painel.","D":"Assento infantil no banco dianteiro, de frente para o painel.","E":"Assento elevatório de frente para o painel."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-86817","number":"86817","sourceNumber":"86817","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Lactente de três meses de idade é trazido à emergência apresentando crise convulsiva\ngeneralizada. A mãe refere que a criança, após crise de choro, começou a apresentar palidez,\nchoro fraco e hipoatividade, com início há 4 horas. Ao exame apresenta-se sonolento, pálido,\nrespondendo mal aos estímulos e bradipneico. O exame de fundo de olho revela papiledema e\nhemorragia retiniana. Assinale a alternativa que contém o PROVÁVEL DIAGNÓSTICO para o\nquadro clínico acima descrito.","options":{"A":"Septicemia;","B":"Meningite aguda;","C":"Crise de perda de fôlego do tipo pálido. Aspiração de leite;","D":"Síndrome do bebê sacudido;","E":"Encefalite viral."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-158417","number":"158417","sourceNumber":"158417","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Com relação ao mediastino, marque a alternativa CORRETA:","options":{"A":"Mediastino antero-posterior: seu limite anterior coincide com o limite posterior do compartimento\nposterior, e o plano da porção anterior da\ncoluna vertebral é seu limite posterior.","B":"Mediastino posterior: compreende as goteiras paravertebrais. Encontra-se nesse local uma\nvariedade de estruturas nervosas.","C":"Apenas 20% das massas mediastinais são encontradas no mediastino antero-superior.","D":"As neoplasias malignas representam 25-42% das massas mediastinais e a maioria dos\npacientes são sintomáticos.","E":"Os tumores mais frequentes do mediastino são: neuroblastoma, ganglioneuroma, schwanoma,\nfeocromacitoma, aneurismas de aorta e cistos do esôfago e cistos broncogênicos."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-158427","number":"158427","sourceNumber":"158427","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Uma paciente do sexo feminino, com 8 anos de idade, apresenta história clínica de\nperda progressiva de força muscular simétrica e arreflexia; a avaliação complementar evidencia\nliquor com dissociação albumino-citológica. Assinale a alternativa CORRETA, quanto ao\ndiagnóstico mais provável.","options":{"A":"Poliomielite.","B":"Meningite viral.","C":"Abscesso paravertebral.","D":"Síndrome de Guillain-Barrè.","E":"Tumor de fossa posterior."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-158432","number":"158432","sourceNumber":"158432","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Uma criança de 1 ano de idade dá entrada no Pronto Socorro, com história de várias\ncrises convulsivas nas últimas horas. Já recebeu\n1 dose de diazepam de 0,5 mg/kg e gardenal IM\n(5mg/kg) há menos de meia hora. Nunca havia convulsionado antes. Encontra-se em mau estado\ngeral, cianótica, pálida, com os olhos encovados e com pulsos finos; apresenta movimentos\ntônico-clônicos em membros. Assinale a alternativa correta quanto à conduta mais indicada neste\ncaso.","options":{"A":"Instalar acesso vascular, administrar duas doses de diazepam de 1 mg/kg EV, imediatamente.","B":"Oxigenar, completar a dose de gardenal IM para 10 mg/kg, imediatamente.","C":"Administrar três doses de diazepam 0,3 mg/kg EV, a cada 5 minutos e, por fim, tiopental EV.","D":"Desobstruir vias aéreas, oxigenar, acesso vascular, administrar diazepam 0,3 mg/kg EV SF0,9%\n20ml/kg EV, e fazer glicoteste.","E":"Observar a crise até que haja resolução espontânea da mesma, estando o paciente\ndevidamente oxigenado e após dar glicose hipertônica."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-362483","number":"362483","sourceNumber":"362483","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Um paciente de 37 anos de idade engenheiro bem- sucedido, casado, com epilepsia\nbem controlada por medicamentos, apresenta-se ao\npronto-socorro após uma convulsão\n\ntônico-clônica generalizada que durou 5 minutos. Ele relata que esqueceu de tomar sua medicação\nantiepiléptica nos últimos dois dias. Qual é a conduta mais apropriada?","options":{"A":"Iniciar um novo medicamento antiepiléptico.","B":"Internar para avaliação de \"\"status epilepticus\"\".","C":"Realizar uma tomografia computadorizada de emergência de crânio.","D":"Administrar uma dose de resgate do medicamento antiepiléptico atual."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-362482","number":"362482","sourceNumber":"362482","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Uma estudante de 20 anos apresenta ptose palpebral, diplopia e fraqueza muscular\nque piora com o esforço e melhora com o\nrepouso. A eletroneuromiografia mostra uma diminuição\nda amplitude do potencial de ação muscular com estimulação repetitiva. Qual é o diagnóstico mais\nprovável?","options":{"A":"Miastenia gravis.","B":"Síndrome de Lambert-Eaton.","C":"Esclerose lateral amiotrófica (ELA).","D":"Distrofia muscular facioescapuloumeral."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-362493","number":"362493","sourceNumber":"362493","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Paciente do sexo masculino, 21 anos, procura atendimento médico referindo tosse seca\npersistente, associada a dispneia progressiva aos grandes esforços e perda de cerca de 10kg.\n\nEvolução de 2 meses. Nega febre no período. Ao exame físico, chamava a atenção face pletórica e\nedemaciada. A radiografia simples de tórax evidenciou volumoso alargamento de mediastino\nsuperior, sendo indicada a tomografia computadorizada. Esta evidenciou massa sólida em\nmediastino superior e anterior, com infiltração de hilo pulmonar e grandes vasos da base cardíaca.\nSobre o caso acima, assinale a alternativa CORRETA:","options":{"A":"O edema de face e pletora presentes sugerem constricção tumoral do arco da aorta, conferindo\nprognóstico ruim ao caso.","B":"A localização da massa tumoral à tomografia e a idade do paciente sugerem o diagnóstico de\nlinfoma, estando indicada a biópsia da massa tumoral que pode ser realizada por toracoscopia ou\nmediastinoscopia.","C":"Os sintomas descritos pelo paciente e sua faixa etária são altamente compatíveis com miastenia\ngravis, o que sugere o timoma como\nprincipal hipótese diagnóstica para a massa mediastinal.","D":"A punção por agulha guiada por tomografia é contraindicada nestes casos devido ao alto risco\nde perfuração de grandes vasos da base cardíaca e a baixa quantidade de tecido extraído para\nanálise."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-327225","number":"327225","sourceNumber":"327225","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Um adolescente compareceu ao ambulatório de neurologia acompanhado de sua mãe.\nO motivo da consulta foi estar apresentando\nvários episódios de \"desligamentos\" que duram\naproximadamente de 5 a 10 segundos, o paciente fica com o olhar fixo, perde contato com o meio\npor alguns segundos e muitas vezes não é percebida pelo paciente e sim pelos familiares e/ou\nprofessores. Geralmente são precipitadas por hiperventilação durante aula de artes marciais. Qual\no diagnóstico clínico mais provável para o paciente?","options":{"A":"Crises focais disperceptivas não motora.","B":"Crises focais perceptivas não motora.","C":"Crises generalizadas não motoras.","D":"Crise focal evoluindo para tônico-clônica bilateral."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-327226","number":"327226","sourceNumber":"327226","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Um motorista de Uber 68 anos de idade, começou a apresentar sinais e sintomas\nneurológicos de caráter progressivo início do\nquadro há 18 meses. O que mais chamou sua\natenção foram diminuição das forças principalmente em membros superiores com músculos tensos\ne rígidos, atrofia em mãos, contrações musculares nos braços e língua, dificuldade para deglutição\ne fala anasalada. Qual o diagnóstico provável?","options":{"A":"Esclerose múltipla","B":"Esclerose lateral amiotrófica (ELA)","C":"Encefalomielite disseminada aguda (ADEM)","D":"Miastenia gravis"},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-298197","number":"298197","sourceNumber":"298197","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Um motorista de ônibus de 35 anos iniciou quadro agudo de fraqueza muscular\ngeneralizada necessitando de internação hospitalar.\nRelata dormência nas mãos e formigamento\ndos dedos dos pés até um pouco acima dos joelhos. O exame neurológico mostrou função mental\npreservada, diparesia facial, fraqueza distal mais que proximal nas extremidades inferiores e\nfraqueza sutil nas mãos, os reflexos profundos estavam ausentes, sensibilidade superficial e\nprofunda preservadas. Ele se lembra de ter uma doença viral há uma semana. Qual o diagnóstico\nprovável?","options":{"A":"Mielite transversa.","B":"Esclerose múltipla.","C":"Síndrome de Guillain-Barré.","D":"Miastenia gravis."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-286713","number":"286713","sourceNumber":"286713","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Um homem de 17 anos apresenta 10 dias de parestesias progressivas nos pés com\nacometimento ascendente atingindo as mãos e fraqueza nas pernas duas noites antes da\ninternação. Tem história de quadro diarreico 2 semanas antes das queixas neurológicas. No exame\nneurológico, apresenta paraparesia flácida arreflexa. Função respiratória ainda normal. O estado\nmental é normal. Os achados mais prováveis na análise do liquor são:","options":{"A":"Nível elevado de proteína.","B":"Contagem elevada de leucócitos.","C":"Pressão de abertura elevada.","D":"Bandas oligoclonais."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-208346","number":"208346","sourceNumber":"208346","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Uma criança de 8 anos de idade, foi avaliada com queixas de baixo rendimento escolar.\nA professora relatou que o aluno apresentava\nparada súbita e transitória da atividade, com duração\nde poucos segundos, acompanhada de episódios de automatismos orais e piscamento, sem\napresentar quedas. O Eletroencefalograma (EEG) mostrou complexos de espículas-onda\ngeneralizados a 3 Hz, com duração maior ou igual a 3 segundos. É característico de:","options":{"A":"Crises mioclônica-atônicas.","B":"Crises mioclônicas.","C":"Crises de ausência típica.","D":"Parada comportamental."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-176016","number":"176016","sourceNumber":"176016","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Um paciente de 30 anos de idade apresentando ptose palpebral e diplopia flutuante\ndurante o dia recebeu o diagnóstico de\nmiastenia gravis. Qual o neurotransmissor envolvido na sua\nfisiopatologia?","options":{"A":"Dopamina.","B":"Acetilcolina.","C":"Serotonina.","D":"Glutamato"},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-151862","number":"151862","sourceNumber":"151862","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Paciente de 26 anos, com diagnóstico de miastenia grave, foi internado com\ninsuficiência respiratória aguda, sendo submetido a\ntratamento com plasmaférese. Em relação à\nmiastenia grave, marque a alternativa CORRETA:","options":{"A":"Ocorre um distúrbio pré-sináptico.","B":"Ocorre baixa liberação de acetilcolina.","C":"Ocorre aumento dos receptores de acetilcolina.","D":"Ocorre redução dos receptores de acetilcolina."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-151967","number":"151967","sourceNumber":"151967","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Lactente com 4 meses, evoluiu com crise convulsiva, apatia, irritabilidade, vômito,\nanemia hipocrômica, oxaluria e falha no desenvolvimento. Neste caso, qual teste terapêutico\nindicado?","options":{"A":"Riboflavina.","B":"Tiamina (81).","C":"Piridoxina (B6).","D":"Cobalamina (812)."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-80980","number":"80980","sourceNumber":"80980","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Em relação à crise epiléptica, marque a alternativa INCORRETA:","options":{"A":"A Ressonância Nuclear Magnética (RM) do cérebro complementa o estudo eletroencefalográfico,\ndevendo ser realizada em todos os pacientes\nmaiores de 18 anos de idade com suspeita de\nepilepsia.","B":"Na investigação das crises, a punção lombar é mandatória se houver suspeita de meningite ou\nencefalite.","C":"As drogas empregadas no tratamento da epilepsia podem levar à osteopenia ou à osteomalacia,\ne, com isso, aumentar o risco de fraturas\nósseas.","D":"História prévia de neoplasia de mama pode sugerir necessidades de estudo de imagem cerebral,\npelo risco aumentado de metástases servirem\nde focos convulsivos.","E":"No tratamento das crises, a falta de resposta a uma determinada droga anticonvulsivante, como\na carbamazepina ou a fenitoína, impede a resposta\na outra droga, sendo recomendadas outras\nformas de tratamento."},"answer":"E","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-80925","number":"80925","sourceNumber":"80925","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Homem, 43 anos, alcoolista crônico foi encontrado com rebaixamento do estado de\nconsciência e levado ao Pronto-Socorro pelo Resgate. Ainda na ambulância, recebeu 50 ml de\nglicose a 50% endovenoso, com melhora do quadro, persistindo alguma confusão. Como se\nencontrava febril, foi necessário internação para investigação melhor do quadro. No dia seguinte, o\npaciente agravou o estado de confusão mental, agora com nistagmo multidirecional, paralisia do VI\npar craniano à esquerda e ataxia cerebelar. Assinale a alternativa CORRETA:","options":{"A":"Provável quadro de hematoma subdural crônico.","B":"O quadro pode ter agravado por se tratar de Meningite bacteriana.","C":"O agravo se deve à Síndrome de Wernicke, decorrente da deficiência de tiamina.","D":"É quadro típico de demência alcoólica.","E":"A causa do agravo pode ser devida à mielinóllise pontina central."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-87401","number":"87401","sourceNumber":"87401","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"De acordo com a IV Diretriz Brasileira sobre Dislipidemia e Prevenção da Aterosclerose,\npaciente com colesterol total = 248 mg/dl,\nLDLc = 167 mg/dl; HDLc = 40 mg/dl e triglicerídeos = 412\nmg/dl, além de dieta e atividade física, qual o tratamento medicamentoso de escolha?","options":{"A":"Ezetimibe","B":"Fibrato.","C":"Ácido nicotínico.","D":"Fibrato + Estatina.","E":"Estatina."},"answer":"E","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-81968","number":"81968","sourceNumber":"81968","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Paciente do sexo masculino, 58 anos, obeso, com glicemia de jejum de 145 mg/dl\n(repetida e confirmada) e PA 160/90 mmHg. Vem à consulta pela primeira vez e não está\nmedicado. Em relação à conduta, assinale a INCORRETA.","options":{"A":"Solicitar o teste oral de tolerância à glicose (TOTG).","B":"Orientar dieta e atividade física.","C":"Iniciar Metformina e tratamento para hipertensão.","D":"Solicitar microalbuminúria e creatinina em amostra urinária de jejum.","E":"Solicitar exame de fundo de olho para avaliar alterações vasculares na retina."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-60947","number":"60947","sourceNumber":"60947","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Para a Organização Pan-Americana de Saúde (OPAS), o envelhecimento é \"um\nprocesso sequencial, individual, acumulativo,\nirreversível, universal, não patológico, de deterioração\nde um organismo maduro\". (BRASIL, 2006). Este é o processo natural (Senescência), mas as\ncondições patológicas (Senilidade) podem requerer assistência. É um exemplo de Senilidade:","options":{"A":"Algum grau de declínio da acuidade auditiva mais frequentemente a presbiacusia.","B":"Incapacidade de manter o controle das necessidades fisiológicas, principalmente, incontinência\nurinária.","C":"Mudança na quantidade e distribuição do tecido adiposo subcutâneo.","D":"Redução na amplitude de movimentos tanto dos braços quanto das pernas, o que modifica a\nmarcha.","E":"A diminuição da altura pela compressão dos corpos vertebrais, mudança nos discos\nintervertebrais e perda de tônus muscular."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-34293","number":"34293","sourceNumber":"34293","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Desde o século 16 foram identificadas três pandemias por século associadas ao vírus\nInfluenzae, com intervalos de 10 a 50 anos entre elas (Vademecum simplificado | Curso de\nMultiplicadores Influenza pandêmica (H1N1) 2009\\Ministério da Saúde\\2010). Em relação à última\npandemia pelo vírus H1N1, podemos afirmar, EXCETO:","options":{"A":"É considerado Caso Suspeito de síndrome gripal a pessoa com tosse ou odinofagia. Febre\n(=37,5°), cefaleia ou mialgia\\artralgia ou dispneia.","B":"Toda a população pode ser vacinada contra o Vírus Pandêmico (H1N1) 2009 mas a prioridade é\npara as gestantes e portadores de doenças crônicas.","C":"Os efeitos adversos mais comuns da vacina contra o Virus Pandêmico (H1N1) 2009 são\nartralgia, cefaleia, fadiga e dor no local da aplicação.","D":"A quimioprofilaxia contra H1N1 está indicada para profissionais de saúde expostos ao vírus em\nuso de Equipamentos de proteção Individual\n(EPI).","E":"Na presença de sinais de alerta (como taquipneia, desidratação, alteração de consciência,\nconvulsões) o paciente deve ser encaminhado ao serviço hospitalar."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-26667","number":"26667","sourceNumber":"26667","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Cláudio tem 42 anos, está obeso, com a pressão arterial de 150 x 100 mmHg. Vem ao\nconsultório por apresentar uma síndrome gripal há 10 dias. É tabagista desde os 16 anos. Fuma 02\nmaços/dia e acende o primeiro cigarro logo após acordar. Quando perguntado sobre o desejo de\nparar de fumar, diz que já tentou, mas sem sucesso. Deseja tentar de novo. Você o orienta a,\nEXCETO:","options":{"A":"fazer terapia cognitivo-comportamental com o psicólogo da unidade de referência","B":"terapia medicamentosa pode ser feita com medicamentos não nicotínicos ou com a reposição de\nnicotina, mas não com ambos","C":"pode usar medicação para auxiliar a parar de fumar, desde que sua pressão arterial esteja\ncontrolada","D":"se tiver úlcera péptica não deve usar goma de mascar e nicotina","E":"vir em consultas semanais na unidade de saúde da família para aconselhamento durante um\nmês, o que aumenta a chance de abandono do fumo."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-7515","number":"7515","sourceNumber":"7515","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Em relação aos pacientes com infecção pelo HIV, assinale a alternativa INCORRETA:","options":{"A":"principal neoplasia oportunista é o linfoma cerebral primário.","B":"a polineuropatia mais comumente encontrada neles é a polineuropatia sensorial distal associada\nao HIV.","C":"pneumonia decorrente de pseudomonas aeruginosa ou Staphylococcus aureus, ocorrem\nhabitualmente com CD4<100 células/ml.","D":"o antígeno criptocócico sérico (AGCR) é um teste extremamente sensível para a presença de\ncriptococcemia e meningite criptocócica, mas pode ser negativo em pacientes infectados por HIV\ncom pneumonia criptocócica isolada.","E":"a tireoide é a glândula endócrina mais acometida e fica alterada durante todo o curso da doença\npelo HIV."},"answer":"E","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-284574","number":"284574","sourceNumber":"284574","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Mulher, 20 anos de idade, estava acompanhada da mãe no metrô quando apresentou\nperda da consciência, seguida de rigidez\nmuscular, abalos musculares difusos e perda\nesfincteriana. A equipe do metrô iniciou rapidamente os primeiros-socorros, colocando algo macio\nsob a cabeça da paciente até cessarem os abalos, que duraram cerca de um minuto. A mãe ficou\nbastante assustada e relatou que a paciente era portadora de diabetes mellitus tipo 1. Nega outras\ncomorbidades. Nunca havia apresentado quadro semelhante. Neste momento, a paciente\nencontra-se ainda inconsciente, com ventilação espontânea. Indique a alternativa mais adequada\nem relação ao quadro.","options":{"A":"A etiologia mais provável nesse caso é hiperglicemia.","B":"O quadro, obrigatoriamente, envolveu ambos os hemisférios cerebrais.","C":"Neste momento, provavelmente, a paciente se encontra em uma crise de ausência.","D":"O \"grito epiléptico\" ocorre durante a fase clônica da crise."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-284575","number":"284575","sourceNumber":"284575","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Mulher, 20 anos de idade, estava acompanhada da mãe no metrô quando apresentou\nperda da consciência, seguida de rigidez\nmuscular, abalos musculares difusos e perda\nesfincteriana. A equipe do metrô iniciou rapidamente os primeiros-socorros, colocando algo macio\nsob a cabeça da paciente até cessarem os abalos, que duraram cerca de um minuto. A mãe ficou\nbastante assustada e relatou que a paciente era portadora de diabetes mellitus tipo 1. Nega outras\ncomorbidades. Nunca havia apresentado quadro semelhante. Neste momento, a paciente\nencontra-se ainda inconsciente, com ventilação espontânea. Indique a principal conduta que deve\nser tomada nesse momento.","options":{"A":"Auxiliar a ventilação através de dispositivo bolsa-válvula-máscara.","B":"Colocar água com açúcar ou líquido adocicado sob a língua da paciente.","C":"Colocar a paciente lateralizada em posição de recuperação.","D":"Encaminhar a paciente para o Pronto Socorro."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-62822","number":"62822","sourceNumber":"62822","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Paciente, oito anos de idade, é internada com um quadro súbito de náuseas, vômitos,\ndiarreia e dor abdominal, procurou serviço de urgência, sendo-lhe prescrito antiemético e\nhidratação oral, porém não melhorou e passou a apresentar cefaleia, vertigem e tontura, seguidas\nde visão turva, ptose palpebral, diplopia, disfagia, disartria, boca seca e progrediu para paralisia\nflácida motora, claramente descendente, associada a comprometimento autônomo disseminado.\nEstado de consciência preservado. Nos antecedentes, chama atenção o histórico de alimentação\ncom conservas caseiras de carne suína. O diagnóstico mais provável é de:","options":{"A":"Diarreia aguda por E. coli.","B":"Síndrome de Guillain-Barré.","C":"Diarreia por rotavírus.","D":"Botulismo.","E":"Diarreia viral."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-49290","number":"49290","sourceNumber":"49290","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Homem, 25 anos de idade, vem há um mês com cãibras e fadiga muscular, as quais\natribui a início de atividade física.\nRelata níveis elevados de PA em exames anteriores. Tem história\nfamiliar de hipertensão e pai faleceu aos 42 anos de idade de AVC hemorrágico. No exame,\napresenta IMC: 25, mucosas coradas, hidratado, PA: 160 x 100 mmHg, sem variação entre os\nmembros. Ausculta cardíaca e respiratória sem alterações, abdome sem visceromegalias e\nextremidades sem edemas, sem sopros à ausculta. Traz exames: hemograma normal, creatinina:\n0,9 mg/dl, ureia: 29 mg/dl. A melhor conduta inicial para esse paciente é dosar:","options":{"A":"Cortisol sérico e urinário;","B":"Potássio sérico e urinário;","C":"Metanefrinas na urina;","D":"Sódio em urina de 24 horas;","E":"ACTH sérico."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-49407","number":"49407","sourceNumber":"49407","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Homem, 57 anos de idade, tabagista desde os 13 anos de idade, deseja deixar de\nfumar. Consome 20 cigarros/dia, sendo o\nprimeiro antes do café da manhã. Tem sobrepeso. Já\ntentou parar de fumar três vezes, tendo passado até três semanas em abstinência, mas retornou\nposteriormente. Não é etilista, nem tem comorbidade psiquiátrica. Nega uso de drogas. Quanto ao\ntratamento desse paciente, é correto afirmar:","options":{"A":"As tentativas prévias indicam pior prognóstico quanto à adesão ao tratamento.","B":"O tratamento com reposição de nicotina é mais eficaz que com antidepressivos.","C":"O uso de bupropiona deve iniciar antes da data prevista para a parada do tabagismo.","D":"O ganho ponderal associado ao tratamento aumenta os riscos cardiovasculares.","E":"O tratamento farmacológico não é mais eficaz que o aconselhamento psicológico."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-215586","number":"215586","sourceNumber":"215586","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Assinale a alternativa CORRETA.","options":{"A":"As alterações da parede torácica, como a escoliose idiopática e o nanismo, não levam à falência\nrespiratória.","B":"As patologias que cursam com falência respiratória por lesão de parênquima pulmonar\ncostumam estar isoladas e nunca se associam a doenças obstrutivas das vias aéreas.","C":"A hipertonia muscular com disfunção da parede torácica e a alteração da deglutição são\nmecanismos que levam pacientes com quadros neurológicos à falência respiratória crônica.","D":"As doenças neuromusculares cursam somente com hipoventilação alveolar."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-215602","number":"215602","sourceNumber":"215602","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Sobre a falência da musculatura respiratória, é CORRETO afirmar que as doenças\nneuromusculares:","options":{"A":"Fazem com que os músculos respiratórios não sejam capazes de gerar ventilação alveolar\nadequada, ocasionando insuficiência respiratória crônica.","B":"Têm quadro clínico agudo.","C":"Estão relacionadas com disfunções do parênquima pulmonar.","D":"Estão relacionadas com erros inatos do metabolismo, como doença de Leigh e deficiência de\ncarnitina."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-157650","number":"157650","sourceNumber":"157650","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Em relação à osteoporose, marque a opção em que a afirmativa esteja INCORRETA:","options":{"A":"A perda óssea se acelera com a queda nos níveis de estrogênio.","B":"O uso de estrogênio reduz a perda óssea, mas não diminui o risco de fraturas.","C":"A partir dos 40 anos a taxa de reabsorção óssea passa a ser maior que a taxa de formação\nóssea.","D":"A reposição de cálcio e vitamina D pode ser benéfica, mas isoladamente tem pouco efeito na\nprevenção de osteoporose."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-134741","number":"134741","sourceNumber":"134741","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Entre as situações listadas abaixo sobre a profilaxia da raiva humana, assinale a\nCORRETA:","options":{"A":"Alguns roedores e lagomorfos são considerados como de baixo risco para a transmissão da\nraiva e, por isso, não é necessário indicar esquema profilático da raiva em caso de acidentes\ncausados por esses animais.","B":"A profilaxia da raiva humana, com uso de soro e vacina, deve ser indicada nos casos de contato\ncom o morcego.","C":"A vacina contra a raiva elaborada em cultura de células não tem contraindicação (gravidez, em\nlactação, doença intercorrente ou outros tratamentos), devido à gravidade da doença, que\napresenta letalidade de aproximadamente 100%.","D":"Todas as situações anteriores estão corretas."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-321312","number":"321312","sourceNumber":"321312","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Homem de 25 anos, portador de epilepsia, é trazido ao departamento de emergência\ncom convulsão tônico- clônica generalizada.\nForam puncionados dois acessos venosos periféricos\ncalibrosos, de imediato, coletados exames laboratoriais de urgência, instalada monitorização e\nadministrados diazepam e fenitoína. Glicemia capilar 110mg/dL. O quadro convulsivo persiste,\nsendo administrada nova dose de diazepam endovenosa. Considerando o período de crise superior\na 30 minutos e a refratariedade às medidas instituídas até o momento, qual a próxima conduta?","options":{"A":"Prescrever fenobarbital endovenoso.","B":"Administrar uma dose adicional de diazepam.","C":"Iniciar sedação e proceder à intubação orotraqueal.","D":"Infundir fenitoína intravenosa em dose inferior à primeira."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-321315","number":"321315","sourceNumber":"321315","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Homem de 28 anos é admitido na emergência com quadro de fraqueza muscular\nprogressiva ascendente há 3 semanas. Refere ainda\nparestesias discretas nos dedos das mãos.\nApresenta ausência de reflexos aquileu e patelar bilateralmente. Realizada punção lombar, que\nevidenciou proteinorraquia de 88mg/dL e 3 células/mm3 . Considerando a principal hipótese\ndiagnóstica, qual o tratamento de escolha?","options":{"A":"Plasmaférese.","B":"Reposição de vitamina B12.","C":"Pulsoterapia com metilprednisolona.","D":"Antibioticoterapia de amplo espectro."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-321329","number":"321329","sourceNumber":"321329","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Lactente, 1 ano, previamente hígido, é trazido à emergência pelos pais devido à crise\nconvulsiva tônico-clônica generalizada. Genitora relata que a criança iniciou a crise logo após\ndespertar, aparentemente, sem nenhum fator desencadeante. Nega febre, trauma, uso de\nmedicações ou histórico de infecção recente. À admissão, paciente apresenta movimentos\n\ntônico-clônicos de membros e sialorreia importante, com os seguintes parâmetros: FC - 140bpm;\nFR - 40irpm; SatO2 - 96% (sob máscara de\noxigênio); Temperatura axilar - 36,5°C; glicemia capilar\n\n- 86 mg/dL. Qual das seguintes alternativas é a farmacoterapia mais apropriada nesse momento?","options":{"A":"Fenitoína, dose: 5mg/Kg, via endovenosa.","B":"Fenobarbital, dose: 5mg/Kg, via endovenosa.","C":"Diazepam, dose: 0,5mg/Kg, via intramuscular.","D":"Midazolam, dose: 0,2mg/Kg, via intramuscular."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-292844","number":"292844","sourceNumber":"292844","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Uma criança de sete anos de idade chega à sala de emergência com história de\ninfecção intestinal há 2 semanas, e que após a\nmelhora clínica passou a apresentar fraqueza\nmuscular em ambos os membros inferiores acompanhados de dor e parestesia bem como de\ndificuldades de deglutição e constipação intestinal. Os reflexos tendinosos estavam ausentes. Qual\na hipótese diagnóstica mais provável?","options":{"A":"Esclerose múltipla.","B":"Encefalite herpética.","C":"Polirradiculoneurite aguda.","D":"Encefalomielite disseminada aguda."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-259747","number":"259747","sourceNumber":"259747","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Uma criança de 36 meses de idade chega no ambulatório com seus familiares uma\nsemana após ter tido uma crise convulsiva\nfebril. Qual das alternativas contém uma situação de\nrisco para recorrência das convulsões?","options":{"A":"O fato de a convulsão ter ocorrido com temperatura acima de 39 graus.","B":"O fato de a convulsão ter ocorrido nas primeiras 12 horas do surgimento da febre.","C":"O fato de a convulsão ter sido desencadeada após vacinação da criança de rotina.","D":"O fato de a convulsão ter sido classificada como generalizada e com duração inferior a 15\nminutos."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-234040","number":"234040","sourceNumber":"234040","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Homem, 40 anos, com antecedente de epilepsia em uso irregular de ácido valproico 1\ngrama ao dia, sem tomar a medicação há 1 semana, é trazido pelo SAMU por apresentar episódios\nde convulsão tônico-clônicos generalizados há 30 minutos. Nesse período, o paciente já\napresentou 3 episódios com duração aproximada de 5 minutos cada, sem recobrar a consciência.\nApresentou, durante o transporte, mais um episódio convulsivo e foi medicado pelo médico do\nSAMU 2 vezes com diazepam 10 mg endovenoso. Na chegada, o paciente apresenta nova crise\nconvulsiva que persiste até o início de sua avaliação (aproximadamente 5 minutos). Ao exame,\npulso: 90 batimentos por minuto, pressão arterial de 160 x 90 mmHg. Glicemia capilar de 100 mg/dl.\nPeso aproximado de 80 kg. Após a monitorização e suporte clínico, qual a melhor conduta\nfarmacológica?","options":{"A":"Diazepam 10 mg endovenosa.","B":"Fenitoína 1.600 mg endovenosa lenta.","C":"Acido valproico 2 gramas via sonda.","D":"Fenobarbital 1.600 mg endovenoso lento."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-234062","number":"234062","sourceNumber":"234062","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Criança de 6 anos de idade, sexo feminino, é levada pela mãe ao pediatra para\navaliação de comportamento estranho que vem\napresentando há alguns dias. Previamente hígida,\nna escola foi chamado atenção que a criança estava desatenta nas aulas. Mãe começou a\nperceber que a criança estava apresentando crises abruptas que duravam em média de 15\nsegundos, várias vezes ao dia onde ela apresentava olhar fixo, era chamada e não respondia,\ndeixava objetos que estavam na mão cair do chão, apresentando comprometimento da consciência\ncom interrupção da atividade que estava fazendo no momento. Tem história familiar de convulsão.\nO EEG mostrou descargas de espícula, onda lenta de projeção difusa, bilateral que não se\nfragmentam e se acentuam durante a hiperventilação da criança. Diante do quadro clínico exposto,\nqual o possível diagnóstico da criança?","options":{"A":"Epilepsia de Panayiotopoulos.","B":"Epilepsia ausência na infância.","C":"Epilepsia mioclônica da infância.","D":"Epilepsia com pontas centrotemporais."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-199677","number":"199677","sourceNumber":"199677","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Na emergência, os pais relatam que sua filha de três anos de idade apresentou\nmovimentos anormais nos membros superiores e\ninferiores, há cerca de 30 minutos, no domicílio.\nQue sinais sugerem ao médico assistente que se trata de um evento convulsivo?","options":{"A":"Movimentos tônicos, clônicos ou tônico-clônicos na ausência de perda da consciência.","B":"Presença de deficit neurológicos focais na ausência de alteração prolongada da consciência.","C":"Perda de consciência e perda do controle esfinctérico na ausência de reflexos de autoproteção.","D":"Presença de aura, movimentos tônicos, clônicos ou tônico-clônicos na ausência de movimentos\nanômalos dos olhos."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-150861","number":"150861","sourceNumber":"150861","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Homem, 36 anos, alcoolista crônico e com história prévia de epilepsia, foi trazido à\nemergência com quadro de convulsão tônico-clônica generalizada. Esposa relata que o paciente\ningeriu bebida alcoólica durante 3 dias seguidos e nesse período não tomou seus medicamentos.\nSegundo o socorrista que o trouxe, o paciente apresenta crises seguidas há 15 minutos. Na\nemergência, foi medicado com diazepam 10 mg, intravenoso, porém a crise não cedeu, mesmo\ncom a repetição da dose. Qual a próxima conduta a ser tomada?","options":{"A":"Fenitoína 20 mg/kg, intravenoso, na sala de emergência.","B":"Midazolam 0,2 mg/kg, intravenoso, na sala de emergência.","C":"Propofol 2 mg/kg, intravenoso, na unidade de terapia intensiva.","D":"Fenobarbital 10 mg/kg, intravenoso, na unidade de terapia intensiva."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-150881","number":"150881","sourceNumber":"150881","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Homem, 47 anos, hipertenso, tabagista, habitante de zona rural, procurou atendimento\nna Unidade Básica de Saúde angustiado, pois há 24\nhoras acordou com dor periauricular a\nesquerda e desde então vem observando desconforto com ruídos altos no ouvido esquerdo.\n\nObservou a face esquerda \"caída\" e apresenta dificuldade de se alimentar, com queda de alimentos\ne saliva pelo canto esquerdo da boca. Ao exame\nfísico, apresenta fraqueza acentuada na face\nesquerda, incluindo a região frontal e apagamento do sulco nasolabial esquerdo (vide figura). PA\n150 x 90 mmHg. Otoscopia e demais itens do exame físico estavam normais. (VER IMAGEM) Qual\na conduta adequada?","options":{"A":"Solicitar avaliação e acompanhamento fisioterápico com seguimento regular na Unidade Básica\nde Saúde, até melhora do quadro.","B":"Referenciar o paciente para avaliação tomográfica no ?Centro de referência, para o diagnóstico\ne tratamento do AVC? mais próximo.","C":"Agendar retorno em 24h para reavaliação, orientação de manter níveis pressóricos e\nencaminhar ao serviço de neurologia de modo eletivo.","D":"Encaminhar o paciente à Unidade de Pronto-Atendimento para avaliações do estado neurológico\na cada hora, e definição de conduta após 24h."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":["question_bank/media/medcurso/med-clinica-medica-med-clm-13/150881.png"],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-126932","number":"126932","sourceNumber":"126932","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Paciente feminina, 30 anos, há dois meses vem notando dificuldade de abrir os\nolhos, principalmente ao final do dia, que se associou à dificuldade de mastigação com\nregurgitação nasal frequente e, mais recentemente, disfagia e fadiga. Ao exame, nota-se fraqueza\nmuscular em cintura pélvica, mais pronunciada à esquerda, e reflexos preservados. Na\ninvestigação, a pesquisa de anticorpos antirreceptores de acetilcolina foi negativa. Nesse\ncontexto, qual exame laboratorial poderia confirmar o diagnóstico mais provável?","options":{"A":"Pesquisa de anticorpo anti-Jo-1.","B":"Pesquisa de anticorpo anti-GM1.","C":"Pesquisa de anticorpo anti-MuSK.","D":"Pesquisa de anticorpo anti-GQ1b."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-102118","number":"102118","sourceNumber":"102118","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Paciente do sexo masculino, 50 anos, hígido, PA = 120x75 mmHg, sem fatores de risco\ncardiovascular na história clínica, vem à Unidade de Saúde pedindo para realizar um checkup. Que\nexames laboratoriais o médico de família deverá solicitar, para rastreamento, no paciente em\nquestão?","options":{"A":"PSA Total e Pesquisa de sangue oculto nas fezes.","B":"Glicemia de jejum, PSA Total e Pesquisa de sangue oculto nas fezes.","C":"Dosagem de lipídios séricos e Pesquisa de sangue oculto nas fezes.","D":"Dosagem de lipídios séricos, PSA total e Pesquisa de sangue oculto nas fezes."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-102124","number":"102124","sourceNumber":"102124","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Médico atende paciente de 74 anos. A idosa refere perda involuntária de urina há 6\nmeses e isso vem causando incômodo e, por\nessa razão, prefere ficar em casa. Relata ter caído à\nnoite, há uma semana, resultando em um hematoma no joelho direito. Qual a conduta imediata\nmais adequada para essa paciente?","options":{"A":"Avaliar: depressão, mecanismo de incontinência urinária e risco de queda.","B":"Deverá: prescrever alendronato de sódio 70 mg, semanal, e carbonato de cálcio 1,5 gramas\ndiária.","C":"Iniciar: terapia de reposição hormonal, após realização de mamografia e de ultrassonografia\ntransvaginal.","D":"Prescrever: carbonato de cálcio 1,5 gramas diária, fazer avaliação ambiental e solicitar\ndensitometria\n\nóssea."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-102130","number":"102130","sourceNumber":"102130","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Paciente de 52 anos, masculino, tabagista, sedentário, bebedor problema, procura\natendimento com seu médico de família para\nconsulta de rotina. Ao exame, pressão arterial 120/75\nmmHg. Para qual situação abaixo o médico deve realizar rastreamento?","options":{"A":"Diabetes.","B":"Obesidade.","C":"Osteoporose.","D":"Câncer de próstata."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-81274","number":"81274","sourceNumber":"81274","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Mulher de 50 anos queixa-se de lesões em membros inferiores (VER IMAGEM) de\ninício há duas semanas, associadas à febre\ndiária de 38°C ao fim das tardes, e dores em joelhos e\ntornozelos. Refere ter concluído tratamento de hanseníase há 1 ano (fez uso de poliquimioterapia\npor 12 meses) e não teve problemas de saúde desde então. Não faz uso de medicações ou de\nsubstâncias ilícitas. Qual dos tratamentos abaixo é o mais recomendado nesse caso?","options":{"A":"Dapsona 100 mg/dia.","B":"Prednisona 10 mg/dia.","C":"Talidomida 300 mg/dia.","D":"Rifampicina 600 mg/dia + dapsona 100 mg/dia."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":["question_bank/media/medcurso/med-clinica-medica-med-clm-13/81274.png"],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-81292","number":"81292","sourceNumber":"81292","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Paciente masculino, 72 anos, sem comorbidades, vem à consulta de rotina. Quando\nquestionado, refere que apresentou uma queda da própria altura há 4 meses. Sem outros episódios\nprévios ou posteriores; sem outras queixas. Não usa medicações. Marcha e equilíbrio normais.\n\nQual a recomendação mais adequada para prevenir queda nesse paciente?","options":{"A":"Suplementar vitamina D.","B":"Indicar uso de sapato ortopédico.","C":"Recomendar programa de exercício.","D":"Encaminhar para avaliação oftalmológica."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-81319","number":"81319","sourceNumber":"81319","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Paciente de 82 anos, restrito ao leito, recebe visita domiciliar de seu médico da atenção\nprimária. Paciente é hipertenso, portador de insuficiência cardíaca congestiva, fibrilação atrial\ncrônica e apresenta sequela motora de acidente vascular cerebral. Estava em uso de enalapril: 20\nmg/dia; carvedilol: 50 mg/dia; ácido acetilsalicílico: 100 mg/dia; hidroclorotiazida: 25 mg/dia;\nmetildopa: 500 mg/dia e digoxina: 0,25 mg/dia. Como o médico deverá fazer o ajuste na\nmedicação, considerando o melhor benefício para esse paciente e diminuição do risco de\niatrogenias?","options":{"A":"Reduzir os intervalos entre as doses dos medicamentos para diminuir a probabilidade de efeitos\nadversos.","B":"Solicitar avaliação da função hepática desse paciente semestralmente, devido ao risco de\nintoxicação digitálica.","C":"Reduzir a dose da digoxina para 0,125 mg e substituir diurético tiazídico, ante risco elevado de\nintoxicação digitálica.","D":"Suspender a metildopa, visto que aumenta o número de receptores locais para medicações\nadrenérgicas, podendo causar hipotensão importante na associação dessas drogas."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-65704","number":"65704","sourceNumber":"65704","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Adulto de 28 anos, sexo masculino, pedreiro, residente em Fortaleza, sem\ncomorbidades, planeja viajar para o interior da\nBahia (Juazeiro da Bahia), em fevereiro de 2013,\npara visitar familiares. Interessado em se proteger contra doenças imunopreveníveis, comparece a\num Centro de Saúde da Família. Não possui cartão de vacinação e não lembra das vacinas\ntomadas no passado. Neste caso, de acordo com o Calendário Básico do Programa Nacional de\nVacinação, a recomendação mais CORRETA é:","options":{"A":"Vacinar contra influenza A (H1N1) pandêmica.","B":"Iniciar esquema de 2 doses de vacina contra hepatite A.","C":"Não há indicação de vacinação contra sarampo e rubéola.","D":"Fazer reforço com dose única de vacina contra difteria e tétano (dT).","E":"Não há necessidade de vacinar contra febre amarela, uma vez que esta cidade se localiza em\nárea indene."},"answer":"E","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-65699","number":"65699","sourceNumber":"65699","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Médico de família e comunidade realiza visita domiciliar a um homem de 70 anos, que\nvive com a esposa de 72 anos e uma filha. A filha referiu preocupação, pois o pai caiu quatro vezes\nno último mês e na última queda cortou a região dos supercílios. Neste episódio, o paciente caiu da\nprópria altura à noite quando ia ao banheiro. O mesmo é independente para as atividades de vida\ndiária e dependente para as atividades de vida instrumentais. É hipertenso e possui insuficiência\nrenal crônica. Faz uso de furosemida 40 mg às 16h e enalapril 20 mg às 7h. Pratica atividade física\nduas vezes por semana. Em relação às orientações para prevenção de quedas deste senhor,\nassinale a alternativa CORRETA:","options":{"A":"A furosemida deve ser suspensa, pois aumenta o risco de quedas.","B":"O uso de protetores pélvicos não tem indicação, pois não diminuem o risco de fraturas de colo\nfemoral.","C":"A atividade física aumenta o risco de quedas em idosos dependentes para as atividades de vida\ninstrumentais.","D":"O fato do indivíduo não ter sido indagado sobre a perda de consciência mantém a hipótese\ndiagnóstica de síncope.","E":"Deve-se recomendar restrição das atividades para reduzir o risco de quedas, pois o risco de\nfraturas é superior à necessidade e ao desejo de independência."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-51178","number":"51178","sourceNumber":"51178","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Mulher de 82 anos comparece ao consultório com quadro progressivo de perda de\npeso, fraqueza, lentidão motora e dificuldades em atividades de vida diária, como banho, há três\nmeses, sem outras queixas. Refere osteoporose e hipertensão bem controlada. Exame físico:\natrofia muscular proximal. Exames: glicemia de jejum 114 mg/dl, velocidade de\nhemossedimentação 40 mm/h e ausência de anemia. Qual o diagnóstico mais provável?","options":{"A":"Doença de Parkinson.","B":"Doença de Alzheimer.","C":"Polimialgia reumática.","D":"Síndrome da fragilidade do idoso."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-51232","number":"51232","sourceNumber":"51232","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Homem de 40 anos é avaliado em departamento de emergência por desorientação.\nFamiliares referem que ele ingere álcool todos os\ndias (de 8 a 10 doses de cachaça), há mais de 5\nanos. Na manhã do dia anterior, foi trazido a este mesmo hospital por rebaixamento do nível de\nconsciência após 5 dias consecutivos de libação etílica, sendo constatada hipoglicemia, que foi\nrevertida com 50 g de glicose endovenosa; após recobrar os sentidos, o paciente solicitou alta.\n\nHoje, ele apresenta flutuação do nível de consciência, com episódios de agitação e agressividade.\nAo exame físico, verifica-se nistagmo\nhorizontal e importante ataxia. Não houve ingestão de álcool\nentre os dois atendimentos. Qual substância deve ser imediatamente administrada nesse paciente?","options":{"A":"Tiamina.","B":"Cianocobalamina.","C":"Benzodiazepínico.","D":"Soro glicosado a 10%."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-51275","number":"51275","sourceNumber":"51275","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Os membros da equipe de saúde, em especial os médicos, devem saber reconhecer\nsituações e fatores de risco para quedas\nde idosos. Sobre esse assunto, qual a afirmativa correta?","options":{"A":"Cerca de 10% das quedas ocorrem em escadas sendo que descê-las apresenta maior risco que\nsubi-las.","B":"Quedas com impacto direto sobre as pernas e a coluna vertebral têm maior probabilidade de\nresultar em fraturas.","C":"Homens idosos tendem a cair mais que mulheres idosas até os 75 anos de idade; a partir dessa\nidade, as frequências se igualam.","D":"Quedas acidentais, em sua maioria, ocorrem fora de casa e durante o desempenho de\natividades eventuais como ir à feira ou ir ao banco."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-51222","number":"51222","sourceNumber":"51222","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Homem de 35 anos procurou Unidade Básica de Saúde após sofrer ferimento no pé há\nmenos de 1 hora. O ferimento foi\ndesencadeado por uma pá utilizada em atividades de jardinagem.\nA pá não estava enferrujada, mas estava suja de terra. O Médico de Família e Comunidade (MFC)\nfoi chamado para avaliar o caso e constatou ferimento profundo no pé. O paciente achava que\nhavia tomado uma dose da vacina antitetânica há 11 anos, mas não tinha certeza. Com relação à\nprofilaxia do tétano, além dos cuidados locais com o ferimento, qual a conduta indicada?","options":{"A":"Administrar IGHAT ou SAT + 3 doses de dT.","B":"Administrar antibioticoprofilaxia com amoxicilina-clavulanato.","C":"Completar a vacinação antitetânica, com mais 2 doses de vacina dupla tipo adulto (dT) e uma de\nreforço.","D":"Fazer uma dose de Imunoglobulina Humana Antitetânica (IGHAT) ou Soro Antitetânico (SAT) e\numa dose de dT."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-32535","number":"32535","sourceNumber":"32535","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Paciente de 65 anos, em terceira linha de quimioterapia para tumor esofágico é\nadmitido por síndrome confusional aguda com\nrebaixamento do nível de consciência. Após\navaliação sumária, são administrados 25 g de glicose e hidratação isotônica endovenosos. Cerca\nde uma hora depois o paciente está bem acordado, porém agitado e desorientado em tempo e\nespaço. Nova avaliação evidencia ataxia importante e oftalmoplegia com nistagmo bilaterais. Qual a\nmelhor conduta neste momento?","options":{"A":"Tiamina 50 mg EV.","B":"Nova dose de glicose EV.","C":"Cianocobalamina (B12) 1000 u EV.","D":"Insulina regular 10 u EV.","E":"Flumazenil 0,5 mg EV."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-30855","number":"30855","sourceNumber":"30855","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"De acordo com as evidências científicas disponíveis, a vacinação para influenza em\nidosos deve preferencialmente seguir qual calendário?","options":{"A":"Periodicidade da vacina deve ser julgada caso a caso.","B":"Após epidemias de gripe.","C":"Rotineiramente a cada semestre.","D":"Rotineiramente a cada ano.","E":"Rotineiramente a cada dois anos."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-37467","number":"37467","sourceNumber":"37467","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Sobre a epidemiologia do envelhecimento no Brasil, assinale a afirmativa INCORRETA:","options":{"A":"A epidemiologia do envelhecimento é uma área\n\nemergente, que se ocupa das condições que levam à incapacidade funcional dos idosos.","B":"Houve um aumento da expectativa de vida com a diminuição da mortalidade nas idades mais\navançadas.","C":"O envelhecimento populacional no Brasil ocorre como consequência da redução da fecundidade\ne da mortalidade infantil apenas.","D":"Os estudos epidemiológicos centram-se nos\ndeterminantes da longevidade, das transições\ndemográfica e epidemiológica.","E":"As condições de saúde da população idosa podem ser determinadas pelos seus perfis de\nmorbidade e mortalidade."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-30884","number":"30884","sourceNumber":"30884","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Qual dos itens abaixo representa um fator de risco para \"delirium\" no idoso durante\ninternamento hospitalar?","options":{"A":"Uso de dipirona.","B":"Sexo feminino.","C":"Hipertensão arterial sistêmica.","D":"Sonda vesical de demora.","E":"Obesidade."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-37029","number":"37029","sourceNumber":"37029","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Qual dos fatores abaixo melhor promove a saúde do idoso?","options":{"A":"Manutenção da independência social.","B":"Melhoria da cognição.","C":"Controle das doenças presentes em cada\nindivíduo.","D":"Aumento do condicionamento físico."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-37033","number":"37033","sourceNumber":"37033","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Em 2009, durante a pandemia de gripe H1N1, o Ministério da Saúde NÃO definiu como\ngrupo de maior risco:","options":{"A":"a população indígena aldeada.","B":"as gestantes.","C":"pessoas portadoras de doenças crônicas.","D":"a população com faixa etária entre 50 e 60\nanos."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-37037","number":"37037","sourceNumber":"37037","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Qual a opção correta em relação à vacinação contra febre amarela?","options":{"A":"É indicada em residentes ou viajantes para todos os estados do Norte do Brasil, exceto o Pará.","B":"A vacina oferecida pelo SUS é composta de\nvírus inativo.","C":"Idealmente, deve-se administrar a vacina 2 a\n4 dias antes da data da viagem.","D":"Deve-se administrar a dose de reforço a cada\ndez anos após a data da última dose."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-37044","number":"37044","sourceNumber":"37044","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"De acordo com o Ministério da Saúde, o esquema de vacinação para adultos acima de\n60 anos deve incluir:","options":{"A":"Hepatite B, dose única, a grupos vulneráveis\nsem vacinação anterior.","B":"Vacina pneumocócica 23-valente para\ninstitucionalizados, com reforço em cinco\nanos.","C":"Vacina influenza sazonal a cada seis meses.","D":"Vacina adsorvida para difteria e tétano a cada\n5 anos, se vacinado adequadamente\nanteriormente."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-37048","number":"37048","sourceNumber":"37048","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"A ingestão de duas a três doses de uísque resulta em uma concentração sérica de\nálcool entre 20 e 30 mg/dl. Em indivíduos sem\ntolerância, assinale a opção que descreve a relação\ncorreta entre concentração sérica e sintomas.","options":{"A":"20 mg/dl ? sem qualquer manifestação.","B":"80 mg/dl ? redução de funções cognitivas\ncomplexas e performance motora.","C":"400 mg/dl ? alterações óbvias da fala,\nmotricidade, do comportamento e do\njulgamento.","D":"600 mg/dl ? coma leve e depressão dos sinais\nvitais."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-17813","number":"17813","sourceNumber":"17813","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Esplenectomia está indicada para:","options":{"A":"estadiamento de doença de Hodgkin","B":"tratamento de púrpura trombocitopênica imunológica","C":"tratamento de esquistossomose hepatoesplênica","D":"tratamento de cirrose hepática"},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-349746","number":"349746","sourceNumber":"349746","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Homem, 24 anos, sem comorbidades conhecidas, sob estresse emocional intenso\nrelacionado ao preparo para uma prova de um\nconcurso público, procurou o pronto atendimento\ncom queixa principal de que o lado direito do rosto não se mexia havia 1 dia. Ao exame físico,\napresentava paralisia em hemiface superior e inferior à direita, paralisia da pálpebra superior\ndireita\nque levava à dificuldade de fechar o olho e piscar, além de desvio da rima labial para o lado\nesquerdo. As pupilas estavam isocóricas e fotorreagentes, e a força estava preservada (grau V) em\nmembros superiores e inferiores bilaterais. De acordo com o caso clínico apresentado, qual é a\nprincipal hipótese diagnóstica?","options":{"A":"Paralisia de Todd.","B":"Acidente vascular encefálico.","C":"Síndrome de Claude Bernard-Horner.","D":"Paralisia de Bell.","E":"Hemorragia subaracnoidea."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-365657","number":"365657","sourceNumber":"365657","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Segundo Velasco (2022), a primeira referência histórica feita à rabdomiólise consta na\nBíblia, em que há a descrição de uma doença aguda e grave que acometeu os israelitas após\ningerirem aves que provavelmente alimentavam-se com sementes de cicuta. (VELASCO, I.T.\nMedicina de emergência: abordagem prática. 16. ed. Barueri [SP]: Manole, 2022, com adaptações).\nAssim como o uso de sementes, algumas medicações podem induzir rabdomiólise, como, por\nexemplo, o uso de","options":{"A":"sinvastatina com ciprofibrato.","B":"furosemida com espironolactona.","C":"propranolol com anlodipino.","D":"AAS com clopidogrel."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-365644","number":"365644","sourceNumber":"365644","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Uma criança de 18 meses de vida é levada ao pronto-socorro após um episódio de\nconvulsão tônico-clônica generalizada com duração de aproximadamente dois minutos, seguida de\nsonolência. Chegou ao hospital cerca de uma hora após o evento agudo, dormindo em todo o\ntrajeto. No atendimento inicial, verificou-se Tax = 40 °C, ela foi medicada com antitérmico e\ndeixada\nem repouso. Ao acordar, realizou exame neurológico com resultado normal. Ao exame físico,\napresenta hiperemia de orofaringe e lesões aftosas em palato. Em relação ao diagnóstico dessa\npaciente, assinale a alternativa correta.","options":{"A":"Trata-se de uma convulsão febril complexa, uma vez que houve sonolência após o episódio\nagudo.","B":"Trata-se de um caso de meningite, visto que há presença de um quadro infeccioso nas vias\naéreas.","C":"Deve-se internar a paciente para investigação da convulsão por meio de exames\ncomplementares.","D":"Trata-se de uma convulsão febril simples, que habitualmente não ocorre mais de uma vez em 24\nhoras, mas pode se repetir em quadros infecciosos posteriores."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-349693","number":"349693","sourceNumber":"349693","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Paciente de onze anos que apresenta crises convulsivas, que iniciaram há seis meses,\nsem déficits até o momento. Existe história\nfamiliar de uma síndrome epiléptica generalizada,\ncaracterizada por movimentos súbitos e involuntários de um grupo ou de um único músculo. Qual\ndas seguintes alternativas apresenta o diagnóstico mais provável para esse paciente?","options":{"A":"Síndrome de Dravet.","B":"Síndrome de Lennox-Gastaut.","C":"Síndrome do lobo temporal.","D":"Síndrome de West.","E":"Epilepsia mioclônica juvenil."},"answer":"E","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-322156","number":"322156","sourceNumber":"322156","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Sobre a neuromielite óptica, assinale a alternativa correta.","options":{"A":"É uma forma de apresentação da Esclerose Múltipla.","B":"Pleocitose é bastante específica para o diagnóstico.","C":"Também é conhecida como síndrome de Devic.","D":"A presença de paralisia espástica é frequente.","E":"A tomografia de crânio apresenta alterações específicas."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-305298","number":"305298","sourceNumber":"305298","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Uma mulher de 40 anos, branca, refere que, há 3 meses, apareceram manchas\navermelhadas nas pálpebras e no dorso das\nmãos que apresentavam melhora discreta com o uso\ntópico de corticoide. Nos últimos 20 dias, começou a apresentar dificuldade de elevar os braços\npara pentear os cabelos e escovar os dentes. Também notou que não conseguia subir os dois\nlances de escada de sua casa e passou a precisar de ajuda para levantar da cama e de cadeiras.\nQual achado de exame físico pode definir o diagnóstico?","options":{"A":"Eritrodermia.","B":"Prurido generalizado.","C":"Pápulas de Gottron.","D":"Nódulos de Bouchard.","E":"Nódulos de Heberden."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-261238","number":"261238","sourceNumber":"261238","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Um paciente de 42 anos de idade evolui com convulsões de início recente do tipo\nparciais complexas. Foi realizada uma tomografia\nde crânio com contraste que evidenciou uma\nmassa em lobo parietal direito, com contornos regulares, sugestivo de neoplastia primária. Durante\na internação, foram efetuadas mais três tomografias com contraste para verificar a existência de\noutros sítios de tumor cerebral. Após 72 horas de internação, apresentou piora da diurese com\nureia = 280 mg/dL e creatinina = 1,4 mg/dL. Com base nesse caso clínico e nos conhecimentos\nmédicos correlatos, julgue o item a seguir. Ácido valproico é contraindicado para esse paciente.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-274389","number":"274389","sourceNumber":"274389","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Um paciente de 14 anos é levado ao hospital por quadro ao qual os pais chamaram de\nconvulsão. Segundo a anamnese, o paciente apresentou movimentos generalizados, versão ocular\ne perda de consciência, com duração de 1 minuto, seguida por sonolência. Enquanto examina o\npaciente, o pediatra faz a anamnese mais detalhada. Das seguintes características, qual deve fazer\no pediatra pensar em um diagnóstico alternativo?","options":{"A":"Perda do controle esfinctérico.","B":"Movimentos tônicos.","C":"Cianose central.","D":"Confusão mental após cessar o episódio.","E":"Localização de estímulo doloroso durante o episódio."},"answer":"E","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-284353","number":"284353","sourceNumber":"284353","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Em relação à prevenção, à epidemiologia e à história natural das doenças, julgue o item\na seguir. A evolução da esclerose múltipla depende da faixa etária do paciente, sendo que a mais\ncomum é a forma progressiva, na qual os sintomas e sinais neurológicos se intensificam sem\nremissão, com acometimento neurológico motor.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-255703","number":"255703","sourceNumber":"255703","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Uma paciente de 70 anos de idade perdeu-se em casa e não sabia onde ficava a\nprópria cozinha. Há uma semana, deixou o fogão\naceso quando foi ao mercado. A filha dela, então,\nlevou-a ao geriatra, que realizou exame do estado mental, o qual demonstrou alterações\nprincipalmente nos testes de memória, bem como no teste do relógio. Realizaram-se exames de\nsangue e tomografia de crânio. Nenhum laboratorial estava alterado. Seu médico prescreveu\nmemantina e donepezila. Considerando esse caso clínico e os conhecimentos médicos correlatos,\njulgue o item a seguir. A memantina é um inibidor da acetilcolinesterase, útil para demência\navançada.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-255704","number":"255704","sourceNumber":"255704","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Uma paciente de 70 anos de idade perdeu-se em casa e não sabia onde ficava a\nprópria cozinha. Há uma semana, deixou o fogão\naceso quando foi ao mercado. A filha dela, então,\nlevou-a ao geriatra, que realizou exame do estado mental, o qual demonstrou alterações\nprincipalmente nos testes de memória, bem como no teste do relógio. Realizaram-se exames de\nsangue e tomografia de crânio. Nenhum laboratorial estava alterado. Seu médico prescreveu\nmemantina e donepezila. Considerando esse caso clínico e os conhecimentos médicos correlatos,\njulgue o item a seguir. Em geral, nessa patologia, alterações comportamentais e de linguagem são\nmanifestações tardias da doença.","options":{"A":"CERTO","B":"ERRADO"},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-255705","number":"255705","sourceNumber":"255705","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Uma paciente de 70 anos de idade perdeu-se em casa e não sabia onde ficava a\nprópria cozinha. Há uma semana, deixou o fogão\naceso quando foi ao mercado. A filha dela, então,\nlevou-a ao geriatra, que realizou exame do estado mental, o qual demonstrou alterações\nprincipalmente nos testes de memória, bem como no teste do relógio. Realizaram-se exames de\nsangue e tomografia de crânio. Nenhum laboratorial estava alterado. Seu médico prescreveu\nmemantina e donepezila. Considerando esse caso clínico e os conhecimentos médicos correlatos,\njulgue o item a seguir. Geralmente pacientes com alterações de vitamina B12 apresentam sinais\nneurológicos.","options":{"A":"CERTO","B":"ERRADO"},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-255730","number":"255730","sourceNumber":"255730","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Um paciente de 12 anos de idade vai ao pediatra em razão de sua mãe querer fazer\numa avaliação anual com exames. Dessa vez, o\npediatra solicitou hormônio do crescimento sérico\n(GH), que veio uma vez e meio aumentado, acima dos valores de referência. O paciente faz\natividades físicas regulares e não apresenta alteração estrutural. Esse paciente tinha suspeita de\nsíndrome de West, mas esta foi descartada. Considerando esse caso clínico e os conhecimentos\nmédicos correlatos, julgue o item a seguir. ACTH é a primeira linha no tratamento e corticoide é\nutilizado para pacientes não respondedores.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-154336","number":"154336","sourceNumber":"154336","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Paciente, 55 anos de idade, sexo feminino, branca, apresentou sinais clínicos\nsugestivos de miastenia gravis há\naproximadamente três meses. A prova terapêutica com\nneostigmina evidenciou melhora da disfagia e ptose palpebral. Na radiografia de tórax, observou-se\nimagem ocupando o mediastino anterior com projeção à direita. A tomografia computadorizada de\ntórax revelou a presença de massa no mediatismo anterior, sendo indicado o tratamento cirúrgico.\nA evolução pós-operatória foi boa, sem complicações. Com relação à localização de tumores no\nmediastino anterior, há como exemplos de doenças mais frequentes as chamadas 4T, que são\ntimoma, teratoma, tiroide e terrível linfoma, sendo o mais comum o (a):","options":{"A":"Teratoma.","B":"Bócio mergulhante.","C":"Timoma.","D":"Tireoide intratorácica.","E":"Terrível linfoma."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-152080","number":"152080","sourceNumber":"152080","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Lactente de 7 meses de idade foi levado ao pronto atendimento, pois, após três dias de\nsintomas gripais, apresentou crise convulsiva tônico-clônica generalizada que durou alguns\nminutos. A mãe nega episódios anteriores e casos de epilepsia na família. Ao exame físico,\nobserva-se paciente febril (temperatura axilar 38,5°C). hipoativo, porém responsivo (Glasgow\n15/15), pupilas isocóricas e fotorreagentes. Otoscopia evidencia abaulamento da membrana\ntimpânica à direita. Com base nesse caso clínico, julgue o item a seguir: indica-se o uso de\nanticonvulsivantes com o intuito de evitar novas crises.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-152087","number":"152087","sourceNumber":"152087","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Lactente de 7meses de idade foi levado ao pronto atendimento, pois, após três dias de\nsintomas gripais, apresentou crise convulsiva tônico-clônica generalizada que durou alguns\nminutos. A mãe nega episódios anteriores e casos de epilepsia na família. Ao exame físico,\nobserva-se paciente febril (temperatura axilar 38,5°C). hipoativo, porém responsivo (Glasgow\n15/15), pupilas isocóricas e fotorreagentes. Otoscopia evidencia abaulamento da membrana\ntimpânica à direita. Com base nesse caso clínico, julgue o item a seguir: necessita-se de uma\ninvestigação complementar ambulatorial com tomografia computadorizada e eletroencefalograma.","options":{"A":"CERTO","B":"ERRADO."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-152095","number":"152095","sourceNumber":"152095","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Lactente de 7meses de idade foi levado ao pronto atendimento, pois, após três dias de\nsintomas gripais, apresentou crise convulsiva tônico-clônica generalizada que durou alguns\nminutos. A mãe nega episódios anteriores e casos de epilepsia na família. Ao exame físico,\nobserva-se paciente febril (temperatura axilar 38,5°C). hipoativo, porém responsivo (Glasgow\n15/15), pupilas isocóricas e fotorreagentes. Otoscopia evidencia abaulamento da membrana\ntimpânica à direita. Com base nesse caso clínico, julgue o item a seguir: prescreve-se,\nimediatamente, medicamento antitérmico, evitando assim a aparição de outro episódio convulsivo.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-135022","number":"135022","sourceNumber":"135022","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"No próximo item é apresentado um caso clínico seguido de uma assertiva a ser julgada.\nUm paciente tabagista, que consome vinte\ncigarros por dia, procurou o ambulatório de cirurgia\ngeral, apresentando desconforto e intumescimento na região inguinal direita. Após avaliação, o\nmédico identificou a presença de hérnia inguinal direita, submeteu o paciente à realização de\nexames pré-operatórios e informou que o tratamento seria por hernioplastia inguinal a Lichtenstein.\nNesse caso, com vistas a diminuir as chances de complicações pulmonares e de recidiva da hérnia\ninguinal, o médico deve recomendar ao paciente que interrompa o consumo de cigarros a partir do\nsegundo ou terceiro dia que precede a cirurgia.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-105563","number":"105563","sourceNumber":"105563","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Uma preocupação a se ter com a população com idade acima de 65 anos é o maior\nnúmero de ocorrências de efeitos adversos com eventuais drogas em uso. Isso se deve a um\nconjunto de fatores causais. Com base nessas informações, assinale a alternativa que apresenta\num fator causal:","options":{"A":"Elevada incidência de tumores.","B":"Doses maiores, que sempre devem ser usadas, para surtir o efeito desejado.","C":"Infecções de repetição muito comum.","D":"Inapetência, que ocorre em 90% desses indivíduos.","E":"Metabolismo das drogas alterado com a idade."},"answer":"E","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-88688","number":"88688","sourceNumber":"88688","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"A respeito de saúde mental, julgue o item subsequente. A constatação de dano real à\nsaúde física e mental do paciente é requisito\npara o diagnóstico de alcoolismo. Fatores como\nintoxicação aguda eventual e mal-estar causado pela ingestão de bebidas alcoólicas não são\nsuficientes para a configuração do referido diagnóstico.","options":{"A":"CERTO","B":"ERRADO"},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-32162","number":"32162","sourceNumber":"32162","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"A hipertensão arterial primária (essencial) causa lesões intrínsecas das arteríolas\nrenais\n(ateroesclerose hialina), que resultam em angionefroesclerose. A terapêutica deve controlar a\npressão arterial para evitar danos cardiovasculares e preservar a taxa de filtração glomerular, com\no objetivo de retardar o desenvolvimento de insuficiência renal crônica. Com base nessas\ninformações, assinale a alternativa que apresenta a prescrição medicamentosa adequada para\nessa situação.","options":{"A":"Inibidores de angiotensina e diuréticos tiazídicos em baixas doses.","B":"Betabloqueadores e diuréticos de alça dose plena.","C":"Inibidores de canais de cálcio e diuréticos tiazídicos em altas doses.","D":"Monoterapia com diuréticos de alça em dose plena.","E":"Inibidores de canais de cálcio e inibidores de angiotensina."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-366238","number":"366238","sourceNumber":"366238","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Acerca de crise febril e seus conceitos correlatos, julgue o próximo item: É definida\ncomo convulsão em vigência de febre em crianças\nentre 3 meses e 5 anos de idade, desde que\nsem evidência de infecção intracraniana ou causa definida para o episódio, bem como exclusão de\nconvulsões febris anteriores.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-366237","number":"366237","sourceNumber":"366237","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Acerca de crise febril e seus conceitos correlatos, julgue o próximo item: O pico de\nidade é entre crianças entre 3 e 5 anos.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-366211","number":"366211","sourceNumber":"366211","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Acerca de crise febril e seus conceitos correlatos, julgue o próximo item: Geralmente é\nquadro espontâneo, sem fator causal, no qual a criança é investigada com exames laboratoriais e\nde imagem de crânio chegando a realizar líquor para diagnóstico de exclusão de infecção\nsubclínica de sistema nervoso central.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-366210","number":"366210","sourceNumber":"366210","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Acerca de crise febril e seus conceitos correlatos, julgue o próximo item: À medida que\na temperatura aumenta, especialmente\nultrapassando os 39 °C, e à medida que se prolonga a\nduração dessa temperatura, aumenta a probabilidade de ocorrência de episódios convulsivos.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-366209","number":"366209","sourceNumber":"366209","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Acerca de crise febril e seus conceitos correlatos, julgue o próximo item: O risco de\nrecorrência é mais elevado em crianças que experimentaram o episódio após completar 1 ano de\nidade. Algumas delas, ocasionalmente, podem necessitar de anticonvulsivantes por um período,\ndependendo da frequência das crises ao longo do ano.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-301259","number":"301259","sourceNumber":"301259","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"O acometimento pleuropulmonar em pacientes com doenças autoimunes sistêmicas é\ncomum e pode levar ao aumento da morbidade e mortalidade. O diagnóstico precoce dessas\nmanifestações oferece a melhor chance de intervir e melhorar o prognóstico. A respeito desse\nassunto, julgue o item a seguir. Em casos de polimiosite, a manifestação mais comum é a\npneumonia aspirativa.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-307107","number":"307107","sourceNumber":"307107","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Um paciente de 5 meses de vida foi levado à emergência por apresentar contração\ntônica rápida em flexão, com duração de 10\nsegundos, da musculatura do pescoço, do tronco e dos\nmembros. Essas crises iniciaram-se há duas semanas e ocorrem em salvas, especialmente ao\ndespertar e em períodos de sonolência, frequentemente acompanhados de choro. Os responsáveis\npela criança negam qualquer episódio de febre e (ou) outros sintomas. Nesse caso clínico, o\nprovável diagnóstico é Alternativas:","options":{"A":"cólica do lactente, demandando observação e orientação para casa.","B":"síndrome mioclônica atônica, precisando de observação.","C":"síndrome de West, com necessidade de EEG que revela hipsarritmia.","D":"síndrome convulsiva febril, com prescrição de clobazan para casa.","E":"síndrome focal por hipoglicemia."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-307116","number":"307116","sourceNumber":"307116","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"No que tange ao tema convulsão febril, assinale a alternativa correta. Alternativas:","options":{"A":"Apresenta evolução insidiosa, frequentemente associada a deficit neurológico.","B":"Apresenta maior recorrência quanto maior a idade do início.","C":"São, na maioria das vezes, generalizadas e breves, e podem ser clônicas.","D":"São acompanhadas de automatismos motores orais ou palpebrais.","E":"Manifesta-se acompanhada de estado pós-ictal prolongado."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-274601","number":"274601","sourceNumber":"274601","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"As intervenções psicocomportamentais visam a alteração das crenças e a modificação\ndos comportamentos disfuncionais, bem como a alteração\nda percepção da dor neuropática,\npermitindo uma melhor adesão ao tratamento e maior confiança nas condutas propostas aos\npacientes. Nesse sentido, se encontra a psicoterapia de apoio, a qual traz benefícios para a\nnormalização das alterações afetivas não passíveis de controle farmacológico. Considerando as\ntécnicas de psicoterapia, é CORRETO afirmar:","options":{"A":"A psicoterapia auxilia os doentes a vislumbrar os seus objetivos de vida.","B":"As técnicas de psicoterapia devem ser regularmente prescritas para doentes com dor muito\nintensa porque a capacidade de participação torna-se comprometida devido às limitações\nfuncionais.","C":"As técnicas de psicoterapia podem ser regularmente prescritas para doentes adequadamente\ncontrolados com medicamentos.","D":"A psicoterapia possui como objetivo tratar apenas os problemas de depressão."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-268900","number":"268900","sourceNumber":"268900","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Um paciente de 55 anos de idade compareceu ao pronto atendimento relatando\nfraqueza, que se iniciou nos membros inferiores\ne foi progredindo para a cintura pélvica e os\nmembros superiores, com início há oito dias. Relatou infecção intestinal três semanas antes do\ninício da fraqueza. Ao exame, apresenta força muscular grau 2 nos membros inferiores e grau 3\nnos membros superiores. Verificam-se FC = 100 bpm, FR = 20 irpm, SatO2 = 98% e PA = 120\nmmHg x 80 mmHg. A hipótese diagnóstica foi feita como síndrome de Guillain-Barré. De acordo\ncom essa hipótese diagnóstica, espera-se encontrar","options":{"A":"hiperreflexia, alteração de sensibilidade, função esfincteriana preservada e líquido\ncefalorraquidiano com celularidade normal e aumento da concentração proteica.","B":"hiporreflexia, sensibilidade inalterada, função esfincteriana alterada e líquido\ncefalorraquidiano\ncom celularidade e concentração proteica aumentadas.","C":"arreflexia, sensibilidade inalterada, função esfincteriana alterada e líquido cefalorraquidiano\ncom\ncelularidade e concentração proteica aumentadas.","D":"hiporreflexia, sensibilidade inalterada, função esfincteriana alterada e líquido\ncefalorraquidiano\ncom celularidade e concentração proteica normais.","E":"arreflexia, alteração de sensibilidade, função esfincteriana preservada e líquido\ncefalorraquidiano\ncom celularidade normal e aumento da concentração\nproteica."},"answer":"E","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-274616","number":"274616","sourceNumber":"274616","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Convulsões são alterações paroxísticas da função neurológica (comportamental,\nmotora e/ou autonômica). A convulsão clônica no\nrecém-nascido se caracteriza por:","options":{"A":"Movimentos rítmicos, inicialmente de 1 a 3 segundos, declinando progressivamente.","B":"Movimentos rítmicos, inicialmente de 1 a 15 segundos, declinando progressivamente.","C":"Movimentos rítmicos, inicialmente de 1 a 10 segundos, declinando progressivamente.","D":"Movimentos arrítmicos, inicialmente de 1 a 15 segundos, declinando progressivamente."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-274617","number":"274617","sourceNumber":"274617","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Considerando a convulsão mioclônica no recém-nascido, quanto à sua característica\nprincipal, é CORRETO afirmar:","options":{"A":"Relaxamento de todos os músculos do corpo.","B":"Movimentos lentos e predileção pelo grupo muscular flexor.","C":"Movimentos de velocidade rápida e predileção pelo grupo muscular flexor.","D":"Ausência de movimento e atrofia do grupo muscular flexor."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-263369","number":"263369","sourceNumber":"263369","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Uma adolescente com 11 anos de idade, com diagnóstico de epilepsia, chega ao\nPronto-Socorro (PS) inconsciente, com movimentos tônico-clônicos generalizados, cianótica, com\ndesvio do olhar e sialorreia. A mãe informa que a adolescente iniciou a crise há 20 minutos, sem\nrecuperar a consciência ao longo do trajeto para o PS. Na sala de emergência, devido à\npersistência do quadro, é administrado diazepam endovenoso por 3 vezes, com intervalo de 5\nminutos entre as doses. Apesar da intervenção terapêutica, a paciente mantém o quadro\nconvulsivo. Nesse caso, a próxima conduta médica deve ser administrar:","options":{"A":"Topiramato por infusão endovenosa contínua.","B":"Fenitoína em dose de ataque endovenosa.","C":"Diazepam em dose dobrada endovenosa.","D":"Tiopental por cânula endotraqueal."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-274622","number":"274622","sourceNumber":"274622","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"A epilepsia é um dos transtornos neurológicos de maior prevalência no mundo.\nConsiderando a epilepsia rolândica, é CORRETO afirmar:","options":{"A":"Esse é o tipo mais comum de desordem epiléptica da infância, afetando entre 15% e 25% das\ncrianças com o distúrbio.","B":"É um tipo de epilepsia que não acomete crianças e adolescentes.","C":"Só acomete crianças a partir dos 7 anos.","D":"Só acomete crianças até os 7 anos."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-273347","number":"273347","sourceNumber":"273347","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Paciente de 25 anos, após quadro de diarreia autolimitada prévia dá entrada no PS\ncom quadro de perda de força ascendente,\ndiminuição dos reflexos tendinosos e sensação de\nformigamento nas pernas. O exame do líquor mostra importante proteinorraquia com celularidade\nnormal. Considerando-se a principal hipótese podemos afirmar que:","options":{"A":"Cerca de 80% apresentam parestesia de mãos e pés associada a fraqueza","B":"Alteração de sensibilidade é comum, sendo mais facilmente diagnosticada testando-se a\nsensibilidade tátil","C":"Na fase aguda a apresentação com dorsalgia é rara e deve sugerir diagnóstico diferencial mais\namplo","D":"A presença de disautonomia é infrequente, mas confere pior prognóstico neurológico"},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-291512","number":"291512","sourceNumber":"291512","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Uma lactente do sexo feminino, de 18 meses de idade, chega para atendimento em\nUnidade Básica de Saúde. A mãe informa que, há 3 dias, a criança apresentou quadro de\nconvulsão tônico-clônica generalizada acompanhada de versão ocular, liberação de esfíncter\nvesical e sialorreia, com duração de aproximadamente 10 minutos. No momento, apresentava\ntemperatura axilar de 38ºC. Foi levada ao pronto atendimento, onde chegou sem crise e recebeu\nalta após 4 horas com diagnóstico de resfriado comum. O episódio convulsivo não se repetiu e a\ncriança está afebril há 48 horas. A mãe relata episódio semelhante aos 11 meses de idade. A\ncriança não apresenta outros antecedentes pessoais ou familiares relevantes. O seu\ndesenvolvimento neuropsicomotor é normal e o exame clínico não apresenta alterações.\n\nConsiderando os dados clínicos da paciente, essa criança apresenta:","options":{"A":"Convulsão febril simples. A mãe deve ser orientada quanto à abordagem nos episódios febris e a\ncriança deve manter acompanhamento de rotina na UBS pelo caráter benigno do quadro.","B":"Convulsão febril simples. O médico deve prescrever benzodiazepínico (diazepam ou nitrazepam)\npara uso durante os episódios febris, com o\nobjetivo de prevenir epilepsia futura.","C":"Convulsão febril complexa. A criança deve realizar eletroencefalograma e tomografia\ncomputadorizada de crânio por não ser o primeiro episódio convulsivo febril apresentado.","D":"Convulsão febril complexa. Os familiares precisam ser alertados sobre a possibilidade de a\ncriança apresentar desempenho escolar fraco futuramente como sequela dos episódios\nconvulsivos."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-244473","number":"244473","sourceNumber":"244473","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Uma paciente de 24 anos de idade apresentou história de seis dias de fraqueza\nprogressiva dos membros inferiores de forma\nascendente e, na manhã de hoje, não consegue\nandar em razão da paralisia completa dos membros inferiores bilateralmente. Há duas semanas,\nela teve um episódio de gastroenterite com diarreia profusa, aquosa, com duração de três dias.\nNega comorbidades prévias. Não há histórico familiar positivo para doenças crônicas. Pressão\narterial = 84 bpm, frequência respiratória = 18 irpm, temperatura = 36ºC, saturação de oxigênio =\n97% no ar ambiente. Exame neurológico: sem sinais de rigidez do pescoço ou meningismo. Sem\nenvolvimento dos pares cranianos. Força muscular: membros inferiores esquerdo e direito grau 0,\nmembros superiores esquerdo e direito grau 5, arreflexia em membros inferiores e reflexo em\nmembros superiores grau 2. Sensibilidade tátil e dolorosa normal globalmente. No primeiro dia após\na admissão, a paciente foi internada na enfermaria neurológica e seus sintomas continuaram a\npiorar. Começou a alegar diminuição da força em membros superiores bilateralmente. A RM foi\nsugestiva de realce da raiz nervosa, e a RM de crânio foi normal. Com base nesse caso clínico e\nnos conhecimentos médicos referentes à provável Síndrome de Guillain-Barré (SGB), assinale a\nalternativa CORRETA.","options":{"A":"A paciente em estudo pode ser tratada com timoglobulina de cavalo 0,4 g kg IVI por cinco dias.\n\nO mecanismo exato de ação não é conhecido, mas acredita-se que vários mecanismos estejam\nenvolvidos, incluindo a inibição da produção de anticorpos, a inibição da ligação do complemento e\na neutralização dos anticorpos patológicos.","B":"O importante conceito imunológico da SGB é o desenvolvimento de reatividade cruzada de\nautoanticorpos direcionados contra os axônios encontrados em neurônios e mielina.","C":"Uma terapia alternativa para a paciente é a plasmaférese. Esse mecanismo consiste na retirada\nde metabólicos de amônia associados a\nautoanticorpos IgM presentes no plasma.","D":"A SGB é considerada uma polineuropatia axonal aguda padrão de luva e bota de neurônio motor\nsuperior. Portanto, a paciente necessita de realização de fundoscopia ocular para confirmação de\nneurite óptica, achado esse patognomônico da SGB.","E":"A SGB é geralmente precedida por uma infecção respiratória ou gastrointestinal, e o organismo\nassociado mais comum é a bactéria causadora de diarreia Campylobacter jejuni. No entanto,\nHaemophilus influenzae, Mycoplasma pneumoniae e infecções virais (CMV, HIV e EBV) também\nforam associados à SGB."},"answer":"E","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-244479","number":"244479","sourceNumber":"244479","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Um paciente de 2 anos e 3 meses de idade foi levado pela mãe, desesperada, ao\npronto atendimento. A criança apresentou um\nepisódio de crise convulsiva em casa, em que se\ncontorceu toda, debateu-se, ficou desacordada, um pouco roxa e salivando, mas logo retomou a\nconsciência. A crise durou cerca de 3 minutos. Agora, passados 15 minutos, o paciente está\nlevemente sonolento. Nunca havia apresentado algo parecido antes. Sempre foi um garoto\nsaudável. Durante o dia, estava bem, porém inapetente e só reclamou de dor para engolir. Nega\ntosse, vômitos, diarreia, cefaleia. Ao exame físico, encontra-se febril (39,5 ºC), taquipneico leve,\ntaquicárdico FC = 143 bpm, pulsos amplos, com boa perfusão periférica. Observam-se ausculta\ncardiopulmonar normal, abdome inocente, sem sinais meníngeos ou localizatórios, com pupilas\nisocóricas isofotorreagentes, orofaringe com hiperemia e placas purulentas em amígdalas, e cadeia\nganglionar cervical anterior aumentada. Depois de aproximadamente 20 minutos, a criança já\nestava bem alerta e com temperatura de 38,3 ºC (havia tomado dipirona no caminho de casa para o\nhospital). Com base nesse caso clínico e considerando o quadro convulsivo apresentado por esse\npaciente, assinale a alternativa correta.","options":{"A":"Como a crise ocorreu em vigência de febre, deve ser colhido líquor para análise microbiológica e\nafastamento da hipótese de meningite.","B":"Na ocasião da alta, o paciente deve ser encaminhado para realização de eletroencefalograma e\ntomografia de crânio.","C":"Trata-se de convulsão febril simples e não há indicação de anticonvulsivante profilático nesse\nmomento.","D":"Deveria ser administrado diazepam à admissão, pois o paciente estava sonolento ainda.","E":"Trata-se de crise de ausência e está indicada profilaxia com ácido valproico preferencialmente."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-203148","number":"203148","sourceNumber":"203148","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Um lactente de 5 meses de vida iniciou quadro de alteração do desenvolvimento\nneuropsicomotor, acompanhado de movimentos do tipo\njack-knife e slaam, simétricos, de curta\nduração, mais evidentes quando desperta. Foi avaliado pela neurologia pediátrica, sendo realizado\num eletroencefalograma com o traçado apresentado. A respeito desse caso clínico, assinale a\nalternativa que corresponde ao diagnóstico e à conduta mais adequada para o caso.","options":{"A":"Diagnóstico: síndrome de Aicardi. Tratamento: vigabatrina.","B":"Diagnóstico: epilepsia mioclônica do lactente. Tratamento: não há tratamento específico.","C":"Diagnóstico: síndorme de Ohtahara. Tratamento: drogas antiepiléticas.","D":"Diagnóstico: síndrome de West. Tratamento: ACTH.","E":"Diagnóstico: síndrome de Dravet. Tratamento: vigabatrina."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":["question_bank/media/medcurso/med-clinica-medica-med-clm-13/203148.png"],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-154493","number":"154493","sourceNumber":"154493","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Paciente do sexo feminino, 34 anos de idade, previamente hígida, com queixa de\nfraqueza muscular há cerca de 1 semana. Relata\nque, por vezes, tem apresentado diplopia e ptose\npalpebral, principalmente ao final do dia. O médico que a atende logo suspeita de um diagnóstico, e\nresolve fazer um teste com edrofônio para corroborar sua hipótese. Após a aplicação do fármaco,\nos sintomas da paciente \"milagrosamente\" desapareceram. Tendo como base o caso acima, qual é\na principal hipótese diagnóstica?","options":{"A":"Dermatomiosite.","B":"Guillain-Barré.","C":"Esclerose Múltipla.","D":"Miastenia Gravis.","E":"Distrofia Muscular de Duchenne."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-154495","number":"154495","sourceNumber":"154495","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Paciente do sexo feminino, 34 anos de idade, previamente hígida, com queixa de\nfraqueza muscular há cerca de 1 semana. Relata\nque, por vezes, tem apresentado diplopia e ptose\npalpebral, principalmente ao final do dia. O médico que a atende logo suspeita de um diagnóstico, e\nresolve fazer um teste com edrofônio para corroborar sua hipótese. Após a aplicação do fármaco,\nos sintomas da paciente \"milagrosamente\" desapareceram. Qual o anticorpo que provavelmente\nserá encontrado na paciente em questão?","options":{"A":"Anti-centrômero.","B":"Anti-músculo liso.","C":"Anti-receptor de acetilcolina.","D":"Anti-citoplasma de neutrófilo.","E":"Anti-Ro."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-159559","number":"159559","sourceNumber":"159559","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"O item a seguir apresenta uma situação hipotética seguida de uma assertiva a ser\njulgada a propósito da fisiopatologia, do\ndiagnóstico precoce e do tratamento de doenças em\ncrianças e adolescentes. Um lactente de seis meses de idade vem apresentando crises convulsivas\nespásticas desde os dois meses de vida e há um retardo importante do seu desenvolvimento. O\neletroencefalograma apresentou o aspecto seguinte (Conforme imagem do caderno de questões).\nNesse caso, o diagnóstico é de síndrome de West ou hipsiarritmia?","options":{"A":"CERTO.","B":"ERRADO."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":["question_bank/media/medcurso/med-clinica-medica-med-clm-13/159559.png"],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-80748","number":"80748","sourceNumber":"80748","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"O estado funcional de idosos deve ser avaliado pelo menos em dois níveis: atividades\nrotineiras do dia a dia (banho, ato de\nvestir-se, arrumar os cabelos e outros) e atividades\ninstrumentais diárias (uso de telefone, cuidados com a casa, ato de fazer compras, por exemplo).\nPara tanto, existem instrumentos específicos que devem ser aplicados periódica e rotineiramente\npelo médico em suas avaliações dessa clientela. Essa prática permite detecção precoce de\nalterações que podem ser quase sempre corrigidas, otimizadas, ou até mesmo evitadas. Acerca da\nfrequência de realização dessa avaliação, assinale a alternativa CORRETA:","options":{"A":"Nunca deve ocorrer na primeira consulta.","B":"Não deve ser realizada após alguma doença intercorrente.","C":"Deve ser realizada sempre que houver alterações na rotina da casa.","D":"Nunca deve ocorrer após a perda de um ente querido.","E":"Não deve ocorrer após alterações nas tarefas rotineiras."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-80749","number":"80749","sourceNumber":"80749","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Os principais objetivos na abordagem clínica de idosos devem estar relacionados à\nexpectativa de vida de acordo com a idade. Assim, nem sempre se objetiva a cura, mas sim\npreservar funcionalidades e aplicar cuidados paliativos necessários para manter boa qualidade de\nvida e conforto. Desse ponto de vista, assinale a alternativa que apresenta o objetivo que seria\ndesejável.","options":{"A":"Internação logo no início de qualquer sintoma suspeito de intercorrências clínicas.","B":"Envidar esforços para manter sempre que possível o manejo domiciliar do paciente.","C":"Prolongar a internação até a ausência de quaisquer sintomas para depois acompanhar o\npaciente em domicílio.","D":"Utilizar meios auxiliares para caminhar (andadores, por exemplo), mesmo que o paciente\nconsiga se locomover bem sem eles.","E":"Impedir que o paciente saia de casa mesmo quando sente dores suportáveis."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-64429","number":"64429","sourceNumber":"64429","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Homem de 40 anos, etilista, é levado ao serviço de emergência por familiares devido a\nquadro de confusão mental. Ao exame físico notam-se sinais de desnutrição além de marcha\natáxica e nistagmo. Das abaixo, a principal medida terapêutica será administrar:","options":{"A":"Lactulona","B":"Tiamina","C":"Haloperidol","D":"Diazepam","E":"Hidantal"},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-352179","number":"352179","sourceNumber":"352179","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Escolar com 7 anos, deu entrada na emergência com quadro de convulsão\n\ntônico-clônica generalizada de início há cerca de 20 minutos. Mãe refere o diagnóstico de paralisia\ncerebral e epilepsia. Faz uso regular de carbamazepina, mas a medicação acabou há 3 dias. No\nmomento está monitorado, afebril, com via aérea segura e oxigênio nasal. Frequência cardíaca:\n110 bpm, pressão arterial: 110/70 mmHg. Glicemia capilar de 90 mg%. Exames laboratoriais foram\ncoletados. Com relação ao tratamento medicamentoso a ser instituído podemos afirmar:","options":{"A":"Fenobarbital por via venosa deve ser a medicação de primeira linha, mas apresenta risco de\ndepressão respiratória e hipotensão.","B":"Trata-se de um estado de mal epiléptico refratário com risco de sequelas neurológicas graves,\nportanto deve ser intubado e iniciar tiopental ou midazolam contínuos.","C":"Fenitoína por via venosa deve ser a medicação de primeira linha pois tem efeito para cessar o\nevento convulsivo vigente, além de ter efeito profilático para novas crises.","D":"Benzodiazepínico por via venosa deve ser a medicação de primeira linha, mas pode ser\nadministrado por via intramuscular, retal ou nasal caso não possua acesso venoso."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-320435","number":"320435","sourceNumber":"320435","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Em consulta de rotina, lactente com 18 meses, observa-se as seguintes medidas\nevolutivas do perímetro cefálico (PC): ao\nnascer (35 cm), 1 mês (37 cm), 4 meses (42 cm), 7 meses\n\n(44 cm), 9 meses (44,5 cm), 12 meses (44,5 cm). Desenvolvimento: sorriso social com dois meses,\ngargalhadas com quatro meses, sentou-se com sete meses, arrastou-se com nove meses e\nbalbucio de sons consonantais com dez meses. Atualmente, não fica de pé com apoio, não\nengatinha, emite sons guturais, não pega o brinquedo ou objetos em seu campo de alcance. Tem\ncontato visual, mas não compreende jogos de esconde-esconde, dança, acenar adeus ou bater\npalmas. Realiza movimentos repetitivos e estereotipados de mãos, do tipo lavar ou esfregar. Há um\nmês apresentou quatro crises convulsivas tônico-clônicas generalizadas. O diagnóstico sindrômico\né:","options":{"A":"Transtorno do espectro autista.","B":"Atraso do desenvolvimento neuropsicomotor.","C":"Paralisia cerebral.","D":"Regressão do desenvolvimento neuropsicomotor.","E":"Não apresenta alterações do crescimento e desenvolvimento."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-336286","number":"336286","sourceNumber":"336286","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Menina, 9 anos, deu entrada no PS em crise convulsiva caracterizada por movimentos\ntônico clônicos generalizados associados a\nperda de controle esfincteriano e perda da consciência\nhá 30 minutos. Após realização de 3 doses de diazepam endovenoso, paciente mantinha em crise\nconvulsiva. A próxima medicação a ser feita é:","options":{"A":"Carbamazepina","B":"Tiopental","C":"Lorazepam","D":"Fenitoína"},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-304847","number":"304847","sourceNumber":"304847","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Uma paciente de 45 anos, previamente hígida foi admitida por fraqueza de instalação\naguda nos membros inferiores e dor ao longo da\nface interna de ambas as coxas e retenção\nurinária há 8 dias. Ao exame, observou-se paraparesia crural, hiperreflexia patelar e aquilina -\ndemais reflexos estavam normoativos, reflexo plantar em extensão bilateralmente, hipoestesia tátil\ne hipopalestesia com nível em T10. Qual a hipótese diagnóstica para este caso?","options":{"A":"Mielopatia longitudinalmente extensa.","B":"Mielorradiculopatia esquistossomótica.","C":"Mielopatia espondilótica.","D":"Síndrome de Guillain-Barrè."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-314033","number":"314033","sourceNumber":"314033","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"A síndrome de Guillain-Barré (SGB) corresponde a uma neuropatia periférica\ninflamatória adquirida de início agudo. Em relação a essa síndrome, assinalar a alternativa\nCORRETA:","options":{"A":"Cursa com níveis elevados de proteína no líquido cefalorraquiano, com baixas contagens de\ncélulas (dissociação albumino-citológica).","B":"A neuropatia axonal motora aguda, um tipo de síndrome de Guillain-Barré, responsabiliza-se\npela maioria dos casos de SGB.","C":"Apesar de frequentemente causar uma \"\"paralisia ascendente\"\", os reflexos profundos\ncostumam estar normais/preservados.","D":"O botulismo, um dos diagnósticos diferenciais possíveis, produz paralisia espástica rapidamente\nprogressiva, com sintomas sensitivos.","E":"O uso de corticoides intravenosos utilizados isoladamente no tratamento da SGB tem-se\nmostrado igualmente eficaz quando comparado à imunoglobulina intravenosa isolada."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-283927","number":"283927","sourceNumber":"283927","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Criança de 7 anos, após episódio de gastroenterite e febrícula, iniciou com quadro de\ncansaço e diminuição de força nas pernas\ncom manifestações ascendentes, contínuas, simétricas e\nprogressivas. Tem apresentado perda do controle esfincteriano, hiporreflexia tendinosa profunda e\nhipertensão arterial. A mais provável hipótese diagnóstica é:","options":{"A":"Polirradiculoneuropatia.","B":"Poliomielite.","C":"Miastenia gravis.","D":"Mielite transversa aguda.","E":"Polimiosite aguda."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-227246","number":"227246","sourceNumber":"227246","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Homem de 24 anos deu entrada no Pronto Socorro com abalos tônico-clônicos com\nduração de cerca de 30 minutos,\nmantendo-se inconsciente. Apresenta febre de 39,2ºC, sem sinais\nde trauma. O diagnóstico deste paciente é:","options":{"A":"Estado de mal convulsivo.","B":"Intoxicação exógena.","C":"Convulsão febril.","D":"Epilepsia."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-243032","number":"243032","sourceNumber":"243032","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Na Síndrome de Compressão Medular relacionada à malignidade, podemos encontrar,\nEXCETO:","options":{"A":"dor na área afetada.","B":"fraqueza muscular.","C":"disfunção esfincteriana.","D":"hiper-reflexia abaixo do nível da compressão.","E":"vômitos matutinos."},"answer":"E","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-243041","number":"243041","sourceNumber":"243041","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"São tumores (TU) mais frequentes no mediastino anterior, médio e posterior, nesta\nordem:","options":{"A":"TU de células germinativas, TU neurogênico, cistos.","B":"TU neurogênico, TU tímicos, TU endócrinos.","C":"TU tímico, cistos, TU neurogênico.","D":"cistos, TU tímico, linfoma.","E":"TU tímicos, TU endócrinos, TU neurogênicos."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-227319","number":"227319","sourceNumber":"227319","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"A respeito da convulsão febril é correto afirmar que:","options":{"A":"Caracteriza-se por duração maior de 30 minutos.","B":"Necessita da realização de punção lombar em todos os casos.","C":"Constitui um evento mais frequente acima dos cinco anos de idade.","D":"Associa-se a febre, não recorrendo, na maioria dos casos, na mesma doença febril."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-246797","number":"246797","sourceNumber":"246797","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Dentre os aspectos clínicos abaixo, qual é característico da crise convulsiva febril\nsimples?","options":{"A":"A crise geralmente é focal e de curta duração.","B":"A incidência é mais elevada entre 6 meses e 60 meses de vida.","C":"Tem grande relação com alterações cognitivas no futuro.","D":"Geralmente recorre em 24 horas.","E":"Em geral duram mais de 15 minutos."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-212904","number":"212904","sourceNumber":"212904","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Em relação ao estado epilético podemos afirmar que:","options":{"A":"Estado de mal epiléptico se caracteriza pela presença de crise convulsiva que dure no mínimo\n10 minutos.","B":"A primeira medida a ser tomada numa crise convulsiva é a infusão de diazepam 10 mg IV.","C":"No estado de mal epiléptico, após a crise ser abortada, está indicado o uso de fenitoína 20\nmg/kg de peso.","D":"Antidepressivos tricíclicos podem estar associados a crise epilépticas, ao passo que os\nantidepressivos serotoninérgicos não.","E":"A maior parte dos pacientes com crise única na emergência apresentará recorrência das crises\nem até 6 meses, se não receber drogas antiepilépticas para uso crônico."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-220307","number":"220307","sourceNumber":"220307","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Criança com 2 anos, previamente hígida, cartão vacinal em dia, é levada a um pronto\natendimento por apresentar quadro de convulsão generalizada, em vigência de febre de 38°C, mas\nquando chegou no pronto atendimento já estava sem crise. Pais são bem orientados e relatam ser\na primeira crise da criança. O pediatra que prestou atendimento à criança não encontrou nenhum\nfoco infeccioso. Mediante o caso descrito, assinale a alternativa que apresenta a conduta\nCORRETA a ser adotada:","options":{"A":"Iniciar anticonvulsivante para prevenir o risco de epilepsia futura.","B":"Realizar punção lombar e, em seguida, iniciar ceftriaxona e dose ataque de fenitoína.","C":"Iniciar anticonvulsivante e solicitar tomografia de crânio.","D":"Orientar os pais sobre o processo benigno da crise convulsiva febril, sem necessidade de iniciar\nanticonvulsivante."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-212956","number":"212956","sourceNumber":"212956","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Lactente de 5 meses de idade, aparentemente saudável, passou a apresentar no último\nmês contrações musculares bruscas, bilaterais e de curta duração (5 segundos), definidas pela\nmãe como \"sustos\", seguidos de choro, que ocorrem principalmente ao despertar. História\npregressa é normal. Nasceu a termo, sem intercorrências, APGAR 9/10. Está em aleitamento\nmaterno exclusivo, e seu exame físico atual é normal. Dentre os diagnósticos diferenciais, qual é o\nmais provável?","options":{"A":"Síndrome de West.","B":"Epilepsia parcial benigna da infância.","C":"Doença do xarope de bordo.","D":"Síndrome de Lennox-Gastaut.","E":"Síndrome de Janz."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-172764","number":"172764","sourceNumber":"172764","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Sobre a síndrome de Guillain-Barré, a assertiva CORRETA:","options":{"A":"Linfocitorraquia acima de 10 células/mm³ e proteinorraquia aumentada são achados\ncaracterísticos.","B":"Eletroneuromiografia sem sinais eletrofisiológicos de desmielinização exclui o diagnóstico.","C":"A plasmaférese demonstra benefícios na recuperação funcional, sobretudo quando iniciada\nprecocemente.","D":"O uso de corticoides está indicado em associação à transfusão de imunoglobulinas ou\nplasmaférese."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-188007","number":"188007","sourceNumber":"188007","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Nas primeiras visitas domiciliares para pessoas idosas é importante que a equipe de\nsaúde use um instrumento de avaliação\nfuncional (IAF) para objetivar a coleta de informações que\nfacilitam a abordagem. Para os domínios a se pesquisar e que devem compor um IAF de boa\nqualidade fazem parte a avaliação da visão e audição, mas outros aspectos como estado mental e\nsuporte social e outros mais. Que outro elemento entre os abaixo, deve fazer para da IAF?","options":{"A":"Testes labirínticos como Dix-Hallpike e Epley.","B":"Fundoscopia.","C":"Função de membros superiores e inferiores.","D":"Conflitos familiares.","E":"Medidas seriadas de pressão arterial."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-172532","number":"172532","sourceNumber":"172532","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"São drogas usadas no tratamento do status epilepticus EXCETO:","options":{"A":"Fentanil.","B":"Fenitoína.","C":"Tiopental.","D":"Midazolan.","E":"Propofol."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-174368","number":"174368","sourceNumber":"174368","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"A síndrome de compressão medular corresponde à compressão do saco dural e seus\ncomponentes por uma lesão tumoral extradural. Está incorreto afirmar que:","options":{"A":"Iniciar imediatamente dexametasona 10mg IV em bolus, seguido de 4mg IV 6/6h.","B":"A dor está presente em 95% dos casos.","C":"O quadro clínico compreende em dor e/ou sintomas neurológicos decorrentes da compressão\ntumoral do saco dural e seus componentes.","D":"Sempre que possível, solicitar uma ressonância magnética de todos os segmentos da coluna.","E":"O segmento mais acometido é o lombossacro (60 a 85%)."},"answer":"E","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-187453","number":"187453","sourceNumber":"187453","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"A polirradiculoneuropatia aguda ou subaguda (Síndrome de Guillain Barré), mais\ncomumente se associa a enterite causada por:","options":{"A":"Salmonela.","B":"Shigella.","C":"Campylobacter jejuni.","D":"Rotavírus.","E":"Citomegalovírus."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-162530","number":"162530","sourceNumber":"162530","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Lactente de 2 anos de idade é levado ao pronto-socorro com crise convulsiva febril.\nQual o medicamento de escolha para retirá-lo da crise?","options":{"A":"Fenitoína.","B":"Fenobarbital.","C":"Ácido valproico.","D":"Benzodiazepínico.","E":"Carbamazepina."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-127220","number":"127220","sourceNumber":"127220","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"São critérios diagnósticos para síndrome de abstinência ao álcool, definidos pela\nOrganização Mundial de Saúde (OMS), exceto.","options":{"A":"Taquicardia.","B":"Tremores.","C":"Agitação psicomotora.","D":"Alucinações.","E":"Ataxia."},"answer":"E","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-127148","number":"127148","sourceNumber":"127148","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"São consideradas categorias de risco clínico com indicação de vacina anti-influenza\nsazonal, exceto,","options":{"A":"Fibrose cística, doença cardíaca isquêmica, Síndrome da Imunodeficiência Adquirida (SIDA).","B":"Diabetes, hepatites crônica, esclerose múltipla.","C":"Doença renal cônica estágio 3, síndrome de Down, atresia biliar.","D":"Asma, insuficiência cardíaca, pós-transplantados.","E":"Hipertensão arterial, obesidade, DPOC."},"answer":"E","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-102769","number":"102769","sourceNumber":"102769","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Uma mãe muito cuidadosa vem à consulta querendo saber como proteger seu filho de\n6 meses contra acidentes. Em relação aos\nacidentes na infância, assinale a alternativa\nINCORRETA.","options":{"A":"Em crianças menores de 1 ano, atentar para o risco de aspiração e superdosagem de\nmedicamentos.","B":"As crianças maiores de 5 anos representam alto risco de intoxicação não intencionada por\nexplorarem o ambiente com seus sentidos.","C":"As queimaduras podem ocorrer em todas as idades.","D":"A partir do final do 1º ano, crianças do sexo masculino têm o dobro de chance de se acidentar."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-77362","number":"77362","sourceNumber":"77362","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Qual é, segundo a Organização Mundial de Saúde, a principal causa de morte evitável\nno mundo?","options":{"A":"Tabagismo.","B":"Hipertensão arterial.","C":"Desnutrição.","D":"Desidratação.","E":"Diabetes."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-59041","number":"59041","sourceNumber":"59041","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"A cada ano a população de idosos no Brasil aumenta. Quanto às doenças encontradas\nno idoso assinale a alternativa correta.","options":{"A":"A Doença Vascular Oclusiva Mesentérica (DVOM) é rara no idoso e pode apresentar alta\nmorbimortalidade não apresentar tratamento imediato.","B":"A isquemia mesentérica só pode ser aguda, com comprometimento arterial ou venoso.","C":"A isquemia mesentérica pode acometer o delgado ou segmentos do cólon com apresentações\nclínicas distintas.","D":"A DVOM apresenta quadro clínico característico com sintomas específicos o que facilita o seu\ndiagnóstico imediato.","E":"Os fenômenos oclusivos são responsáveis pela maioria dos quadros isquêmicos e a doença\naterosclerótica não é a principal causa desta doença."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-43299","number":"43299","sourceNumber":"43299","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Em relação às questões relacionadas ao tabagismo, marque a alternativa INCORRETA:","options":{"A":"É a principal causa de morte evitável no mundo.","B":"Em relação à prevenção secundária de eventos cardiovasculares a cessação do tabagismo é\nmais importante do que as medidas amplamente preconizadas pelas diretrizes internacionais (uso\nde betabloqueadores, inibidores da enzima conversora, vastatinas e antiagregantes plaquetários).","C":"Das mortes relacionadas ao tabaco, atualmente as neoplasias são responsáveis pela maior\nparcela.","D":"Em relação à doença pulmonar obstrutiva crônica (DPOC), a cessação do tabagismo ainda é a\núnica medida capaz de modificar sua história natural, além de reduzir sua mortalidade.","E":"Internações hospitalares são momentos ideais para sensibilização de pacientes quanto à\nnecessidade de cessação do tabagismo."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-23155","number":"23155","sourceNumber":"23155","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Adolescente de 15 anos é atendido com febre de 38,5ºC, de início há 12 horas,\nintensa mialgia, dor de cabeça, dor de garganta\ne tosse seca, além de coriza clara e obstrução\nnasal. Refere que estava bem até o dia anterior ao início dos sintomas. Ao exame o paciente está\nem regular estado geral, com febre e calafrios; é obeservado hiperemia conjuntival bilateral,\nhiperemia nasal e intensa hiperemia de orofaringe, com enantema em palato mole. A ausculta\npulmonar está normal, com frequência respiratória de 20 irpm. O restante do exame físico está\nnormal. Qual destas hipóteses diagnósticas é a mais correta para este caso?","options":{"A":"Influenza (gripe).","B":"Dengue.","C":"Rinofaringite aguda.","D":"Mononucleose infecciosa.","E":"Febre hemorrágica da Dengue."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-366958","number":"366958","sourceNumber":"366958","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Para quais das seguintes condições a eletroneuromiografia é comumente utilizada no\ndiagnóstico?","options":{"A":"Esclerose múltipla.","B":"Síndrome do túnel do carpo.","C":"Enxaqueca.","D":"Alzheimer."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-366955","number":"366955","sourceNumber":"366955","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Lucas, 33 anos, apresenta episódios recorrentes de fraqueza em um membro, visão\nturva e formigamento. A ressonância magnética revelou lesões desmielinizantes. Qual é o\ntratamento de primeira linha mais provável indicado para Lucas?","options":{"A":"Betainterferonas.","B":"Anticoagulantes.","C":"Corticoides tópicos.","D":"Antibióticos."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-366988","number":"366988","sourceNumber":"366988","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Em relação à Síndrome de Guillain-Barré, qual das seguintes afirmações é verdadeira?","options":{"A":"É uma doença autoimune que ataca principalmente os músculos esqueléticos.","B":"É comumente desencadeada por infecções bacterianas.","C":"A principal característica é a fraqueza muscular ascendente.","D":"O tratamento principal é com corticosteróides em altas doses."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-363978","number":"363978","sourceNumber":"363978","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Paciente de 57 anos, do sexo feminino, procura o serviço com queixa de fadiga. Conta\nque há 8 meses apresentou cansaço aos\nesforços e que agora tem dificuldade para subir escadas,\npara estender roupas no arame, lavar e pentear os cabelos, mas percebe períodos de melhora\napós repouso. Nega perda de peso e desconhece outras doenças. Seu exame físico geral é normal\ne a perda de força só se torna perceptível nas provas do exame neurológico que provocam fadiga\nmuscular. O restante do exame neurológico é normal. Ela realizou exame de eletroneuromiografia\n(ENMG), que demonstrou condução sensitiva normal e condução motora alterada, com potenciais\nmusculares compostos de baixa amplitude, os quais aumentaram sua amplitude em mais de 100%\napós estimulação repetitiva de alta frequência (30 Hz) em todos os músculos avaliados. Nesse\ncaso, o anticorpo a ser dosado e que confirma a hipótese diagnóstica é o anticorpo","options":{"A":"antirreceptor de acetilcolina ligador (anti-AChR ligador).","B":"anti-tirosina quinase músculo específica (anti-MUSK).","C":"antirreceptor de rianodina músculo esquelético (anti-RRi-1).","D":"anti canal de cálcio voltagem dependente (anti-VGCC)."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-362685","number":"362685","sourceNumber":"362685","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Todas as alternativas apresentam sintomas que sugerem o diagnóstico de Síndrome de\nGuillain Barré, exceto:","options":{"A":"Disfunção autonômica, em qualquer modalidade.","B":"Disfunção autonômica, em qualquer modalidade.","C":"Envolvimento de nervos cranianos.","D":"Assimetria marcante."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-363905","number":"363905","sourceNumber":"363905","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Leia o caso clínico a seguir. Mulher, 36 anos, queixou-se de mal-estar e perda de\nenergia, além de dificuldade de pentear os\ncabelos e levantar-se de uma posição sentada. Ao\nexame físico apresentava eritema-edema de cor violáceo na região periorbitária, pápulas violáceas\nna região dorsal das articulações interfalangeanas e máculas eritematosas violáceas nos cotovelos.\nConsiderando todo o quadro clínico, podemos considerar como hipótese diagnóstica","options":{"A":"psoríase.","B":"dermatomiosite.","C":"lúpus eritematoso sistêmico.","D":"esclerose sistêmica."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-354763","number":"354763","sourceNumber":"354763","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"A nova classificação da liga internacional contra a epilepsia (ILAE) divide as crises em\nfocais, generalizadas e desconhecidas. As crises focais podem ou não apresentar consciência\nalterada e podem ser de início motor ou não motor. É exemplo de crise focal de início não motor:","options":{"A":"atônica.","B":"parada comportamental.","C":"automatismos.","D":"espasmos epilépticos."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-363917","number":"363917","sourceNumber":"363917","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Qual é a principal causa de convulsões em lactentes?","options":{"A":"Hipocalcemia.","B":"Meningite.","C":"Traumas.","D":"Hipertermia."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-334096","number":"334096","sourceNumber":"334096","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"A Imunoglobulina Humana (IgIV), pela facilidade de uso, tornou-se o tratamento de\nescolha na maioria dos países, apesar de seu mecanismo de ação pouco compreendido na\nSíndrome de Guillain-Barré. Sendo correto afirmar que:","options":{"A":"Sua eficácia na recuperação motora, risco de morte e efeitos adversos comparada a tratamento\ncom plasmaférese não mostrou que os resultados dentro\nde duas semanas são semelhantes.","B":"Sua eficácia na recuperação motora, risco de morte e efeitos adversos comparada a tratamento\ncom plasmaférese mostrou que os resultados dentro de\nduas semanas são piores.","C":"Sua eficácia na recuperação motora, risco de morte e efeitos adversos comparada a tratamento\ncom plasmaférese mostrou que os resultados dentro de\nduas semanas são semelhantes.","D":"Sua eficácia na recuperação motora, risco de morte e efeitos adversos comparada a tratamento\ncom plasmaférese mostrou que os resultados dentro de\nduas semanas são melhores."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-334766","number":"334766","sourceNumber":"334766","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Qual dado semiológico é sugestivo de crises convulsivas?","options":{"A":"Movimentos de báscula de quadril.","B":"Choro durante a crise.","C":"Manutenção dos olhos fechados durante a crise.","D":"Presença de automatismos manuais com alteração da consciência."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-334767","number":"334767","sourceNumber":"334767","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Em relação às doenças desmielinizantes, e critérios diagnósticos sabe-se que:","options":{"A":"Os critérios de disseminação no tempo podem exigir uma das duas situações: a primeira é a\npresença de nova lesão em T2 (ou com realce\npor gadolínio) em uma ressonância de controle, a\nqualquer tempo, quando comparada à ressonância inicial; a segunda caracteriza-se pela presença\nde, pelo menos, uma lesão captante simultânea à lesão não captante, em uma mesma imagem por\nressonância.","B":"A confirmação do diagnóstico da síndrome do espectro neuromielite óptica, necessita da\npresença de anticorpos antiaquaporina 4 no soro ou no líquor do paciente.","C":"Os critérios de disseminação no espaço para o diagnóstico da esclerose múltipla incluem a\npresença de uma lesão em T2 em, pelo menos, duas das quatro topografias: justacortical,\nperiventricular, infratentorial e medula espinhal, incluindo o nervo óptico necessariamente.","D":"O exame de líquor na esclerose múltipla primariamente progressiva deve ter a presença de\nBandas oligoclonais associado a índice de IgG\naumentado."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-330082","number":"330082","sourceNumber":"330082","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"A Síndrome de West é uma síndrome da infância caracterizada pela tríade: I.\nEspasmos, que podem ser em extensão ou em flexão, com apresentação em salvas. II.\nHipsarritmia no EEG, caracterizada pela presença de ondas lentas de alta voltagem. III. Crises\nepilépticas polimorfas intratáveis (em geral, tônicas, atônicas ou de ausência atípica). Das\nproposições acima, estão CORRETAS:","options":{"A":"I e II, apenas.","B":"I e III, apenas.","C":"II e III, apenas.","D":"Todas estão corretas."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-346433","number":"346433","sourceNumber":"346433","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Homem de 35 anos, etilista (1 litro de destilado ao dia) há 5 anos. Refere que há uma\nsemana iniciou com parestesias nos pés, que\nprogrediram de maneira ascendente. Há dois dias\nevoluiu com redução progressiva de força em MMII e há um dia não consegue mais deambular. O\nexame neurológico evidencia força grau I e ausência de reflexos em MMII, força grau V em MMSS\ncom reflexos preservados. As sensibilidades dolorosa e vibratória estão preservadas; não foi\nevidenciado nível sensitivo. O hemograma demonstra anemia macrocítica. A radiografia de coluna\nlombossacral é normal. O exame do líquor revela: celularidade= 4 células/mm3; glicose= 70 mg/dL;\nproteína= 210 mg/dL. Assinale a alternativa CORRETA que apresenta o diagnóstico mais provável:","options":{"A":"Deficiência de vitamina B12;","B":"Polineuropatia alcoólica.","C":"Síndrome de Guillain-Barré.","D":"Mielite transversa."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-334125","number":"334125","sourceNumber":"334125","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Sobre os fármacos de segunda linha no tratamento do Status Epileticus (SE) assinale a\nalternativa incorreta.","options":{"A":"Devido aos efeitos adversos causados pela dificuldade de metabolização e eliminação da\nfenitoína, o fenobarbital é utilizado, preferencialmente em neonatos.","B":"O principal efeito adverso do fenobarbital é de depressão neurológica, enquanto a fenitoina\napresenta efeitos adversos cardiovasculares, como arritmia e hipotensão.","C":"Para evitar os efeitos adversos da fenitoína, recomenda-se que a sua administração ocorra em\ncerca de 10 minutos.","D":"Como a maior parte da fenitoína se liga a proteínas plasmáticas, situações de hipoalbuminemia\naumentam o risco de toxicidade pelo aumento de sua fração livre."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-346437","number":"346437","sourceNumber":"346437","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Criança de 01 ano, apresentou crise convulsiva tônico clônica generalizada inédita, com\nduração de 03 minutos, há 01 hora, em vigência de febre de 39,5°C. No momento está\nassintomática e sem alterações no exame físico. Após triagem infecciosa foi evidenciado um\nquadro de infecção urinária. Além de controle de temperatura, qual a conduta mais adequada?","options":{"A":"Antibioticoterapia e benzodiazepínico;","B":"Coleta de líquor e antibioticoterapia;","C":"Antibioticoterapia e observação clínica;","D":"Benzodiazepínico e observação clínica."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-331992","number":"331992","sourceNumber":"331992","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Sobre convulsão febril (CF) na infância, indique a alternativa incorreta:","options":{"A":"O risco de um novo episódio convulsivo durante o mesmo quadro febril é raro, embora possa\nocorrer.","B":"O diagnóstico de CF na infância é essencialmente clínico, tornando fundamentais a anamnese\ndetalhada e o exame físico minucioso.","C":"Crianças com CF têm risco discretamente aumentado para crises focais complexas, da mesma\nforma que outros tipos de epilepsia, quando comparadas com a população geral.","D":"Nos casos em que a criança está em convulsão, o tratamento agudo é igual a qualquer crise\nepiléptica, independentemente de sua etiologia.","E":"A CF simples tem apresentação generalizada, duração inferior a 30 minutos e não recorre em\nmenos de 24 horas."},"answer":"E","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-337424","number":"337424","sourceNumber":"337424","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"São os tipos mais comuns do mediastino posterior:","options":{"A":"Tumores neurogênicos.","B":"Linfomas.","C":"Cisto broncogênicos.","D":"Tumores de células germinativas."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-337425","number":"337425","sourceNumber":"337425","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Os tumores de mediastino são neoplasias raras e aproximadamente 30% dos pacientes\nadultos apresentam sintomas, sendo alguns deles mais comuns de acordo com o tipo de tumor. 1.\nLinfoma. A. Dispneia, chiado e hemoptise. 2. Timoma com miastenia gravis. B. Sudorese noturna,\nperda de peso, fadiga, adenopatia extratorácica, elevação da PCR e leucocitose. 3. Granuloma\nmediastinal. C. Massa testicular, elevação do ?-HCG e AFP em homens jovens. 4. Tumor de\ncélulas germinativas. D. Fraqueza flutuante no decorrer do dia, fadiga precoce, ptose e diplopia.\n\nAssinale a alternativa com a correta associação entre o tipo de tumor e sintomas associados.","options":{"A":"1-B, 2-D, 3-C, 4-A","B":"1-B, 2-D, 3-A, 4-C","C":"1-C, 2-A, 3-B, 4-D","D":"1-A, 2-B, 3-D, 4-C"},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-337426","number":"337426","sourceNumber":"337426","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"A localização mais comum dos tumores neurogênicos do tórax é:","options":{"A":"Mediastino anterior.","B":"Mediastino médio.","C":"Mediastino lateral.","D":"Mediastino posterior."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-337427","number":"337427","sourceNumber":"337427","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Essa síndrome é mais comum em mulheres de meia-idade e consiste na compressão\nda veia subclávia e dos nervos do plexo\nbraquial. As regiões mais afetadas são o triângulo\ninterescaleno (artéria e nervos), o espaço costoclavicular (veia) e a área subcoracoide (artéria,\nveia\ne nervos).","options":{"A":"Pectus escavatum.","B":"Síndrome da Veia Cava superior.","C":"Síndrome do desfiladeiro torácico.","D":"Síndrome da Subclávia aberrante."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-321584","number":"321584","sourceNumber":"321584","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Leia o caso clínico. Um paciente com histórico de epilepsia é trazido ao\n\npronto-atendimento por crises convulsivas. Sua mãe refere que as crises têm duração de dois a\ntrês-minutos. O paciente manifestou três crises seguidas, sem retorno ao seu estado basal. O\npasso seguinte de manejo clínico desse paciente é o de ofertar o seguinte medicamento:","options":{"A":"levetiracetam","B":"fenitoína","C":"fenobarbital","D":"diazepan"},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-334811","number":"334811","sourceNumber":"334811","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"A convulsão febril constitui uma das grandes causas de consultas de crianças em\nUnidades de Pronto Atendimento. Geralmente se constitui em um evento benigno, porém existe\numa condição que aumenta o risco de recorrência, que é","options":{"A":"proveniente de faringoamigdalite.","B":"história familiar de síndrome epiléptica.","C":"Idade inferior a 1 ano de idade.","D":"distúrbio metabólico associado."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-337435","number":"337435","sourceNumber":"337435","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Homem de 42 anos vítima de politraumatismo foi submetido à tomografia de tórax que\nidentificou fratura de costela à esquerda e observou-se também a presença de lesão sólida de 3 x 4\nx 6 cm em goteira paravertebral à esquerda. De acordo com a epidemiologia das lesões de\nmediastino, assinale a principal hipótese diagnóstica.","options":{"A":"Teratoma.","B":"Tumor de célula germinativa.","C":"Tumor neurogênico.","D":"Linfoma."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-300794","number":"300794","sourceNumber":"300794","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Assinale a alternativa que apresenta a forma comum de epilepsia focal de difícil\ncontrole medicamentoso em adultos, cujo quadro\nclínico se caracteriza por crises focais com\nconsciência preservada simples. Mais frequentemente, sensação visceral, epigástrica ou torácica\nascendente, que pode associar-se a outros sintomas autonômicos, sensações psíquicas de\ndesrealização ou despersonalização, medo ou fenômenos dismnésicos, seguidos de perda de\ncontato com o meio, com reação de parada, olhar vago e fixo, e automatismos oromastigatórios e\nmanuais, com ocorrência rara de crises secundariamente generalizadas. As crises se iniciam na\ninfância tardia e na adolescência, porém, ocasionalmente, alguns pacientes manifestam o quadro\nna idade adulta:","options":{"A":"Epilepsia benigna da infância com descargas centrotemporais.","B":"Epilepsia temporal associada à esclerose de hipocampo.","C":"Epilepsia focal associada a distúrbios do desenvolvimento cortical.","D":"Epilepsia associada a tumores."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-316299","number":"316299","sourceNumber":"316299","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Paciente politraumatizado de 35 anos chega na UPA de Rio Verde; na admissão\nsuspeita, de traumatismo raquimedular. Ao\nexame, o interno de medicina de FAMERV percebeu\nque o paciente apresentava perda de sensibilidade à dor e à temperatura, porém a sensibilidade\nproprioceptiva ao posicionamento, à vibração e à pressão profunda está preservada. Qual o nome\ndessa síndrome medular?","options":{"A":"Síndrome central da medula.","B":"Síndrome de Brown-Séquard.","C":"Síndrome anterior da medula.","D":"Síndrome do cone medular."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-315781","number":"315781","sourceNumber":"315781","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Assinale a alternativa incorreta sobre as Crises Não Epilépticas Psicogênicas (CNEP).","options":{"A":"Os sintomas são facilmente distinguíveis das crises epilépticas.","B":"Os sintomas motores são mais comuns em adolescentes.","C":"As CNEPs são geralmente desencadeadas por dificuldades interpessoais ou escolares.","D":"O registro dos episódios por meio de um vídeo EEG é importante para o diagnóstico."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-300830","number":"300830","sourceNumber":"300830","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"As crises epilépticas correspondem a uma manifestação clínica em que a atividade\nneuronal do córtex cerebral apresenta\ndescarga excessiva e de maneira sincrônica. Algumas crises\nrefletem a presença de anormalidade cerebral subjacente, enquanto outras correspondem a uma\natividade cerebral normal a eventos externos, como febre, distúrbios hidroeletrolíticos ou\nintoxicação exógena. Nesse contexto, cujo conceito refere ao estado de mal epiléptico, é\nCORRETO afirmar:","options":{"A":"Distúrbio cerebral caracterizado pela predisposição do cérebro para gerar crises epilépticas e\npelas consequências neurológicas, cognitivas, psicológicas e sociais dessa condição.","B":"Crise única ou repetitiva, sem retorno do nível de consciência no período de 30 minutos.","C":"Disfunção transitória de uma parte ou de todo o cérebro com descarga excessiva de uma\npopulação de neurônios hiperexcitáveis que leva a manifestações de natureza motora, sensorial,\npsíquica ou autonômica.","D":"Alteração no funcionamento cerebral, caracterizada por uma descarga excessiva e síncrona de\num agrupamento neuronal, que não interfere no\nnível de consciência."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-294300","number":"294300","sourceNumber":"294300","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Mulher de 43 anos, queixando-se de dificuldade em pentear os cabelos, subir escadas\ne disfagia. Clinicamente, apresentava eritema\nróseo-violáceo nas pálpebras, região malar, fronte e\ntêmporas com edema periorbitário. Nas mãos, apresentava placas eritematosas sobre as\narticulações interfalangianas e máculas eritemato-violáceas na região do V do decote. Os exames\nlaboratoriais demonstravam aumento dos níveis séricos de creatinofosfoquinase, aldolase,\ntransaminases (ALT, AST) e desidrogenase láctica. Nesse caso, o diagnóstico da paciente é:","options":{"A":"Esclerose sistêmica.","B":"Dermatomiosite.","C":"Lúpus eritematoso discoide.","D":"Lúpus eritematoso subagudo."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-308285","number":"308285","sourceNumber":"308285","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Sobre a miastenia gravis é correto afirmar:","options":{"A":"Sintomas principais são fraqueza e fadiga muscular.","B":"Pico de incidência em mulheres de 20 a 30 anos.","C":"Mulheres são mais afetadas que homens.","D":"Todas as alternativas são corretas."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-316373","number":"316373","sourceNumber":"316373","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Paciente de 7 anos de idade dá entrada em pronto socorro pediátrico inconsciente,\napresentando hipertonia dos membros associada a\nabalos generalizados, sialorreia excessiva e em\nvigência de febre alta. Imediatamente é feito o manejo de primeiros socorros e colocada em\nposição lateral para prevenir aspiração. Dentre as alternativas, qual o diagnóstico, medicamento,\ndose e a via mais adequada a ser utilizada no caso em questão:","options":{"A":"Crise convulsiva tônico-clônica generalizada, fenitoína 15mg/kg/dose, via intramuscular.","B":"Crise convulsiva tônico-clônica generalizada, diazepam 0,3 a 0,5mg/kg/dose, via endovenosa ou\nretal.","C":"Crise convulsiva febril, fenitoína 5 a 8 mg/kg/dose, via endovenosa.","D":"Crise convulsiva febril, fenobarbital 20mg/kg/dia, via intramuscular."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-308306","number":"308306","sourceNumber":"308306","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Sobre as convulsões febris, podemos afirmar:","options":{"A":"A maioria das convulsões febris evoluirá para epilepsia.","B":"Convulsões febris ocorrem em cerca de 2% a 5% das crianças entre seis meses e cinco anos de\nidade.","C":"Frequentemente, uma convulsão febril pode ser o primeiro sinal de um distúrbio neurológico\nainda não reconhecido.","D":"As crianças só necessitam de medicamentos abortivos de crises caso elas durem 10 minutos ou\nmais para minimizar o risco de uma convulsão prolongada ou estado de mal epiléptico."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-281981","number":"281981","sourceNumber":"281981","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Paciente M.D.R. 37 anos, queixa de fadiga e astenia progressiva há 1 ano, com\nalteração do paladar e dificuldade de\nequilíbrio nos últimos três meses. Nega outras queixas. HPP:\nHipotireoidismo de Hashimoto há 3 anos em uso levotiroxina 100mcg/dia. Nega cirurgias e outras\ncomorbidades. G2P1A1, aborto no primeiro trimestre gestacional há 2 anos. HF: Mãe, 59 anos, tem\nvitiligo. Desconhece história paterna. 2 irmãos mais novos hígidos. Ao exame: BEG, hipocorada\n\n+++/4+, acianótica, anictérica. AR: MVF sem RA. Fr 18irpm. Sat O2 96%; ACV: RCR em 2T. BNF.\nSopro holossistólico panfocal. PA: 120/70mmHg.\nFc: 103bpm. AGI: Abdome livre, algo doloroso\ndifusamente, sem visceromegalias. RHA+, DB negativo. Neurológico: Romberg+, ataxia de marcha,\nhiper-reflexia, parestesia em mãos e pés. Glasgow 15, sem outras alterações. Qual a principal\nhipótese diagnóstica e qual exame confirma seu diagnóstico?","options":{"A":"Esclerose múltipla - critérios clínicos.","B":"Esclerose lateral amiotrófica - RNM.","C":"Anemia aplástica - biópsia de medula óssea.","D":"Anemia perniciosa - anticorpos antifator intrínseco."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-281983","number":"281983","sourceNumber":"281983","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Crise epiléptica em adultos que começa com um período de estado alterado da\npercepção. Consiste num breve estado de\n\"branco\", responsividade diminuída ou alterada, e\ncessação súbita ou pausa na atividade. O paciente vai parecer \"desligado\", desatento aos seus\narredores, e pode também parecer torporoso. Trata-se da:","options":{"A":"Crise de ausência.","B":"Crise insular.","C":"Crise focal sensitiva.","D":"Crise disperceptiva."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-281275","number":"281275","sourceNumber":"281275","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Assinale a alternativa correta sobre a Síndrome de West.","options":{"A":"Quando ocorrem padrão de hipsarritmia no EEG, espasmos em flexão e parada ou regressão do\ndesenvolvimento, a tríade da doença é incompleta.","B":"O padrão de hipsarritmia ocorre em lactentes com a síndrome, que corresponde a uma condição\nepiléptica que cursa com espasmos e regressão do desenvolvimento.","C":"O pico de incidência ocorre entre 3 e 7 anos de idade e, algumas vezes, o diagnóstico pode ser\natrasado por confusão com cólicas, irritabilidade ou hiper-reatividade a estímulos.","D":"O prognóstico é bom, mas demanda investigação etiológica."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-277424","number":"277424","sourceNumber":"277424","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Uma paciente do sexo feminino com 40 anos é avaliada por queixa de cansaço e\ndesconforto respiratório progressivo. Aprofundando a anamnese ela relata ainda disfagia, ptose\npalpebral assimétrica e diplopia que piora no período noturno. Avaliando a tomografia de tórax\nsolicitada, foi encontrada massa lobulada no terço antero-superior central do tórax. A hipótese\ndiagnóstica mais provável é:","options":{"A":"tumor de Pancoast","B":"linfoma","C":"teratoma","D":"timoma"},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-258181","number":"258181","sourceNumber":"258181","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Uma mulher de 22 anos inicia fraqueza proximal de evolução de nove meses. A\nfraqueza se acentuava aos esforços como subir escadas ou descer escadas. Associado,\napresentou diploplia, disartria e ptose palpebral, boca e olhos secos. O exame de\neletroneuromiografia demonstrou bloqueio neuromuscular que melhorava com a estimulação\nrepetitiva de alta frequência. Sobre a síndrome de Eaton-Lambert, pode-se afirmar:","options":{"A":"não existem diferenças clínicas importantes entre os pacientes que apresentam associação com\ncâncer e as que não apresentam esta associação, seja no quadro clínico, seja na idade e no sexo.","B":"o tumor mais comumente presente nos casos que se associam com câncer são os tumores\nginecológicos na mulher e de próstata no homem, independente da idade e do sexo.","C":"doenças autoimunes concomitantes, tais como artrite reumatoide, hipertiroidite e anticorpos do\ntipo anti-P/Q do complexo VGKC, são mais comuns nos casos não ligados ao câncer.","D":"o diagnóstico é semelhante ao da miastenia gravis, sendo o achado da eletroneuromiografia\nmuito característico: potenciais de alta voltagem que,\ncom estimulação repetitiva, aumentam sua\namplitude."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-258182","number":"258182","sourceNumber":"258182","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Jovem de 31 anos apresentou quadro de febre, dor de garganta e mialgia após um\ncontato suspeito há uma semana atrás e evoluiu\napós cinco dias com tosse seca. Procurou o posto\nmédico e fez PCR para covid-19 e, após nove dias, ficou sabendo que o teste foi positivo. Foi\norientado a hidratar-se, tratar febre e dor com analgésicos, mas com duas semanas evoluiu com\nfraqueza ascendente e dificuldade respiratória. Foi internado e seu exame demonstrava uma\ntetraparesia flácida, ausência de reflexos, urina normal, intestino normal, sem dor, pressão em\nníveis normais. Em relação ao caso, o paciente apresenta quadro de:","options":{"A":"Miopatia, e deverá ser realizada para diagnóstico, dosagem de enzimas hepáticas e musculares\ne eletroneuromiografia.","B":"Mielite transversa extensa, e o diagnóstico deverá ser realizado com ressonância de coluna e\nliquor.","C":"Polirradiculoneurite aguda, e o diagnóstico deverá ser realizado com exame de\neletroneuromiografia e exame de liquor.","D":"Neuropatia do paciente crítico, e o diagnóstico deverá ser realizado com exame de\neletroneuromiografia e liquor."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-273154","number":"273154","sourceNumber":"273154","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Síndrome de West é geneticamente determinada e costuma aparecer entre os 3\nmeses. Quanto às características da Síndrome de West, é CORRETO afirmar:","options":{"A":"É uma doença de crianças, caracterizando-as como obesas e com pouco tônus muscular, não\nafetando a capacidade mental nem mesmo as glândulas sexuais que produzem hormônios\nnormalmente.","B":"É uma doença genética rara caracterizada pelo envelhecimento acelerado das crianças. As\ncrianças nascem saudáveis, mas em poucos meses a doença mostra o seu lado, dando o aspecto\nà criança como de um ancião.","C":"É conhecida como a doença dos tiques e as crianças que a sofrem realizam movimentos rápidos\ne involuntários dos músculos e produção\ninvoluntária de ruídos e palavras.","D":"É uma das encefalopatias epilépticas que surgem na lactância, sendo caracterizada por\nespasmos infantis, interrupção do desenvolvimento e uma alteração específica no\neletroencefalograma, chamada de hipsarritmia."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-274829","number":"274829","sourceNumber":"274829","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Lactente, iniciou quadro agudo de febre elevada, no primeiro dia já com 38°C. Mãe\ndeixou lactente no berço e foi preparar a\nmedicação, antitérmico, ao retornar encontrou o lactente\napresentando desvio do olhar, movimentos tônicos clônicos generalizados, liberação esfincteriana,\nmuita salivação. Acionou serviço de resgate, demorou cerca de 5 minutos para adentrar na Unidade\nde Pronto Atendimento (UPA). Lactente encontrava-se febril, sonolento, respirando\nespontaneamente, sinais vitais preservados. História familiar que o pai quando criança apresentou\nepisódios de convulsão com febre. Qual o diagnóstico e a conduta adequada?","options":{"A":"Crise convulsiva febril + antitérmico.","B":"Crise convulsiva febril + Diazepam.","C":"Epilepsia + anticonvulsivante.","D":"Crise convulsiva febril + anticonvulsivante."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-229823","number":"229823","sourceNumber":"229823","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"A convulsão febril benigna é um evento comum na faixa etária pediátrica, associado a\nfebre, sem evidência de infecção intracraniana ou de outra doença neurológica aguda, e não\nprecedido por crises afebris. Sobre este evento podemos afirmar que:","options":{"A":"o pico de incidência predomina entre os 6 e 9 meses de idade.","B":"deve ser prontamente avaliada pelo importante risco de morbidade e de mortalidade.","C":"o EEG na crise febril tem valor limitado, porque a presença de anormalidades não define o\ndiagnóstico e não modifica a conduta.","D":"a ocorrência de epilepsia em crianças que tiveram crises febris, mesmo que atípicas, é a mesma\nesperada para a população em geral."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-252746","number":"252746","sourceNumber":"252746","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Em relação à esclerose múltipla, marque a alternativa incorreta:","options":{"A":"É mais comum em mulheres e seu início geralmente ocorre entre 20 e 40 anos.","B":"São fatores de risco para o aparecimento da doença a exposição ao vírus Epstein-Barr após a\nprimeira infância e tabagismo.","C":"A doença é mais comum em negros.","D":"Trata-se de uma doença autoimune, que se caracteriza por inflamação, desmielinização, gliose e\nperda neuronal."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-252768","number":"252768","sourceNumber":"252768","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Um pré-escolar de 3 anos de idade apresentou crise convulsiva em casa, tônico-clônica\ngeneralizada, com liberação de esfincter, com duração de três minutos. Já no pronto-atendimento,\nobservou-se sonolência 30 min após a crise, melhorando após esse período. A mãe nega alergias\nou antecedentes de internações, cirurgias ou outro episódio semelhante à crise. A mãe relatava\ntosse e coriza há um dia, e no exame físico observaram-se sinais vitais preservados, FC 125bpm,\nFR 44 irpm, temperatura axilar de 38 graus, PA 86/48mmHg, ausculta cardíaca e respiratória\nnormais, hiperemia de orofaringe, ausência de meningismo ou sinais neurológicos focais. Nesse\nmomento, a conduta mais adequada seria:","options":{"A":"Internação hospitalar para investigação, já que se trata da primeira crise convulsiva.","B":"Manter o paciente em observação algumas horas devido ao risco de nova crise e alta com\nencaminhamento ambulatorial ao especialista.","C":"Tranquilizar a família sobre benignidade do quadro e prescrever sintomáticos.","D":"Manter observação até avaliação do especialista devido à sonolência que o paciente apresentou\napós a crise."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-246573","number":"246573","sourceNumber":"246573","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Sobre os distúrbios neurodegenerativos da infância, assinale a alternativa incorreta.","options":{"A":"Os distúrbios de substância branca costumam se apresentar com espasticidade e sinais de\nneurônio motor superior, enquanto os\ndistúrbios primariamente de substância cinzenta cursam com\ncrises epilépticas e deficiências visual e intelectual.","B":"Dentre as esfingolipidoses, as gangliosidoses se apresentam em 2 tipos: GM1 e GM2. A primeira\napresenta 3 subtipos, classificados de acordo com a idade de apresentação, e as gangliosidoses\nGM2 apresentam diversos subtipos, incluindo a doença de Tay-Sachs, a doença de Sandhoff e as\ngangliosidoses GM2 juvenil e do adulto.","C":"Os sintomas da doença de Krabbe se manifestam nos primeiros meses de vida com irritabilidade\ne choros excessivos, hiperpirexia sem\nexplicação, problemas de alimentação e vômitos.","D":"A leucodistrofia metacromática (LDM) infantil tardia começa de modo insidioso com distúrbios de\nmarcha por volta de 1 a 2 anos de idade. Cursa com hiperreflexia tendinosa profunda e hipertonia\nmuscular, comprometendo a locomoção da criança.","E":"As lipofuscinoses ceroides neuronais são a classe mais comum de doenças neurodegenerativas\nem crianças e consistem em três distúrbios de\nherança autossômica recessiva."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-241742","number":"241742","sourceNumber":"241742","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Sobre o estado de mal epiléptico, jugue os itens seguintes. I. Trata-se de uma crise\nepiléptica contínua, com duração superior a\n20-30 minutos, ou ocorrência de crises em série, entre\nas quais não há recuperação da consciência. II. As crises febris prolongadas e os estados de mal\nepiléptico idiopático ou sintomático são subtipos do estado de mal epiléptico em crianças. III.\nDurante crises prolongadas, as áreas do sistema nervoso central mais afetadas pela\n\"excitoxicidade\" são: hipocampo, amígdala, cerebelo, córtex médio e tálamo. IV. Os\nbenzodiazepínicos podem ser administrados por via intravenosa (IV) ou intramuscular (IM) no\nestado de mal epiléptico, sem diferenças significativas de efeito terapêutico. Pode-se afirmar que:","options":{"A":"apenas os itens I, II e III estão corretos.","B":"apenas os itens I, II e IV estão corretos.","C":"apenas os itens II, III e IV estão corretos.","D":"todos os itens estão corretos.","E":"apenas os itens II e IV estão corretos."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-246576","number":"246576","sourceNumber":"246576","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Sobre os traumatismos raquimedulares em pediatria, julgue os itens a seguir. I. Os\ntraumas raquimedulares sem lesão radiográfica são\nmais comuns em crianças que em adultos e se\napresentam em duas formas distintas, de acordo com a faixa etária acometida. II. Os traumas\nraquimedulares sem lesão radiográfica costumam decorrer de traumas mais graves, quanto maior a\nidade de ocorrência. III. As lesões medulares mais graves podem transcorrer com choque espinal,\nque pode persistir por até 4 semanas após o trauma. IV. Mesmo em lesões medulares graves,\nmenos de 10% dos pacientes costumam apresentar trauma craniano associado. Pode-se afirmar\nque:","options":{"A":"todos os itens estão certos.","B":"apenas os itens I, II e IV estão certos","C":"apenas os itens I e IV estão certos.","D":"apenas os itens I, II e III estão certos.","E":"apenas os itens I e III estão certos."},"answer":"E","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-229875","number":"229875","sourceNumber":"229875","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"A alternativa que NÃO corresponde aos sinais ou sintomas presentes na\nDermatopolimiosite é","options":{"A":"Heliotropo","B":"Rash malar","C":"Fraqueza muscular assimétrica e distal","D":"Pápulas Gottron"},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-254290","number":"254290","sourceNumber":"254290","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Poliana retorna em consulta de pré-natal com 32 semanas e 2 dias com queixa há 2\nsemanas de dormência e formigamento nas\nmãos, pior à direita. Os sintomas são piores à noite e\naliviam ao chacoalhar as mãos. Ao exame, apresenta parestesia no 2º e 3º dedos da mão direita\ndurante o teste de Phallen. Assinale qual seria a principal hipótese diagnóstica e o manejo inicial\nmais adequado, respectivamente:","options":{"A":"Síndrome do túnel do carpo e imobilização do punho com tala à noite.","B":"Polineuropatia e solicitação de eletroneuromiografia.","C":"Tenossinovite de De Quervain e encaminhamento à fisioterapia.","D":"Radiculopatia de C6-C7 e encaminhamento à ortopedia."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-216673","number":"216673","sourceNumber":"216673","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Adolescente de 17 anos, portador de epilepsia, em uso irregular das medicações, é\nadmitido no pronto-socorro em crises epilépticas reentrantes, sem recobrar a consciência entre as\ncrises, de início há 8 minutos. Após a administração de diazepam e cessação da crise, foi iniciada a\ninfusão de fenitoína. Mesmo após dose máxima de fenitoína, o paciente voltou a apresentar nova\ncrise convulsiva. Após nova dose de diazepam e cessação da crise, a medicação a ser\nadministrada nessa etapa deve ser:","options":{"A":"Midazolam.","B":"Tiopental.","C":"Fenobarbital.","D":"Carbamazepina."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-205633","number":"205633","sourceNumber":"205633","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Fazem parte do diagnóstico neurofisiológico da Síndrome de Guillain-Barré todos os\nachados abaixo, EXCETO:","options":{"A":"Bloqueio da condução motora parcial ou total.","B":"Velocidade de condução nervosa diminuída.","C":"Abolição do reflexo H.","D":"Presença de hipsarritmia no eletroencefalograma."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-215453","number":"215453","sourceNumber":"215453","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Durante seu plantão em um Pronto atendimento você recebe uma criança de 4 meses,\nque apresentou, segundo os pais, movimentos\nrepetitivos de versão cefálica e desvio ocular para a\nesquerda, com breves períodos de perda de contato com o meio. Após 20 minutos do início dos\nepisódios chegaram ao hospital, e a criança evoluiu com abalos clônicos no hemicorpo esquerdo e,\nem seguida, abalos tônico-clônicos generalizados. Após a realização das medidas de suporte e\nrealização da fenitoína na dose correta o paciente não apresentou melhora. Quais opções abaixo\nseria a conduta mais adequada nesse momento?","options":{"A":"Propofol ou cetamina.","B":"Anestésico inalatório ou midazolan contínuo.","C":"Administrar doses de diazepan a cada 5 minutos durante 1 hora se as crises persistirem.","D":"Fenobarbital ou midazolan contínuo."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-205640","number":"205640","sourceNumber":"205640","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"A epilepsia caracterizada pelo espasmo infantil compreende todas as abaixo, EXCETO:","options":{"A":"Está relacionada ao despertar do ciclo sono ? vigília.","B":"Não há tratamento medicamentoso específico para este tipo de crise epiléptica.","C":"Ocorre em salvas.","D":"Se associada ao atraso do desenvolvimento neuropsicotor e hipsarritmia no\neletroencefalograma, sempre será a síndrome de West."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-215458","number":"215458","sourceNumber":"215458","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Você está de plantão no Pronto-socorro e atende uma criança que se encontra em\nestado de mal epiléptico. Para tratamento inicial desse paciente você deve ter a preocupação de\nusar um medicamento com todas as especificações abaixo, EXCETO","options":{"A":"baixo risco de efeitos colaterais.","B":"alta eficácia.","C":"início de efeito lento.","D":"baixo risco de recorrência."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-210535","number":"210535","sourceNumber":"210535","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Sobre paciente com quadro de síndrome do túnel do carpo, podemos dizer que o nervo\nacometido nessa região é o seguinte:","options":{"A":"Ulnar","B":"Radial","C":"Cutâneo lateral","D":"Mediano","E":"Cutâneo medial"},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-201688","number":"201688","sourceNumber":"201688","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"A alteração mais comum do nervo mediano é a sua compressão no punho, denominada\nsíndrome do túnel do carpo. Entretanto, existem várias outras afecções que acometem o nervo\nmediano e alguns achados clínicos e/ou eletrofisiológicos conduzem ao diagnóstico diferencial,\ncomo a ocorrência de:","options":{"A":"Atrofia do músculo abdutor curto do polegar.","B":"Hipoestesia do primeiro ao terceiro dedos.","C":"Sinal de Tinel na região anterior do punho.","D":"Atrofia dos músculos proximais do antebraço."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-217044","number":"217044","sourceNumber":"217044","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"O Estado de Mal Epiléptico (EME) é a emergência neurológica mais frequente em\npediatria, de distribuição universal, sem\npredileção de idade, sexo ou cor. Para controle das crises,\né (são) necessária (s) qual(is) das seguinte (s) medida (s)? I. Manter vias aéreas pérvias, obter\nacesso venoso periférico, aspiração bucal frequente. II. Administrar benzodiazepínicos (diazepam\nou midazolam) para controle imediato da crise. III. Administrar fármacos de segunda linha, como\nfenitoína ou ácido valproico, prolongando o efeito antiepilético. Pode-se afirmar que:","options":{"A":"Apenas o item I está certo.","B":"Apenas o item II está certo.","C":"Apenas o item III está certo.","D":"Apenas os itens I e II estão certos.","E":"Todos os itens estão certos."},"answer":"E","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-210525","number":"210525","sourceNumber":"210525","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"A crise febril (CF) é definida como \"crise epiléptica ocorrida entre os 6 meses e 6 anos\nde idade, em vigência de doença febril\". Em\nalguns casos, a crise febril apresenta: I. recuperação\nlenta ou alteração neurólogica pós-ictal. II. uso de antimicrobianos sistêmicos no decorrer da\ndoença febril. III. sinais sugestivos de infecção do sistema nervoso central. Quais dos itens acima\nindicam propedêutica específica, já a partir do primeiro episódio de crise febril?","options":{"A":"Apenas o item I.","B":"Apenas os itens I e II.","C":"Apenas os itens I e III.","D":"Nenhum dos itens.","E":"Todos os itens."},"answer":"E","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-214187","number":"214187","sourceNumber":"214187","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"A Esclerose Lateral Amiotrófica (ELA) é uma doença neuromuscular degenerativa e de\ncausa desconhecida que compromete o Sistema\nNervoso Central e o Periférico. Quanto à ELA,\nafirma-se que, EXCETO:","options":{"A":"é uma das principais doenças neurológicas, além do Parkinson e Alzheimer.","B":"é mais prevalente entre 55 a 75 anos.","C":"em mais 90% dos casos está relacionado á mutação do gene SOD1.","D":"o quadro clínico está relacionado à perda de neurônios do sistema motor."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-214996","number":"214996","sourceNumber":"214996","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"O diagnóstico de convulsão febril na infância é eminentemente clínico, e, para tanto,\nalguns critérios devem ser considerados. Dos critérios a seguir, qual tem relação com convulsão\nfebril?","options":{"A":"aparecimento de quadro febril na faixa etária dos 9 meses aos 9 anos","B":"presença de episódio recorrente do mesmo quadro febril","C":"presença de crise convulsiva generalizada","D":"convulsão após 24 horas de início do quadro febril"},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-216448","number":"216448","sourceNumber":"216448","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Paciente de 3 anos de idade dá entrada em pronto-socorro pediátrico com quadro de\ncrise convulsiva tônico-clônica generalizada em vigência de febre alta. Imediatamente é feito o\nmanejo de primeiros socorros com proteção de vias aéreas, respiração e circulação e colocada em\nposição lateral para prevenir aspiração. Dentre as alternativas, qual o medicamento, a dose e a via\nmais adequada a ser utilizada no caso em questão?","options":{"A":"Fenitoína, 15 mg/kg/dose, via intramuscular.","B":"Diazepam, 0,3 a 0,5 mg/kg/dose, via endovenosa ou retal.","C":"Fenitoína, 5 a 8 mg/kg/dose, via endovenosa.","D":"Diazepam, 0,2 a 0,5 mg/kg/dose, via intramuscular."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-187703","number":"187703","sourceNumber":"187703","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Uma paciente, 62 anos, portadora de Hipertensão Arterial Sistêmica, Diabetes Mellitus\ntipo 2 e Fibrilação Atrial Crônica, dá\nentrada ao pronto socorro da Santa Casa de Misericórdia de\nGoiânia, com um quadro agudo de desvio da rima labial para o lado esquerdo, disartria, além de\ndificuldade para fechar o olho direito. A paciente ainda apresentava assimetria das rugas frontais,\ncom fraqueza à direita, ao franzir a testa para cima. O restante do exame neurológico era normal. A\npaciente vinha em uso de: Losartana, Metformina e Marevam, este último está na faixa terapêutica.\nO provável diagnóstico e topografia da lesão são, respectivamente:","options":{"A":"Acidente vascular encefálico, hemisfério cerebral esquerdo.","B":"Acidente vascular encefálico, hemisfério cerebral direito.","C":"Acidente vascular encefálico, tronco encefálico à esquerda.","D":"Paralisia facial periférica, nervo facial direito."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-173519","number":"173519","sourceNumber":"173519","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Paciente do sexo feminino, de 28 anos, previamente hígida, apresenta-se com quadro\nde dor ocular de início há seis horas no\nolho direito, de caráter progressivo, com escotoma e dor à\nmovimentação lateralizada do olhar. No exame ocular, movimentos dos olhos normais, acuidade\nvisual 20/20 bilateralmente, reflexos pupilares com reação fotomotora diminuída do olho direito. RM\ndemonstrou duas lesões periventriculares na substância branca, sem realce de gadolínio. Qual é o\nexame importante para o diagnóstico do sintoma visual?","options":{"A":"Medida de pressão intraocular.","B":"Angioflurosceína.","C":"Campimetria.","D":"Reações sorológicas."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-173522","number":"173522","sourceNumber":"173522","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Paciente do sexo feminino, de 28 anos, previamente hígida, apresenta-se com quadro\nde dor ocular de início há seis horas no\nolho direito, de caráter progressivo, com escotoma e dor à\nmovimentação lateralizada do olhar. No exame ocular, movimentos dos olhos normais, acuidade\nvisual 20/20 bilateralmente, reflexos pupilares com reação fotomotora diminuída do olho direito. RM\ndemonstrou duas lesões periventriculares na substância branca, sem realce de gadolínio. Qual é o\ndiagnóstico do sintoma visual?","options":{"A":"Toxoplasmose.","B":"Glaucoma.","C":"Neurite óptica.","D":"Síndrome ocular isquêmica."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-173524","number":"173524","sourceNumber":"173524","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Paciente do sexo feminino, de 28 anos, previamente hígida, apresenta-se com quadro\nde dor ocular de início há seis horas no\nolho direito, de caráter progressivo, com escotoma e dor à\nmovimentação lateralizada do olhar. No exame ocular, movimentos dos olhos normais, acuidade\nvisual 20/20 bilateralmente, reflexos pupilares com reação fotomotora diminuída do olho direito. RM\ndemonstrou duas lesões periventriculares na substância branca, sem realce de gadolínio.\n\nConsiderando os achados de ressonância de crânio, o diagnóstico etiológico é:","options":{"A":"síndrome clínica isolada.","B":"neuromielite óptica.","C":"esclerose múltipla.","D":"ADEM."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-186475","number":"186475","sourceNumber":"186475","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Lactente, sexo feminino, 2 anos, chega ao pronto-atendimento com história de febre há\n24 horas e movimentos tônico-clônicos\nassociados à perda de consciência que durou 5 minutos e\ncedeu há 10 minutos. Exame físico: febril, com exame neurológico normal. Antecedentes pessoais\nsem dados dignos de nota. Diante desse quadro, a conduta indicada é:","options":{"A":"Solicitar EEG e parecer do neuropediatra.","B":"Diagnosticar e tratar a etiologia infecciosa, observar a paciente e orientar a família quanto à\netiologia da crise convulsiva.","C":"Realizar punção lombar e iniciar anticonvulsivante.","D":"Realizar punção lombar e iniciar antimicrobiano."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-173558","number":"173558","sourceNumber":"173558","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"As convulsões febris são o transtorno convulsivo mais comum na infância. Este tipo de\nconvulsão:","options":{"A":"Acomete crianças de dois meses a seis anos de idade que apresentam febre alta. Pode ser\nsimples ou complexa (este tipo é mais frequente em criança que também apresenta convulsão\nafebril).","B":"Tem como principal diagnóstico diferencial as meningites: o exame do líquido cefalorraquidiano\ndeve ser considerado, caso haja lenta\nrecuperação ou alteração neurológica pós-ictal.","C":"Ocorre com maior frequência em crianças com antecedentes de infecções congênitas,\nprincipalmente toxoplasmose e rubéola; também tem sido\ndocumentada nos casos de microcefalia\ncausada por Zika.","D":"Deve ser prevenida com o uso contínuo de fenobarbital ? anticonvulsivante de primeira escolha\npara tratamento profilático das convulsões\nfebris simples. Este tratamento visa reduzir o risco de\nepilepsia futura."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-157264","number":"157264","sourceNumber":"157264","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Dentre os micro-organismos causadores de gastroenterite, quais estão associadas à\ncrise convulsiva tônico-clônica?","options":{"A":"Shigella e Salmonella.","B":"Yersinia e Campylobacter.","C":"Shigella e Yersinia.","D":"Campylobacter e E. Coli êntero-hemorrágica.","E":"E. Coli êntero-hemorrágica e Salmonella."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-150751","number":"150751","sourceNumber":"150751","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Qual é a causa mais comum de paralisia facial?","options":{"A":"Tumor de parótida.","B":"Latrogênica.","C":"Paralisia de Bell.","D":"Trauma de face."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-160469","number":"160469","sourceNumber":"160469","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Sabemos que são vários os fatores envolvidos na gênese da Síndrome do Túnel do\nCarpo, tais como: gravidez, menopausa,\nobesidade, insuficiência renal, hipotireoidismo, lúpus\neritematoso e outros. Durante o exame físico, o teste mais específico e sensível para o diagnóstico\ndessa patologia é o de","options":{"A":"Tinel.","B":"Durkan.","C":"Phalen.","D":"Phalen invertido."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-156452","number":"156452","sourceNumber":"156452","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Marque a afirmativa correta sobre CONVULSÕES","options":{"A":"São movimentos musculares coordenados e voluntários","B":"Podem ser convulsões tônicas ou clônicas","C":"O edema cerebral não é comum na eclâmpsia","D":"A causa mais comum é a hipertensão arterial","E":"O exame do líquor é dispensável"},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-150260","number":"150260","sourceNumber":"150260","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"O protocolo baseado em evidência da Sociedade Americana para Epilepsia estabelece\npara o tratamento do estado convulsivo em\nadultos e crianças vários medicamentos. Em relação a\nesse tratamento,","options":{"A":"o lorazepam endovenoso é superior ao diazepam endovenoso.","B":"o lorazepam endovenoso é inferior ao diazepam endovenoso.","C":"o lorazepam endovenoso é igual ao diazepam endovenoso.","D":"o lorazepam e o diazepam têm-se revelado ineficazes."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-150707","number":"150707","sourceNumber":"150707","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Qual é a comorbidade psiquiátrica mais comumente encontrada em pacientes com\nesclerose múltipla?","options":{"A":"Psicose.","B":"Transtorno bipolar do humor.","C":"Depressão.","D":"Transtorno obsessivo-compulsivo."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-157048","number":"157048","sourceNumber":"157048","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"O diagnóstico de convulsão febril na infância é eminentemente clínico, e, para tanto,\nalguns critérios devem ser considerados. Dos critérios a seguir, qual tem relação com convulsão\nfebril?","options":{"A":"Aparecimento de quadro febril na faixa etária dos 9 meses aos 9 anos.","B":"Presença de episódio recorrente do mesmo quadro febril.","C":"Presença de crise convulsiva generalizada.","D":"Convulsão após 24 horas de início do quadro febril."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-156481","number":"156481","sourceNumber":"156481","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Em relação as crises epiléticas na infância é correto afirmar exceto:","options":{"A":"As crises epilépticas sintomáticas agudas são definidas como as mais frequentes na infância e\nocorrem no período de limiar mais baixo do SNC, entre os três meses e os cinco anos de idade","B":"Na faixa etária de um a 6 meses a meningite bacteriana e a hemorragia intracraniana são as\netiologias predominantes das crises epilépticas sintomáticas agudas","C":"A classificação da crise febril é definida pela sua duração e recorrência","D":"No diagnóstico das crises febris simples são preconizados exames séricos, eletroencefalograma\ne de neuroimagem"},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-149200","number":"149200","sourceNumber":"149200","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Pré-escolar de 4 anos é admitido no Pronto-socorro com crises convulsivas\n\ntônico-clônicas generalizadas, sem história prévia de episódios convulsivos. Mãe relatava febre há\num dia. Foram feitas três doses de\nbenzodiazepínicos, porém criança ainda apresentava crise. Qual\ndas drogas abaixo deve ser usada na sequência, segundo o algoritmo de tratamento de crises\nconvulsivas?","options":{"A":"Fenitoína e fenobarbital.","B":"Repetiria mais três doses de benzodiazepínico.","C":"Midazolan e tiopental contínuos.","D":"Midazolan e ketamina contínuos."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-127299","number":"127299","sourceNumber":"127299","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Marcos foi visitar um amigo e, ao brincar com o animal de estimação da família, foi\nmordido na face pelo cãozinho. O dono informou que o animal está com ele há cinco anos e que\ntem sido vacinado todos os anos. Informa, ainda, que ele nunca causou problemas para as\npessoas. Com base no protocolo de profilaxia da raiva humana, com vacina de cultivo\ncelular do Ministério da Saúde, a conduta CORRETA para esse caso é de:","options":{"A":"Não fazer nada, já que o animal é sadio e domiciliado.","B":"Iniciar esquema profilático com duas doses: uma no dia 0 e outra no dia 3.","C":"Iniciar, imediatamente, o esquema profilático com cinco doses de vacina, administradas nos dias\n0, 3, 7, 14 e 28, além de observar o\nanimal por dez dias. Se a suspeita de raiva for descartada após\no 10º dia de observação, suspender a vacinação.","D":"Iniciar, imediatamente, o esquema profilático com soro e cinco doses de vacina, administradas\nnos dias 0, 3, 7, 14 e 28, além de observar o\nanimal por dez dias. Se a suspeita de raiva for\ndescartada após o 10º dia de observação, suspender a vacinação."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-138198","number":"138198","sourceNumber":"138198","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"É bem sabido que a enfermidade de Alzheimer é a causa mais comum de demência e\ntem como substrato anatômico a atrofia do hipocampo. Pode, em casos familiares, estar associada\nao cromossoma","options":{"A":"13 (Patau).","B":"18 (Edwards).","C":"21 (Down).","D":"22 (Di Georges)."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-109168","number":"109168","sourceNumber":"109168","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Criança, 6 anos de idade, chega ao pronto-socorro, com história de ter sido mordida por\num cão de propriedade dos vizinhos. Apresentava lesão profunda no pescoço. A criança nuca havia\nrecebido profilaxia anti-rábica e as informações dão conta que o cão encontra-se em boas\ncondições de saúde. Frente a esta situação, a conduta médica inicial deve ser observação do\nanimal e:","options":{"A":"3 doses de vacina antirrábica.","B":"Uma dose de soro antirrábico, mais 5 doses de vacina antirrábica.","C":"7 doses de vacina antirrábica.","D":"5 doses de vacina antirrábica."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-101189","number":"101189","sourceNumber":"101189","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Sr. Everaldo, 38 anos, dá entrada em unidade de pronto atendimento acompanhado de\nsua esposa. Ela se queixa de que, há cerca de\ndois dias, o paciente está ?estranho?, pois tem tido\npercepções que não são compartilhadas pelo restante da família, tais como ouvir vozes de pessoas\nque não estão presentes e ver bichos andando pelas paredes. Na entrevista, o paciente reclama de\nhaver um fio enrolado em suas pernas e passa o tempo todo tentando desenrolá-lo. O fio é, no\nentanto, inexistente. Diz ainda que está dentro de uma igreja e fora levado ali para se confessar. A\nesposa nega que ele tenha tido sintomas psiquiátricos previamente e nega outros problemas de\nsaúde. Nega tabagismo, fez uso esporádico de maconha na adolescência e nos últimos anos tem\nbebido cerca de um litro de bebida destilada diariamente. A acompanhante diz, entretanto, que há\ncerca de uma semana ele reduziu bastante o consumo, na tentativa de abandonar o vício. Ao\nexame, apresenta-se com mucosas normocoradas; anictérico; acianótico; desidratado +/4+;\nsudoreico; desorientado no tempo e espaço, confuso e ansioso. Pressão arterial é de 150 x 96\nmmHg; frequência cardíaca de 130 bpm e frequência respiratória de 24 irpm. Glicemia capilar\n(HGT): 71 mg/dl. A principal hipótese diagnóstica e a conduta terapêutica adequada são,\nrespectivamente:","options":{"A":"Delirium tremens. Prescrever haloperidol 5 mg por via intramuscular, soro glicosado por via\nintravenosa e encaminhar para unidade psiquiátrica para manejo adequado dos sintomas\npsicóticos.","B":"Desidratação sobreposta à esquizofrenia paranoide. Prescrever soro fisiológico por via\nintravenosa, haloperidol 5 mg, por via oral, e\nencaminhar para tratamento psiquiátrico ambulatorial\napós estabilização do quadro de desidratação.","C":"Síndrome de abstinência alcoólica. Prescrever diazepam 10 mg por via oral, a cada hora (até o\nmáximo de 60 mg por dia), soro fisiológico via intravenosa, tiamina 100 mg por via intramuscular e\nmanter o paciente em unidade clínica devido à gravidade do quadro clínico.","D":"Transtorno psicótico agudo induzido por álcool. Prescrever haloperidol 5 mg por via\nintramuscular, soro fisiológico por via intravenosa, tiamina 100 mg por via intramuscular e\n\nencaminhar para unidade psiquiátrica."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-109316","number":"109316","sourceNumber":"109316","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"No caso de mordeduras humanas e de animais, além das profilaxias vacinais\npertinentes, deve ser considerada a cobertura\nde Pasteurella multocida (Red Book, 2012). O\nantimicrobiano indicado para tal cobertura é:","options":{"A":"Cefalexina.","B":"Azitromicina.","C":"Amoxicilina-clavulanato.","D":"Ceftriaxona."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-83653","number":"83653","sourceNumber":"83653","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Configuram abuso sexual contra crianças e adolescentes, as situações em que:","options":{"A":"Fique comprovado o contato físico de natureza libidinosa entre adulto-criança/adolescente, sem\nque a criança/adolescente tenha\nconsciência da natureza do ato.","B":"Seja consumado o ato sexual com penetração por parte do adulto, com ou sem o consentimento\nda criança/adolescente.","C":"A criança/adolescente seja usada para\nestimulação sexual de alguém em estágio\npsicossexual mais avançado.","D":"Haja interação de natureza libidinosa sem consentimento por parte da criança/adolescente.","E":"Haja coerção física para submeter a criança/adolescente a situações humilhantes\ncontra a sua vontade."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-85793","number":"85793","sourceNumber":"85793","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Em relação ao trauma na infância, podemos afirmar que:","options":{"A":"É a terceira causa de óbito nas crianças de 5 a 10 anos.","B":"No traumatismo cranioencefálico moderado a escala de Glasgow está entre 7-10.","C":"As fraturas de costelas são bastante frequentes nos pré-escolares que sofrem trauma torácico.","D":"A hipotensão é um sinal precoce que podeindicar hipovolemia no politraumatizado.","E":"Hipotensão, hipotermia e bradicardia são características do trauma espinhal."},"answer":"E","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-84366","number":"84366","sourceNumber":"84366","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Que alteração geral na morfologia humana está associada ao envelhecimento? Cite o\nitem CORRETO abaixo:","options":{"A":"Aumento do peso corporal.","B":"Diminuição da água corporal.","C":"Diminuição dos níveis de insulina.","D":"Diminuição dos níveis de vasopressina.","E":"Aumento das horas de sono REM."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-85409","number":"85409","sourceNumber":"85409","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"P.S.J., sexo masculino, 40 anos, chega ao consultório com queixa de dor nos MMII e\nMMSS de início há dois anos. Apresenta\ndificuldade na dorsiflexão do pé direito (pé caído) há seis\nmeses com piora progressiva. Notou que o olho esquerdo apresenta-se mais ressecado, com\ndiminuição das lágrimas, hiperemia conjuntival e uma pequena úlcera córnea. Queixou-se de\ndiminuição da sudorese e ressecamento dos MMSS e uma discreta dificuldade de extender o 3º, 4º\ne 5º quirodáctilo D. Dor intensa à palpação do trajeto nervoso ulnar D, com espessamento\nimportante. Já procurou vários médicos e já fez uso de várias medicações para o controle da dor,\nsem sucesso. Trouxe alguns exames: hemograma: normal; glicemia de jejum: 120 mg/dl; ureia: 40\nmg/dl; creatinina: 1,0 mg/dl; eletroneuromiografia: mononeuropatia múltipla. Qual a melhor\nconduta?","options":{"A":"Controle glicêmico.","B":"Indicar fisioterapia motora com carga.","C":"Iniciar com rifampicina, dapsona, clofazimina e prednisona.","D":"Iniciar tratamento com vitamina B12 e carbamazepina."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-83887","number":"83887","sourceNumber":"83887","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"A vacinação contra febre amarela:","options":{"A":"Somente deve ser oferecida em campanhas.","B":"Deve ser oferecida nas regiões endêmicas, quando há surto da doença.","C":"Deve ser oferecida de rotina e em campanhas, em caso de surto da doença.","D":"É administrada a cada 10 anos, com a primeira dose logo após o nascer.","E":"Exige reforço, segundo o Programa Nacional de Imunização."},"answer":"E","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-83883","number":"83883","sourceNumber":"83883","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Em seguimento à erradicação da varíola, inicia-se em 1980 a 1ª CAMPANHA\nNACIONAL DE VACINAÇÃO CONTRA A POLIOMIELITE,\ncom a meta de vacinar todas as crianças\nmenores de 5 anos em um só dia. O último caso de poliomielite no Brasil ocorreu na Paraíba em\nmarço de 1989. Em setembro de 1994, o Brasil junto com os demais países da região das\nAméricas, recebeu da Comissão Internacional para a Certificação da Ausência de Circulação\nAutóctone do Poliovírus Selvagem nas Américas, o Certificado que a doença e o vírus foram\neliminados de nosso continente. Com a erradicação da poliomielite no Brasil:","options":{"A":"Não houve mais a necessidade de se oferecer a vacina Sabin nas campanhas de vacinação,\ndesde 1994.","B":"A vacina antipólio continua a ser usada na vacinação de rotina e em campanhas.","C":"Passou-se a vacinar somente em casos suspeitos, em bloqueios de foco.","D":"A vacina é administrada unicamente por via intramuscular profunda.","E":"Passou-se a usar apenas a vacina Salk."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-83884","number":"83884","sourceNumber":"83884","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Com respeito ao Calendário Nacional de Vacinação, podemos afirmar que para os\nidosos as vacinas recomendadas são:","options":{"A":"Contra febre amarela a cada 10 anos e a dupla adulto, com reforço a cada 10 anos.","B":"Contra sarampo e tétano.","C":"Contra hepatite B e difteria.","D":"Contra tétano e hepatite A.","E":"Contra gripe e meningite."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-83799","number":"83799","sourceNumber":"83799","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Entende-se por Evento Adverso Pós-Vacinação (EAPV):","options":{"A":"Um evento que tem relação apenas com respeito à composição de uma vacina.","B":"Um evento que prescinde de notificação compulsória.","C":"Um conjunto de intercorrências que são classificados em letais e não letais.","D":"Qualquer ocorrência clínica indesejável em indivíduo que tenha recebido algum imunobiológico.","E":"Somente aqueles que decorrem da administração de vacinas de vírus vivo atenuado."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-63238","number":"63238","sourceNumber":"63238","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Hanseníase é uma doença infectocontagiosa crônica endêmica no Brasil. Sobre essa\ndoença, assinale a alternativa INCORRETA.","options":{"A":"Todos os contatos intradomiciliares devem ser examinados, acompanhados e orientados, para\ninterrupção da cadeia epidemiológica.","B":"Na haseníase tuberculoide, as lesões são predominantemente placas eritematosas com\nalteração da sensibilidade térmica, dolorosa e tátil.","C":"Na hanseníase dimorfa, os bacilos iniviáveis se apresentam corados e em globais.","D":"Na hanseníase virchoviana, as lesões são disseminadas, infliltram a face, mãos e pés, a\nbaciloscopia é positiva e o teste de mitsuda é negativo.","E":"Na hanseníase indeterminada, as lesões se apresentam como manchas hipocrômicas e a\nbaciloscopia pode ser positiva ou negativa."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-49018","number":"49018","sourceNumber":"49018","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Segundo o Ministério da Saúde do Brasil (MS), a Influenza A é uma doença respiratória\naguda, causada pelo vírus pandêmico (H1N1).\nEste subtipo do vírus da influenza, do mesmo modo\nque os demais, é trasmitido de pessoa a pessoa, principalmente por meio da tosse ou espirro e do\ncontato com secreções respiratórias de pessoas infectadas. Felizmente, foi disponibilizada uma\nvacina eficaz que permitiu o seu controle com bastante segurança. Quando se trata de vacina\ncontra vírus H1N1, qual das alternativas abaixo é uma contraindicação, pelo MS?","options":{"A":"Crianças com idade inferior a 9 meses.","B":"Adultos com idade superior a 60 anos.","C":"Pacientes HIV positivos.","D":"Pacientes com alergia a ovos.","E":"Idade inferior a 1 ano."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-53540","number":"53540","sourceNumber":"53540","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Assinale a alternativa em que está listado um CRITÉRIO MAIOR para o diagnóstico de\nSíndrome de Imobilização.","options":{"A":"Múltiplas contraturas.","B":"Úlceras de decúbito.","C":"Dupla incontinência.","D":"Afasia.","E":"Amaurose."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-155294","number":"155294","sourceNumber":"155294","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Em um paciente com fraqueza muscular proximal simétrica, febre baixa recorrente,\nelevação moderada da aldolase e\neletroneuromiografia sugestiva de miopatia, é formulada a\nhipótese diagnóstica de polimiosite. Nesse contexto, a positividade do anticorpo anti-Jo-1:","options":{"A":"É necessária para confirmar o diagnóstico de polimiosite.","B":"Sugere evolução em algum momento com acometimento cutâneo (dermatopolimiosite), portanto\nindica rastreio sistêmico para neoplasia\noculta.","C":"Prediz resposta ruim à corticoterapia.","D":"Indica um paciente com maior probabilidade de acometimento pulmonar.","E":"Indica sobreposição com síndrome de Sjögren."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-155296","number":"155296","sourceNumber":"155296","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Homem, 16 anos de idade, inicia episódios de abalos musculares rápidos, semelhantes\na choques em membros superiores e membros\ninferiores, sem alteração do nível de\nconsciência.Devido a essas crises, joga objetos no chão, o que é característico de mioclonias. Em\nrelação à epilepsia mioclônica juvenil, é INCORRETO afirmar:","options":{"A":"A Carbamazepina é a medicação de escolha no tratamento.","B":"As crises podem ser desencadeadas por privação de sono, estresse, álcool, estímulo luminoso\nrepetitivo.","C":"No presente caso, a medicação de primeira linha é o ácido Valproico.","D":"O uso de levotiracetam também poderia ser indicado.","E":"O pico de início dos sintomas é na adolescência."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-105640","number":"105640","sourceNumber":"105640","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"A taxa de letalidade do tétano é maior entre:","options":{"A":"Recém-nascidos e adultos jovens.","B":"Crianças e gestantes.","C":"Crianças e adolescentes.","D":"Lactentes e idosos.","E":"Mulheres e idosos."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-105657","number":"105657","sourceNumber":"105657","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"A escala de Fagerstron, utilizada para definir o grau de dependência química do\nfumante, considera todos os itens abaixo, EXCETO.","options":{"A":"Lapso de tempo entre o despertar e o ato de fumar.","B":"Número de vezes em que o paciente já tentou parar de fumar.","C":"Dificuldade de ficar sem fumar em locais onde o fumo é proibido.","D":"Número de cigarros fumados por dia.","E":"O fato de o paciente continuar fumando mesmo acamado por doença."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-105646","number":"105646","sourceNumber":"105646","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Das vacinas abaixo, qual NÃO está indicada para imunização dos pacientes acima de\n60 anos?","options":{"A":"Febre amarela.","B":"Meningocócica tipo C.","C":"Influenza sazonal.","D":"Pneumocócica.","E":"Dupla tipo adulta."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-84935","number":"84935","sourceNumber":"84935","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Quais os fármacos a seguir podem interferir negativamente no metabolismo glicídico?","options":{"A":"Colesevelam e Pravastatina.","B":"Fenofibrato e Orlistate.","C":"Atenolol eNiacina.","D":"Nebivolol e Anlodipina.","E":"Carvedilol e Ramipril."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-80989","number":"80989","sourceNumber":"80989","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Dentre os possíveis efeitos colaterais dos diuréticos destacam-se as seguintes\nafirmações, EXCETO:","options":{"A":"Alcalose Metabólica, hiperglicemia e contração do volume extracelular.","B":"Hiperuricemia, hipocolesterolemia e hipocalemia.","C":"Hiperglicemia, hipocalemia e nefrite intersticial aguda.","D":"Ginecomastia, hiperglicemia e hiperuricemia.","E":"Hiponatremia, hipocalemia e hipercalcemia."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-80845","number":"80845","sourceNumber":"80845","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Assinale a alternativa CORRETA quanto ao transporte de um lactente até um ano de\nidade completo e até alcançar o peso de 10 kg.","options":{"A":"O assento deve estar no banco traseiro do veículo, voltado para frente (a favor do fluxo do\ncarro).","B":"O assento do lactente deve, obrigatoriamente, estar no banco traseiro do veículo, voltado para\ntrás (contra o fluxo do carro).","C":"Não há orientação específica para essa faixa etária.","D":"Ao atingir o peso de 10 kg, a criança já pode ser transportada no banco dianteiro, no colo da\nmãe.","E":"Nenhuma das respostas."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-62635","number":"62635","sourceNumber":"62635","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Assinale a alternativa incorreta em relação ao tabagismo e dos resultados\nperioperatórios.","options":{"A":"Em pacientes cirúrgicos não cardíacos, o tabagismo está associado a um acréscimo de\naproximadamente 40% no risco de mortalidade em 30 dias e um risco de 30 - 100% de maior\nmorbidade, incluindo infecção do sítio cirúrgico, pneumonia, intubação não planejada, parada\ncardíaca, infarto do miocárdio e choque séptico;","B":"O tabagismo determina piora na atividade fagocítica e bactericida dos neutrófilos e macrófagos,\nresultando numa reduzida capacidade de\ncontrole da contaminação bacteriana da ferida operatória,\ndeterminando maior predisposição à infecção de sítio cirúrgico;","C":"O tabagismo altera a função das células inflamatórias, determinando uma degradação do tecido\nconectivo devido a uma excessiva liberação de proteases, associada a uma redução na liberação\nde fatores inibidores de proteases;","D":"O tabagismo determina um efeito vasoconstrictor deletério permanente e não reversível, após\nsua interrupção (cessar de fumar) no fluxo\nsanguíneo periférico, oxigenação e metabolismo\nanaeróbio; favorecendo o surgimento de hipóxia, necrose e infecção de sítio cirúrgico.","E":"A resposta inflamatória é reversível dentro de 3 e 4 semanas após a interrupção do tabagismo,\ncom o retorno à normalidade da função das\ncélulas inflamatórias, liberação de enzinas proteolíticas\ne mecanismos oxidativos, porém a resposta proliferativa parece não ser reversível (função do\nfibroblasto, regeneração epidérmica, síntese e degradação do colágeno)."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-342384","number":"342384","sourceNumber":"342384","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"A patologia mais frequentemente associada ao timoma é:","options":{"A":"linfoma","B":"miastenia gravis","C":"câncer de pulmão","D":"síndrome de Tourette","E":"artrite reumatóide"},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-308660","number":"308660","sourceNumber":"308660","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"A síndrome do desfiladeiro torácico refere-se à compressão dos vasos subclávios e dos\nnervos do plexo braquial na região do desfiladeiro torácico. São úteis na investigação diagnóstica,\nEXCETO:","options":{"A":"cintilografia.","B":"ultrassom doppler arterial de membro superior.","C":"radiografia de tórax.","D":"tomografia computadorizada de tórax.","E":"eletroneuromiografia."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-302080","number":"302080","sourceNumber":"302080","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Paciente 33 anos comparece ao ambulatório relatando perda do movimento de\ndorsiflexão do pé direito há 30 dias. Nega\ntraumas. Nos antecedentes: Nega uso de medicamentos\ne quadros infecciosos nos últimos 90 dias. Refere casos de hanseníase na família. Fez primeira\ndose de vacina AstraZeneca há 60 dias. Ao exame: Força Zero para dorsiflexão do pé direito e\nausência de lesões dermatológicas. Nesse caso:","options":{"A":"A principal hipótese nesse caso é neuropatia periférica reacional pelo uso da vacina\nindependente do teste de sensibilidade\ncutânea, dispensando-se inclusive a propedêutica armada.","B":"Deve-se proceder com avaliação dermatoneurológica minunciosa e se teste de sensibilidade\ncutânea ao longo nervo fibular direito for\nnormal, deve-se solicitar eletroneuromiografia para\ninvestigar padrão e possível etiologia da neuropatia.","C":"Deve-se solicitar baciloscopia do esfregaço intradérmico para descartar o diagnóstico de\nhanseníase.","D":"Encaminhar de imediato para o neurologista seria a conduta mais acertada do médico da família\npor se tratar de um quadro compatível com\nneuropatia periférica sem lesões dermatológicas.","E":"Ainda que o teste de sensibilidade cutâneo esteja normal ao longo do tegumento, o diagnóstico\nde hanseníase neural é o mais provável."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-302082","number":"302082","sourceNumber":"302082","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Paciente masculino, em tratamento oncológico sistêmico, adentra ao serviço de pronto\natendimento referindo neuropatia periférica, resultando em ataxia sensorial e dor, sem fraqueza.\n\nQual o medicamento quimioterápico, dos listados abaixo, está comumente associado as queixas do\npaciente acima referido?","options":{"A":"metotrexato","B":"alcaloides da vinca","C":"taxanos","D":"análogos da platina","E":"modulador seletivo do receptor de estrogênio"},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-302126","number":"302126","sourceNumber":"302126","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Lactente, oito meses, previamente hígido, é levado à emergência com história de febre\nhá 36 horas e episódio de crise convulsiva\ntônico-clônica com duração de cinco minutos.\n\nResponsável nega episódios anteriores. Exame físico: febril e sonolento, porém facilmente\ndespertável, sem sinais de irritação meníngea.\nHiperemia de orofaringe. Restante do exame sem\nalterações. A abordagem imediata é realizar:","options":{"A":"dosagem de eletrólitos","B":"punção lombar","C":"hemograma e PCR","D":"tomografia computadorizada de crânio","E":"ressonância nuclear magnética de encéfalo"},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-281477","number":"281477","sourceNumber":"281477","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Criança de 10 anos, epiléptica, com história de vômitos incoercíveis, deu entrada no\npronto socorro infantil com convulsão. Não houve sucesso na tentativa de acessos venoso e\nintraósseo. Qual medicamento de 1º escolha e a via de aplicação para este quadro convulsivo?","options":{"A":"Diazepam intramuscular.","B":"Fenobarbital oral.","C":"Midazolam intramuscular.","D":"Ácido valpróico oral.","E":"Penicilina Benzatina oral."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-244656","number":"244656","sourceNumber":"244656","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Mulher de 55 anos, hipertensa, diabética e renal crônica não dialítica, chegou a\nemergência do hospital trazida por\nfamiliares 30 minutos após breve perda de consciência (+/- 3\nmin). Acompanhante relata que a paciente estava apresentando abalos de braços e pernas e ficou\ncom os olhos abertos. Paciente não apresenta sinais neurológicos focais. Ao exame apresenta\nabertura ocular, obedece a comandos e segue desorientado em tempo e espaço. SSVV: PA = 140\nx 80 FC = 80 bpm FR = 15. Sem alterações ao exame físico. Deve fazer parte da investigação\ninicial desta paciente, EXCETO:","options":{"A":"Eletrocardiograma","B":"Sódio","C":"Glicemia","D":"Eletroencefalograma","E":"Ureia"},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-252416","number":"252416","sourceNumber":"252416","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Sensação de formigamento, dormência, hipoestesia ou hiperestesia em território de um\nou mais nervos caracterizam as parestesias\nsubagudas e crônicas dos membros superiores.\n\nAssinale a alternativa na qual o sinal de Tinel, teste de phalen e Durkan em geral estão positivos.","options":{"A":"Síndrome do canal de Guyon","B":"Síndrome do pronador redondo","C":"Síndrome do canal cubital","D":"Síndrome do túnel do carpo","E":"Síndrome do túnel radial"},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-252451","number":"252451","sourceNumber":"252451","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Recém-nascido, de 40 semanas de gestação, pesando 4020 gramas, apresentou\nescore de Apgar 2/ 3/ 4 respectivamente. Com\nduas horas de vida, iniciou quadro de crises\nconvulsivas, sendo feito fenobarbital endovenoso na dose de 20mg/kg, havendo manutenção do\nquadro de crise convulsiva. Selecione a conduta adequada imediata para controle das crises\nconvulsivas nesse caso:","options":{"A":"Solicitar parecer especializado para neuropediatria e aguardar conduta.","B":"Fazer flush de glicose.","C":"Fazer diazepam endovenoso.","D":"Fazer midazolam endovenoso ou intranasal.","E":"Repetir outra dose de 20mg/kg de fenobarbital endovenoso."},"answer":"E","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-252457","number":"252457","sourceNumber":"252457","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"A Distrofia Muscular de Duchenne é a doença degenerativa neuromuscular hereditária\nmais grave da infância. Qual das opções a seguir\né o melhor exame de rastreamento para criança\ncom Distrofia Muscular de Duchenne?","options":{"A":"Avaliação dos níveis séricos da creatina quinase","B":"Biópsia muscular","C":"Eletromiografia","D":"Avaliação dos níveis séricos da TGO","E":"Análise sanguínea para fatores antinucleares"},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-203605","number":"203605","sourceNumber":"203605","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Sobre o câncer de pulmão e as síndromes paraneoplásicas, a histologia mais\nrelacionada à síndrome miastênica de Eaton-Lambert é o:","options":{"A":"Carcinoma broncogênico.","B":"Carcinoma espinocelular.","C":"Adenocarcinoma.","D":"Linfoma pulmonar.","E":"Carcinoma de pequenas células."},"answer":"E","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-203631","number":"203631","sourceNumber":"203631","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Sobre o padrão clínico das PFA (paralisias flácidas agudas), a apresentação:\ndescendente, bilateral e simétrica é típica de","options":{"A":"Poliomielite.","B":"Síndrome de Guillain-Barré.","C":"Miastenia gravis.","D":"Botulismo.","E":"Mielite transversa."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-218049","number":"218049","sourceNumber":"218049","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Lactente, oito meses, previamente hígido, é levado à emergência com história de febre\nhá 36 horas e episódio de crise convulsiva\ntônico-clônica com duração de cinco minutos.\n\nResponsável nega episódios anteriores. Exame físico: febril e sonolento, porém facilmente\ndespertável, sem sinais de irritação meníngea.\nHiperemia de orofaringe. Restante do exame sem\nalterações. A abordagem imediata é realizar:","options":{"A":"Tomografia computadorizada.","B":"Punção lombar.","C":"Dosagem de eletrólitos.","D":"Hemograma e PCR.","E":"Intubação orotraqueal."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-203210","number":"203210","sourceNumber":"203210","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Paciente oncológica, evolui com dor em mãos, associada à dormência e a\nformigamento. Recebe o diagnóstico de dor\nneuropática grau 2. O tratamento inicial de escolha\npara o quadro exposto é:","options":{"A":"Gabapentina 900 mg/dia.","B":"Oxicodona 20 mg/dia.","C":"Dexametasona 8 mg/dia.","D":"Morfina 60 mg/dia.","E":"Dipirona 4 g/dia."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-203269","number":"203269","sourceNumber":"203269","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Recém-nascido, de 39 semanas de gestação, pesando 3.350 gramas, apresentou\nescore de Apgar 2/ 3/ 4/ respectivamente. Com\ntrês horas de vida, iniciou quadro de crises\nconvulsivas. A conduta adequada imediata, para controle das crises convulsivas, é indicar:","options":{"A":"Sulfato de magnésio endovenoso","B":"Fenitoína intramuscular.","C":"Fenobarbital endovenoso.","D":"Diazepam endovenoso.","E":"Solicitar parecer especializado para neuropediatria e aguardar conduta."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-203276","number":"203276","sourceNumber":"203276","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Sobre síndromes epileptiformes, selecione a opção CORRETA para o padrão\neletroencefalográfico característico da síndrome de West:","options":{"A":"Hipsarritmia.","B":"Desorganização.","C":"Atividade surto-supressão.","D":"IRDA (atividade rítmica delta intermitente).","E":"Delta contínuo de alta voltagem."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-177522","number":"177522","sourceNumber":"177522","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Recém-nascido deu entrada no pronto socorro com quadro de crise convulsiva. Qual é\no anticonvulsivante de primeira escolha no período\nneonatal?","options":{"A":"Midazolam","B":"Fenitoína","C":"Fenobarbital","D":"Diazepam","E":"Tiopental"},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-160445","number":"160445","sourceNumber":"160445","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Um homem de 30 anos apresenta há 24h plegia ascendente em membros inferiores,\ncom discreta parestesia, sem acometimento\nesfincteriano. Há cerca de 3 semanas, apresentou\nquadro febril com rash cutâneo, autolimitado, mas não apresenta outras comorbidades.\n\nHemograma, bioquímica e eletrólitos estão normais e o líquor apresenta 5 cel/mm3 (80%\nmononucleares) e proteína total 40 mg/dl.\nSobre este cenário clínico, assinale a afirmativa correta.","options":{"A":"A imunoglobulina venosa de ser instituída imediatamente.","B":"A punção liquórica deve ser repetida em 48h.","C":"Há indicação para pulsoterapia com prednisona e ciclofosfamida.","D":"Deve ser solicitada eletroneuromiografia de membros inferiores.","E":"Deve ser solicitada ressonância magnética crânio e coluna."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-154369","number":"154369","sourceNumber":"154369","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Em massa no mediastino posterior de uma criança, os diagnósticos mais prováveis são:","options":{"A":"Anomalia dos grandes vasos, cisto broncogênico.","B":"Linfoma, tumor tímico.","C":"Cisto esofágico, tumor neurogênico.","D":"Tumor neurogênico, higroma cístico.","E":"Cisto broncogênico, teratoma."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-160450","number":"160450","sourceNumber":"160450","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"A epilepsia é um distúrbio com alta prevalência em todo o mundo, especialmente em\npaíses em desenvolvimento, onde o sistema\nde saúde ainda falha na sua prevenção. Sobre o tema,\nidentifique a afirmativa VERDADEIRA:","options":{"A":"O estado de mal epilético é caracterizado pela presença de crises com mais de 30 minutos de\nduração ou crises epiléticas repetidas com recuperação da consciência entre elas.","B":"A mortalidade entre os epiléticos é cerca de 2 (duas) vezes maior do que a da população geral e\ncostuma estar relacionada à etiologia das crises e à falta de controle terapêutico.","C":"Drogas anestésicas são desnecessárias e contraindicadas no estado de mal epilético refratário\n(EMER).","D":"Na fase precoce da infância, a epilepsia costuma ser assintomática, secundária a encefalopatia\nhipóxico-isquêmica perinatal, infecções do sistema nervoso central (SNC) e traumatismos\ncranioencefálicos (TCE).","E":"O estado de mal epilético costuma se manifestar por diferentes tipos de crises, sendo as não\nconvulsivas as mais observadas na infância."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-154392","number":"154392","sourceNumber":"154392","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Adolescente de 12 anos, sexo masculino, apresenta episódios de contrações rítmicas e\ndormência de uma hemiface, ruídos guturais, salivação excessiva e movimentos clônicos dos\nmembros ipsilaterais. Os episódios ocorrem apenas durante o sono. Exame físico: normal. O\ndiagnóstico mais provável é:","options":{"A":"Mioclonias benignas do sono.","B":"Epilepsia de ausência típica.","C":"Epilepsia mioclônica juvenil.","D":"Epilepsia rolândica benigna.","E":"Terror noturno."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-132784","number":"132784","sourceNumber":"132784","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Jovem de 16 anos de idade deu entrada no pronto socorro trazido pelo SAMU com\nferimento laceroperfurante em coxa esquerda. Segundo o APH, a lesão foi determinada por arame\nfarpado durante tentativa de fuga da polícia. Das três doses da vacina antitetânica, a última foi\nrealizada há mais de 6 anos, segundo informação fornecida pela mãe. Assinale a alternativa\nCORRETA em relação à profilaxia antitetânica adequada nesse caso.","options":{"A":"Não realizar o reforço da vacina antitetânica, pois a antibioticoterapia sistêmica será iniciada\nnesse tipo de ferimento.","B":"Não realizar o reforço da vacina antitetânica, pois o paciente já havia completado as três doses\nobrigatórias do esquema básico de vacinação.","C":"Realizar o reforço da vacina antitetânica, pois o paciente é jovem.","D":"Não realizar o reforço da vacina antitetânica, pois esse tipo de ferida é considerada limpa.","E":"Realizar o reforço da vacina antitetânica, pois a última dose foi administrada há mais de 6\nanos."},"answer":"E","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-103945","number":"103945","sourceNumber":"103945","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Analise as seguintes afirmativas sobre maus-tratos na infância e, em seguida, escolha a\nopção correta. I. Pessoas vítimas de\nviolência na infância podem repeti-la quando se tornam\nadultas, especialmente com seus próprios filhos ou com outras crianças e adolescentes com as\nquais se relacionam socialmente. II. São formas de maus-tratos na infância: negligência, abusos\nfísicos, abuso sexual, abuso psicológico e síndrome de Munchausen por procuração. III. Todos os\ncasos suspeitos de maus-tratos devem ser obrigatoriamente comunicados ao conselho tutelar da\nrespectiva localidade de moradia da vitima. IV. Toda denúncia ao conselho tutelar deve ser\ncomunicada também à policia, para que sejam tomadas as medidas cabíveis contra o agressor.","options":{"A":"apenas I, II e III estão corretas.","B":"apenas II e IV estão corretas.","C":"apenas I e II estão corretas.","D":"apenas II e III estão corretas.","E":"I, II, III e IV estão corretas."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-103959","number":"103959","sourceNumber":"103959","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Escolha a opção correta em relação à prevenção secundária do câncer de cólon e reto.","options":{"A":"Mesmo pessoas com alto risco ou com história familiar para este câncer devem realizar exames\nde triagem apenas a partir dos 50 anos.","B":"A triagem para este câncer deve começar aos 50 anos.","C":"A realização da colonoscopia deve começar mais cedo nas mulheres, pois estas apresentam\nmaior risco de desenvolver este tipo de câncer\ndo que os homens.","D":"Teste de alta sensibilidade para identificação de sangue oculto nas fezes deve ser feito a cada\ncinco anos, dos 50 aos 75 anos.","E":"Sigmoidoscopia flexível deve ser realizada de 10 em 10 anos, a partir dos 40 anos."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-103982","number":"103982","sourceNumber":"103982","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Uma menina com 8 anos de idade acidentou-se com metal enferrujado, ferindo-se\ngravemente em membro inferior. É levada ao\nhospital onde é realizada a sutura. Seu esquema\nvacinal estava completo (3 ou mais doses, sendo a última dose há menos de 5 anos). Em relação à\nprevenção do tétano, neste caso:","options":{"A":"deve-se dar reforço da vacina (tríplice acelular), sem imunização passiva.","B":"deve-se dar reforço da vacina (dupla adulto) e imunização passiva.","C":"deve-se dar reforço da vacina (dupla adulto), sem imunização passiva.","D":"não é necessário vacinação de reforço nem imunização passiva.","E":"deve-se fazer apenas a imunização passiva."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-346616","number":"346616","sourceNumber":"346616","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Em uma jovem com hipertrofia gengival, qual das seguintes condições é a causa MAIS\nPROVÁVEL desse achado?","options":{"A":"Bulimia","B":"Uso de difenilhidantoína","C":"Uso de tetraciclina","D":"Uso excessivo de flúor"},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-327339","number":"327339","sourceNumber":"327339","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Feminino, 30 anos, vem ao ambulatório com queixa de fraqueza inicialmente em\nmembros inferiores há 3 dias, evoluindo com\npiora da força muscular em membros superiores há 2\ndias. Refere um quadro diarreico há 2 semanas antes do início dos sintomas atuais. Nega disfagia,\ndiplopia, perda de controle esfincteriano, sem nível sensitivo. Nega comorbidades ou história\nfamiliar de doença neurológica. Qual o manejo correto desta paciente?","options":{"A":"Acompanhamento ambulatorial, pois se trata de miastenia gravis, devendo ser realizada coleta\nde líquor e prescrita prednisona.","B":"Internação hospitalar, pois se trata de uma crise miastênica, devendo ser realizada\neletroneuromiografia e prescrita imunoglobulina humana.","C":"Internação hospitalar, pois se trata de uma síndrome de Guillain Barré, devendo ser realizada\ncoleta de líquor e prescrita imunoglobulina\nhumana.","D":"Acompanhamento ambulatorial, pois se trata de uma síndrome de Guillain Barré, devendo ser\nrealizada coleta de líquor e prescrita prednisona."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-346648","number":"346648","sourceNumber":"346648","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Qual das características abaixo sugere que uma convulsão na vigência de febre NÃO é\nBENIGNA?","options":{"A":"Ocorrência de convulsão tônico-clônica generalizada","B":"Convulsão que se repete no mesmo episódio febril","C":"Ocorrência nas primeiras 24 horas de febre","D":"Criança com idade entre seis meses e seis anos"},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-327360","number":"327360","sourceNumber":"327360","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Pré-escolar, feminina, 5 anos de idade, veio encaminhada para o Ambulatório de\nPediatria do Hospital Universitário com\nhistória de quadro de crises epilépticas caracterizadas por\nperda súbita do tônus postural, extensão do membro superior direito, postura em opistótono e\ndesvio óculo-cefálico para a esquerda, com duração de aproximadamente 30 segundos, iniciadas\nhá 6 meses. Evolui na fase pós-ictal com letargia e confusão prolongada. As crises foram ficando\ncada vez mais frequentes, quase toda semana e não estavam relacionadas com atividade física ou\npresença de febre. A paciente é filha de pais não consanguíneos, sem história de intercorrências\ngestacionais ou de parto e com desenvolvimento neurológico normal. Sem história familiar de\ndoença neurológica. Os exames de hemograma, testes bioquímicos e triagem para erros inatos do\nmetabolismo foram normais. O eletroencefalograma evidenciou atividade epileptiforme focal na\nregião occipital do hemisfério cerebral direito, durante o sono. A RM de crânio com resultado\nnormal. PET- scan marcado com F-2-Deoxyglicose (FDG) demonstrou hipometabolismo glicolítico\nnas regiões têmporo-occipital direita e parietal alta posterior direita. Essas crises epilépticas\nque a\npaciente apresentou, segundo a Liga Internacional Contra a Epilepsia (ILAE - 2017), são\nclassificadas de início","options":{"A":"generalizado, tonicoclônicas.","B":"generalizado, motor tônico.","C":"focal, tonicoclônicas.","D":"focal, motor tônico."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-308372","number":"308372","sourceNumber":"308372","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Lactente de 1 ano e 6 meses iniciou há, aproximadamente, 18 horas quadro febril\n(38,5ºC) e sinais clínicos de infecção de\nvias aéreas superiores. Não está fazendo uso de\nantibióticos. Há cerca de 30 minutos, apresentou crise epiléptica caracterizada por movimentos\ntônico-clônicos generalizados de duração aproximada de 5 minutos, sendo então trazido ao pronto\natendimento. Pais referem ser o primeiro episódio na vida da criança. No momento do atendimento,\na criança encontra-se com temperatura de 37,9ºC (feito dipirona em casa após a crise), ativa,\nreativa, sem sinais de irritação meníngea e restante do exame clínico e neurológico normal.\n\nConstatada apenas hiperemia de orofaringe e membrana timpânica associada à coriza hialina.\nConsiderando que se trata de crise febril simples, deve-se:","options":{"A":"Fazer diazepam endovenoso, no pronto atendimento, e prescrever anticonvulsivante e\nantitérmicos até consulta com especialista.","B":"Prescrever anticonvulsivante e antitérmicos até consulta com especialista.","C":"Fazer diazepam endovenoso, no pronto atendimento, e prescrever apenas antitérmicos.","D":"Prescrever apenas antitérmicos."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-313393","number":"313393","sourceNumber":"313393","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Escolar, 6 anos, sexo masculino, semcomorbidades prévias, trazido pela mãe ao\nneuropediatra com relato de perdas abruptas deconsciência, na qual a criança fica parada,\ncomdesvio do olhar por um breve momento e melhora na sequência, sem período pós-ictal,\nretomando suas atividades. Foi realizado eletroencefalograma que revelou complexos ponta-onda\nlentas de 3 ciclos/segundo. Confirmado o diagnóstico de epilepsia, qual a melhor alternativa\nterapêutica para esse tipo de crise?","options":{"A":"Fenitoína;","B":"Fenobarbital;","C":"Etossuximida;","D":"Oxcarbazepina."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-313410","number":"313410","sourceNumber":"313410","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Mulher, 28 anos, com quadro de visão dupla recorrente, apresentando no momento\nalém da diplopia, cansaço e dificuldade de deambulação. Ao exame apresenta-se com fala\nempastada, semiptose palpebral esquerda e paraparesia crural de predomínio proximal. O\nneurotransmissor envolvido na fisiopatologia da principal hipótese diagnóstica é:","options":{"A":"Dopamina;","B":"Serotonina;","C":"Acetilcolina;","D":"Noradrenalina."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-267281","number":"267281","sourceNumber":"267281","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Uma mulher de 42 anos, dona de casa, recorre ao serviço de urgência devido à história\nde dois dias de dificuldade de caminhar por\nfraqueza nas pernas, principalmente na perna\nesquerda. Ela diz: \"Eu me sinto como se as minhas pernas ficassem moles\". Apresentou\nincontinência urinária progressiva durante esse período e tem urinado na cama à noite. Há três\nanos, foi submetida à quadrantectomia seguida de quimioterapia e radioterapia devido a um\ncarcinoma ductal infiltrativo da mama. Os sinais vitais são temperatura 37,1°C, frequência cardíaca\n88/min, frequência respiratória 16/min e pressão arterial 102/66 mmHg. Força muscular das\nextremidades é de 4/5 no MID e 3/5 no MIE. Os reflexos tendinosos profundos estão exacerbados\nnos joelhos e tornozelos bilateralmente. A sensibilidade ao estímulo doloroso está reduzida nas\nextremidades inferiores. Qual é o estudo inicial apropriado para essa doente?","options":{"A":"Eletroneuromiografia dos MMII","B":"Ressonância Nuclear Magnética da coluna","C":"Tomografia Computadorizada de crânio","D":"PET scan"},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-258913","number":"258913","sourceNumber":"258913","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Homem, 31 anos, vem ao ambulatório do PSF trazido pela esposa, com história de ter\napresentado há 10 dias, durante o sono da noite, um episódio de abalos dos quatro membros,\nperda de controle esfincteriano, duração de 5 minutos, seguido de período de 2 horas de confusão\ne desconhecimento. Nega familiares com algum problema de saúde, antecedentes pessoais nada\ndignos de nota. Diante desse caso, qual a propedêutica e o tratamento a ser instituído?","options":{"A":"Solicitar exame de TC Crânio, iniciar fenobarbital 100 mg venoso de 12/12 h e encaminhar para\nacompanhamento com neurologista.","B":"Solicitar exame de EEG, encaminhar para acompanhamento neurológico e orientações em\nrelação à conduta frente a uma nova crise convulsiva, caso ocorra.","C":"Solicitar exame de RNM Encéfalo, iniciar carbamazepina 200 mg oral de 8/8 h e encaminhar\npara acompanhamento com neurocirurgião.","D":"Internar o paciente em hospital de referência, solicitar punção lombar, exames de sangue, TC\nCrânio e avaliação da infectologia."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-283969","number":"283969","sourceNumber":"283969","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Escolar, 6 anos, sexo masculino, sem comorbidades prévias, trazido pela mãe ao\nneuropediatra com relato de perdas abruptas de consciência, na qual a criança fica parada, com\ndesvio do olhar por um breve momento e melhora na sequência, sem período pós-ictal, retomando\nsuas atividades. Foi realizado eletroencefalograma que revelou complexos ponta-onda lentas de 3\nciclos/segundo. Confirmado o diagnóstico de epilepsia, qual a melhor alternativa terapêutica para\nesse tipo de crise?","options":{"A":"Fenitoína","B":"Fenobarbital","C":"Etossuximida","D":"Oxcarbazepina"},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-283987","number":"283987","sourceNumber":"283987","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Mulher, 28 anos, com quadro de visão dupla recorrente, apresentando no momento\nalém da diplopia, cansaço e dificuldade de deambulação. Ao exame apresenta-se com fala\nempastada, semiptose palpebral esquerda e paraparesia crural de predomínio proximal. O\nneurotransmissor envolvido na fisiopatologia da principal hipótese diagnóstica é:","options":{"A":"dopamina","B":"serotonina","C":"acetilcolina","D":"noradrenalina"},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-247698","number":"247698","sourceNumber":"247698","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Recém-nascida de termo, 15 dias, apresentando hipotonia. Há o relato de pouca\nmovimentação durante a gestação. Os pais são consanguíneos. Ao exame, observa-se hipotonia\ngeneralizada (posição de rã), face expressiva, sucção débil, fasciculação de língua e reflexos\ntendinosos profundos abolidos. O diagnóstico que descreve a situação é:","options":{"A":"Distrofia Muscular Congênita.","B":"Atrofia muscular espinhal.","C":"Distrofia Miotônica.","D":"Glicogenose Tipo II (Doença de Pompe)."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-254203","number":"254203","sourceNumber":"254203","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Sobre convulsões febris na infância, assinale a alternativa CORRETA.","options":{"A":"O uso de antitérmico é efetivo para prevenção de crises","B":"É recomendado tratamento contínuo com anticonvulsivantes após a primeira crise","C":"Existe aumento do risco de desenvolver epilepsia no futuro","D":"Febre mais elevada é sinal de que a doença é mais grave e que há maior risco de convulsões"},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-247713","number":"247713","sourceNumber":"247713","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Carlos Gregório, 3 anos e 6 meses, é uma criança saudável. Seu crescimento e\ndesenvolvimento neuropsicomotor são adequados para a idade. Há duas semanas, começou a\nfrequentar a creche do bairro e com este contato intenso com várias crianças, vem apresentando\nquadros sugestivos de viroses de vias aéreas superiores. Há 2 dias em vigência de febre (38,9°C),\napresentou movimentos tônico-clônicos generalizados com duração de aproximadamente cinco\nminutos. Após a crise, foi levado a uma Policlínica e avaliado detalhadamente pelo pediatra. O\nmédico não constatou alterações no exame físico (nem mesmo sinais de irritação meníngea). A\ncriança recuperou-se espontaneamente sem necessidade de medicação. O episódio foi classificado\ncomo crise febril simples. Qual a conduta adequada para essa situação?","options":{"A":"Aplicar diazepam na dose de 0,2 a 0,4 mg/kg, realizar tomografia de crânio na urgência e\nprescrever fenobarbital para casa na dose de 4 mg/kg/dia.","B":"Realizar punção lombar para coleta de liquor, prescrever fenobarbital para casa na dose de 4\nmg/kg/dia.","C":"Aplicar diazepam na dose de 0,2 a 0,4 mg/kg, prescrever fenobarbital para casa na dose de 4\nmg/kg/dia.","D":"Avaliar o paciente detalhadamente. Se não apresentar alterações neurológicas, liberar para casa\napenas com antitérmicos orais."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-221373","number":"221373","sourceNumber":"221373","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Assinale a alternativa INCORRETA com relação aos seminomas mediastinais:","options":{"A":"Constituem 50% dos tumores malignos de células germinativas.","B":"Os sintomas estão relacionados com os efeitos mecânicos do tumor sobre as estruturas\nmediastinais e pulmonares adjacentes.","C":"A síndrome da veia cava superior ocorre em 10% a 20% dos pacientes.","D":"Estes tumores não são sensíveis à radioterapia ou a quimioterapia. O tratamento de escolha\nconsiste na ressecção cirúrgica."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-208595","number":"208595","sourceNumber":"208595","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Um menino de 2 anos e 6 meses é trazido ao pronto-socorro por ter apresentado, em\ncasa, quadro de convulsão tônico-clônica\ngeneralizada, com duração de 5 minutos e recuperação\nespontânea da consciência. A mãe relata coriza e tosse há 2 dias e febre algumas horas antes do\nepisódio. Ao exame físico, a criança estava orientada, ativa, reativa, sem sinais neurológicos\nfocais,\nsem sinais meníngeos, com hiperemia de orofaringe, além de membrana timpânica direita\nhiperemiada e abaulada. Qual é a conduta inicial indicada para o caso?","options":{"A":"tratar a otite e explicar aos pais a benignidade do quadro","B":"coletar glicemia e eletrólitos e internar a criança","C":"solicitar tomografia de crânio","D":"coletar liquor e iniciar ceftriaxona parenteral","E":"tratar a otite e iniciar fenobarbital"},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-159386","number":"159386","sourceNumber":"159386","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Criança de 9 anos é trazida na UBS com ferimento superficial ao tornozelo por\nmordedura de cão de rua. O cão fugiu e está\ndesaparecido. Quanto a prevenção da raiva humana,\nconforme o Ministério da Saúde, assinale a alternativa CORRETA:","options":{"A":"Administrar somente 5 doses de vacina (0, 3, 7, 14, 28).","B":"Administrar 5 doses de vacina (0, 3, 7, 14, 28) e iniciar tratamento com soro perifocal na porta\nde\nentrada.","C":"Administrar 5 doses de vacina (0, 3, 7, 14, 28) e iniciar tratamento com soro intramuscular.","D":"Administrar somente soro perifocal na porta de entrada."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-158075","number":"158075","sourceNumber":"158075","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Em relação às crises convulsivas da infância, assinale a afirmativa correta.","options":{"A":"A crise febril é sempre benigna e não deve ser tratada com medicamentos.","B":"O objetivo de tratamento das crises convulsivas é prevenir e tratar complicações sistêmicas.","C":"A punção lombar sempre deve ser realizada.","D":"Eletroencefalograma e ressonância magnética de crânio são indicadas em todos os casos de\ncrises convulsivas febris acima de dois anos."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-109274","number":"109274","sourceNumber":"109274","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Paciente com hanseníase multibacilar descobre estar grávida durante a sexta cartela\nde Poliquimioterapia Multibacilar (PQTMB). Qual é a\nconduta recomendada?","options":{"A":"Manter a PQTMB.","B":"Suspender o tratamento até o término da gestação.","C":"Suspender apenas a dapsona, mantendo a clofazimina e a dose mensal supervisionada.","D":"Substituir a dapsona por droga alternativa (ofloxacina ou minociclina)."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-85012","number":"85012","sourceNumber":"85012","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"<p>Em relação ao envelhecimento e saúde da pessoa idosa, marque a afirmativa\nCORRETA:</p>","options":{"A":"O Ministério da Saúde preconiza que qualquer prática corporal/atividade física pelo idoso só\npode ser iniciada após realização da avaliação\nde saúde.","B":"No Brasil, a prevalência de depressão é maior nos homens do que nas mulheres.","C":"A inatividade física é um dos fatores de risco mais importantes para as doenças crônicas,\nassociada à dieta inadequada e uso do fumo.","D":"Recomenda-se para os idosos acima de 60 anos as vacinas: dupla adulto (Dt ? contra difteria e\ntétano) e uma dose anual da vacina contra influenza no inverno."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-360563","number":"360563","sourceNumber":"360563","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"A síndrome clínica isolada de alto risco de conversão para Esclerose Múltipla:","options":{"A":"Caracteriza-se pela terceira manifestação clínica não sugestiva de desmielinização inflamatória\nno SNC, na qual o paciente apresente uma ou\nmais lesões típicas em T2 comprovadas por exame\nde ressonância magnética e inatribuível a outras doenças.","B":"Caracteriza-se pela primeira manifestação clínica sugestiva de desmielinização inflamatória no\nSNC, na qual o paciente apresente uma ou mais lesões típicas em T2 comprovadas por exame de\nressonância magnética e inatribuível a outras doenças.","C":"Caracteriza-se pela primeira manifestação clínica não sugestiva de desmielinização inflamatória\nno SNC, na qual o paciente apresente uma ou\nmais lesões típicas em T7 comprovadas por exame\nde ressonância magnética e inatribuível a outras doenças.","D":"Caracteriza-se pela primeira manifestação clínica sugestiva de desmielinização inflamatória no\nSNC, na qual o paciente apresente uma ou mais lesões atípicas em T2 comprovadas por exame de\nressonância magnética e atribuível a outras doenças."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-330625","number":"330625","sourceNumber":"330625","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Síndrome de Miller-Fisher:","options":{"A":"Não é uma variante de Síndrome de Guillain-Barré SGB, caracterizada pela tríade ataxia,\narreflexia a oftalmoplegia.","B":"É uma variante de Síndrome de Guillain-Barré SGB, caracterizada pela tríade ataxia, arreflexia\ndupla a não oftalmoplegia.","C":"É uma variante de Síndrome de Guillain-Barré SGB, caracterizada pela tríade ataxia, arreflexia a\noftalmoplegia.","D":"É uma variante de Síndrome de Guillain-Barré SGB, caracterizada pela tríade ataxia, hipereflexia\na oftalmoplegia."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-330628","number":"330628","sourceNumber":"330628","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"A Síndrome de Guillain-Barré SGB é uma das causas mais frequentes de\npolineuropatia aguda vista nos hospitais gerais. Sendo correto que:","options":{"A":"Várias outras condições neurológicas devem ser distinguidas da SGB. O dilema imediato é\ndiferenciar SGB de uma doença medular crônica.","B":"Várias outras condições neurológicas devem ser distinguidas da SGB. O dilema imediato é\ndiferenciar SGB de uma doença medular aguda.","C":"Várias outras condições neurológicas devem ser distinguidas da SGB. Não existe dilema de\ndiferenciar SGB de uma doença medular aguda.","D":"Várias outras condições neurológicas devem ser distinguidas da SGB. O dilema imediato é\ndiferenciar SGB de uma doença não medular aguda."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-330630","number":"330630","sourceNumber":"330630","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"As áreas de atenção na Síndrome de Guillain-Barré:","options":{"A":"Incluem prevenção de fenômenos tromboembólicos, monitorização cardíaca, não sendo\nnecessário avaliações seriadas de reserva\nventilatória e de fraqueza orofaríngea, proteção de vias\naéreas, manutenção da função intestinal, controle apropriado da dor e nutrição e suporte\npsicológico adequados.","B":"Incluem prevenção de fenômenos tromboembólicos, monitorização cardíaca, avaliações\nseriadas de reserva ventilatória e não de\nfraqueza orofaríngea ou proteção de vias aéreas,\nmanutenção da função intestinal, controle apropriado da dor e nutrição e suporte psicológico\nadequados.","C":"Incluem prevenção de fenômenos tromboembólicos, monitorização cardíaca, avaliações\nseriadas de reserva ventilatória e de\nfraqueza orofaríngea, proteção de vias aéreas, manutenção da\nfunção intestinal, controle apropriado da dor e nutrição e suporte psicológico adequados.","D":"Excluem prevenção de fenômenos tromboembólicos, monitorização cardíaca, avaliações\nseriadas de reserva ventilatória e de\nfraqueza orofaríngea, proteção de vias aéreas, manutenção da\nfunção intestinal, controle apropriado da dor e nutrição e suporte psicológico adequados."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-330632","number":"330632","sourceNumber":"330632","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Os tratamentos modificadores de doença preconizados na Síndrome de Guillain-Barré\n(SGB):","options":{"A":"Incluem um tratamento não medicamentoso (plasmaférese) e um medicamentoso\n(imunoglobulina humana endovenosa). Não se observam\ndiferenças significativas na resposta a\nessas duas formas de tratamento.","B":"Incluem um tratamento não medicamentoso (plasmaférese) e um medicamentoso\n(imunoglobulina humana endovenosa). Se observam\ndiferenças significativas na resposta a essas\nduas formas de tratamento.","C":"Incluem um tratamento medicamentoso (plasmaférese) e um não medicamentoso\n(imunoglobulina humana endovenosa). Não se observam\ndiferenças significativas na resposta a\nessas duas formas de tratamento.","D":"Excluem um tratamento não medicamentoso (plasmaférese) e medicamentoso (imunoglobulina\nhumana endovenosa). Não se observam diferenças\nsignificativas na resposta a essas duas formas\nde tratamento."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-332980","number":"332980","sourceNumber":"332980","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Lactente de 1 ano e 8 meses iniciou há 15 horas quadro febril (38,8ºC) e sinais clínicos\nde infecção de vias aéreas superiores. Não está\nfazendo uso de antibióticos. Há cerca de 30\nminutos, apresentou crise convulsiva caracterizada por movimentos tônico-clônicos generalizados\nde duração aproximada de 4 minutos, sendo então trazido ao pronto atendimento. Pais referem ser\no primeiro episódio na vida da criança. Sem internação prévia. No momento do atendimento, a\ncriança encontra-se com temperatura de 37,9ºC (feito antitérmico em casa após a crise), ativa,\nreativa, sem sinais de irritação meníngea e restante do exame clínico e neurológico normal.\n\nConstatada apenas hiperemia de orofaringe e membrana timpânica, presença de coriza hialina.\nConsiderando que se trata de Crise Febril simples, deve-se:","options":{"A":"fazer benzodiazepínico endovenoso, no Pronto Atendimento, e prescrever anticonvulsivante e\nantitérmicos até consulta com especialista.","B":"fazer benzodiazepínico por via oral, pois a criança está ativa; prescrever anticonvulsivante e\nantitérmicos até consulta com especialista.","C":"fazer benzodiazepínico por via oral, pois a criança está ativa; prescrever apenas antitérmicos.","D":"prescrever antitérmico; não prescrever benzodiazepínico."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-309764","number":"309764","sourceNumber":"309764","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"A convulsão febril é um evento benigno e ocorre em crianças com mais de 1 mês de\nvida, associada a doença febril não causada por infecção do sistema nervoso central. Sobre esse\ntipo de crise convulsiva está correto afirmar:","options":{"A":"Ocorre principalmente em pacientes com antecedentes de crises convulsivas neonatais ou crises\nafebris.","B":"A punção lombar com coleta de liquor está sempre indicada para se excluir infecção do sistema\nnervoso central.","C":"Apesar da evolução benigna, o tratamento com uso de anticonvulsivantes é necessário na\nmaioria das vezes.","D":"O diagnóstico depende de história e exame clínico e neurológico, caracterizando crise epilética e\nafastando infecção do sistema nervoso central e outras crises sintomáticas agudas.","E":"Exames de imagem são sempre indicados para afastar outras causas de doenças no sistema\nnervoso central."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-274980","number":"274980","sourceNumber":"274980","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Lactente 4 meses, sexo masculino, em aleitamento materno exclusivo, dá entrada na\nemergência pediátrica com crise convulsiva tônico-clônica, e você, como médico residente, verifica\nque esse paciente apresenta exame físico normal e está afebril. Dessa forma, quais exames devem\nser considerados para elucidação do diagnóstico para uma criança com idade inferior a 6 meses\nque se apresenta na emergência com primeiro episódio de crise convulsiva afebril?","options":{"A":"Glicemia, eletrólitos, gasometria e punção lombar.","B":"RM, punção lombar e hemograma.","C":"Eletrólitos, radiografia de tórax, ecocardiograma (ECO) e glicemia.","D":"EEG, glicemia, creatinina e punção lombar.","E":"Glicemia, eletrólitos e gasometria."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-247122","number":"247122","sourceNumber":"247122","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Uma das manifestações mais frequentes em neuropediatria são as convulsões febris\n(CF). Com relação a essa enfermidade, assinale a alternativa correta.","options":{"A":"É um evento próprio de crianças, entre os 12 meses até os 7 anos de idade, associado à febre,\nmas sem evidência de infecção intracraniana\nou de outra neurológica aguda.","B":"Orientar a família que crises convulsivas afebris podem proceder à manifestação de crises\nconvulsivas febris e, portanto, auxiliam no diagnóstico de CF.","C":"As CF ocorrem somente quando a temperatura corporal é maior que 39º C.","D":"O EEG na CF é fundamental, pois os achados de anormalidade orientam o diagnóstico, auxiliam\no tratamento e definem o prognóstico,\nprincipalmente nas crises febris recorrentes.","E":"Está relacionada à idade, não deve estar associada a convulsões neonatais, além disso,\nlactentes que apresentam a primeira CF, mesmo\nna ausência de sinais de irritação meníngea,\ndevem realizar exame do líquido cefalorraquidiano."},"answer":"E","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-216830","number":"216830","sourceNumber":"216830","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Paciente com 41 anos de idade, feminina, refere dor com piora a noite, parestesia em\n2º e 3º dedos da mão, perda de força. O\nexame clínico mais sensível e específico que pode\nconfirmar sua hipótese diagnóstica é:","options":{"A":"Durkan.","B":"Tinel.","C":"Phalen.","D":"Jobe."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-221303","number":"221303","sourceNumber":"221303","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Assinale a alternativa INCORRETA com relação aos seminomas mediastinais:","options":{"A":"Constituem 50% dos tumores malignos de células germinativas.","B":"Os sintomas estão relacionados com os efeitos mecânicos do tumor sobre as estruturas\nmediastinais e pulmonares adjacentes.","C":"A síndrome da veia cava superior ocorre em 10% a 20% dos pacientes.","D":"Estes tumores não são sensíveis à radioterapia ou a quimioterapia. O tratamento de escolha\nconsiste na ressecção cirúrgica."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-177947","number":"177947","sourceNumber":"177947","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Das doenças autoimunes listadas abaixo, uma delas está associada ao risco maior de\nneoplasias malignas, justificando a pesquisa de neoplasias ocultas quando do seu diagnóstico.\n\nAssinale-a.","options":{"A":"Artrite reumatoide.","B":"Periarterite nodosa.","C":"Lúpus eritematoso sistêmico.","D":"Esclerose sistêmica progressiva.","E":"Dermatopolimiosite."},"answer":"E","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-177037","number":"177037","sourceNumber":"177037","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Pedro, 64 anos de idade, previamente hígido, negou uso de medicamentos\ncontinuamente, refere quadro de parestesia de\nmembros inferiores com início há 2 anos. Há um\nano apresenta parestesia de membros superiores. Eletroneuromiografia: polineuropatia\nsensitivo-motora axonal. Das etiologias listadas abaixo assinale a IMPROVÁVEL para Pedro.","options":{"A":"Insuficiência renal crônica.","B":"Exposição a toxinas.","C":"Deficiência de cianocobalamina.","D":"Diabetes mellitus."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-155618","number":"155618","sourceNumber":"155618","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Assinale a alternativa que apresenta as afirmativas verdadeiras sobre crise convulsiva\nfebril. I) Ocorrem na primeira infância até os\ncinco anos de idade. II) Nas crises simples, está\nindicado coleta de liquor em menores de 12 meses com suspeita de infecção de sistema nervoso\ncentral. III) A crise febril complexa é caracterizada por focalidade, duração maior que 15 minutos e\ncrises repetidas em 24hs.","options":{"A":"Apenas I.","B":"Apenas II e III.","C":"Apenas I e II.","D":"Apenas I e III.","E":"I, II e III."},"answer":"E","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-151090","number":"151090","sourceNumber":"151090","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Mulher, 51 anos, hipertensa há 5 anos, diabética há 1 ano, dislipidêmica e portadora de\nartrite reumatóide diagnosticada há 6 meses. Em uso de captopril 75 mg/dia, sinvastativa 40\nmg/dia, metotrexato 15 mg/semana, ácido fólico 5 mg/semana, prednisona 5 mg/dia,\nhidroxicloroquina 400 mg/dia. Retorna para consulta de rotina referindo dor muscular. Ao exame\nfísico apresenta-se em bom estado geral, estável hemodinamicamente, eupneica, PA: 130 x 90\nmmHg; FC 80 bpm, sem artrite ao exame clínico. Cientes de que o manejo dos efeitos adversos\nrelacionados ao uso de medicações deve ser uma constante na prática clínica, assinale dentre as\nmedicações abaixo a alternativa que contenha o possível medicamento causador da mialgia:","options":{"A":"Hidroxicloroquina.","B":"Captopril.","C":"Sinvastatina.","D":"Todas as alternativas acima."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-138045","number":"138045","sourceNumber":"138045","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Homem de 36 anos apresentou quadro de febre (38,4°C), mialgia, artralgia e exantema\nassociado a prurido que durou 6 dias. Uma semana após, o paciente iniciou dificuldade para\ndeambular que evoluiu com fraqueza para pegar objetos. Na suspeita de síndrome de\n\nGuillain-Barré, qual o exame e o seu achado que melhor corrobora com esse diagnóstico?","options":{"A":"Punção lombar - liquor demonstrando aumento do número de células, proteína normal e glicose\nnormal.","B":"Punção lombar - liquor demonstrando número de células normais, proteína normal e glicose\naumentada.","C":"Punção lombar - liquor demonstrando número de células normais, proteína aumentada e glicose\nnormal.","D":"Ressonância magnética demonstrando lesão do trato piramidal bilateral.","E":"Ressonância magnética demonstrando lesão em medula cervical."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-107524","number":"107524","sourceNumber":"107524","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Mulher, 67 anos, tem antecedente hígido e decide procurar consultório de Clínica\nMédica para realização de um chek-up, já que\na última procura ao médico faz três anos. É tabagista\ncarga de 70 maços/ano. Exame clínico: PA = 138 x 88 mmHg; FC = 92 bpm; IMC = 28 kg/m²,\nSemiologia cardíaca, pulmonar, abdominal e de membros inferiores sem alterações. Assinale a\nalternativa INCORRETA:","options":{"A":"A paciente preenche critérios de síndrome metabólica.","B":"O rastreamento de câncer colorretal pode ser solicitado para essa paciente, sangue oculto nas\nfezes ou colonoscopia.","C":"A mamografica e a colpocitologia oncótica devem ser solicitadas.","D":"Em relação à imunização, recomenda-se a vacinação para pneumococo, influenza ou gripe e a\ndupla adulta.","E":"Faz parte dos exames de check-up, solicitar a densitometria óssea."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-106953","number":"106953","sourceNumber":"106953","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Sobre a prevenção de doenças respiratórias em idosos, podemos afirmar que","options":{"A":"a vacina contra influenza é válida por cinco anos, não devendo ser repetida antes desse período.","B":"a vacina pneumocócica deve ser repetida anualmente no Outono.","C":"é recomendada uma dose anual de vacina contra influenza durante a Primavera.","D":"pacientes com mais de 65 anos devem receber, pelo menos, uma dose de vacina pneumocócica\ndurante a vida."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-107005","number":"107005","sourceNumber":"107005","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Um paciente com 66 anos, sexo masculino, procurou a emergência de um hospital\ngeral com ferimento na mão direita,\nocasionado por fragmento de madeira que ocorreu no dia\nanterior. O paciente apresentava febre de 38°C, dor local de moderada intensidade e secreção\npurulenta no ferimento. O debridamento, realizado pelo médico plantonista, mostrou uma lesão\ncom, aproximadamente, 1 cm de profundidade, com halo de hiperemia, secreção purulenta e área\nde necrose. Foi retirado fragmento de madeira com, mais ou menos, 1×0,6 cm. O paciente afirmava\nque, há mais ou menos 7 anos, havia tomado 3 doses da vacina contra o Tétano, em Unidade de\nSaúde (confirmado pela caderneta de vacinação), indicadas por ocasião de outro ferimento. De\nantecedentes, era portador de Diabetes Mellitus mal controlada. No caso acima relatado, além do\ndebridamento, qual medida deve ser recomendada para a prevenção do Tétano?","options":{"A":"Imunoglobulina antitetânica homóloga ou heteróloga.","B":"Apenas o debridamento bem feito é suficiente, porque o paciente já recebeu 3 doses da vacina.","C":"Aplicação da vacina antitetânica com orientação para o paciente completar o esquema de 3\ndoses.","D":"Uma dose de reforço da vacina antitetânica."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-107016","number":"107016","sourceNumber":"107016","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Um paciente de 15 anos, sexo masculino, é mordido na face por cão aparentemente\nsadio. O garoto tomou dose de reforço de\nvacina antitetânica, mas não recebeu vacinação\nantirrábica. O exame mostra que o ferimento é profundo, múltiplo e com exposição de periósteo. 1\nhora após a ocorrência do fato, você atende o paciente. No caso acima, portanto, é CORRETO\nafirmar que","options":{"A":"a ferida deve ser suturada porque o ferimento é na face.","B":"mordeduras na face e couro cabeludo são consideradas graves e neste caso realizar a\nobservação do cão agressor e indicar a vacina antirrábica.","C":"podemos esperar a observação do cão agressor para iniciar a vacinação porque o ferimento é\nconsiderado leve.","D":"em mordeduras por cão, a profilaxia com antibióticos é sempre indicada porque a infecção\nocorre emmais de 30% dos casos."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-64869","number":"64869","sourceNumber":"64869","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Uma paciente, 75 anos, branca, hipertensa há 20 anos, sedentária, com história de 3\nquedas em um ano em seu próprio domicílio,\ncomparece ao atendimento, queixando-se de\nhiporexia e dor intensa em ambos os joelhos. O marido, de 80 anos, vítima de AVE, está acamado\ne totalmente dependente para as atividades de vida diária. A paciente faz uso diário de\n\nanti-inflamatórios, complementando com opiáceos em um frequência de 3 vezes na semana, além\nde captopril 25 mg de 8 em 8 horas,\nhidroclorotiazida 25 mg/dia e bromazepam 3 mg à noite. Na\nconsulta, apresentou-se muito preocupada, desanimada e relatando dificuldades para cuidar de seu\nesposo. Ao exame físico, identifica-se um humor deprimido, com Escala de Depressão Geriátrica\n7/15; Pressão Arterial 130/80 mmHg; Frequência Cardíaca 72 bpm; genuvaro, edema em ambos os\njoelhos. Isso considerando, assinale a alternativa correta em relação à avaliação e conduta para a\npaciente em questão.","options":{"A":"Na avaliação da hiporexia de paciente, não é necessário considerar o uso de medicamentos.","B":"O risco de quedas aumentado não tem relação com o tipo, a quantidade e a posologia das\nmedicações em uso.","C":"A abordagem da paciente deve incluir a capacidade de compreensão da mesma em relação à\nadministração das medicações, bem como a posologia e a classe do fármaco.","D":"Na avaliação multidimensional desta paciente, o risco aumentado de quedas é atribuido\nisoladamente ao uso de anti-hipertensivos.","E":"O uso de opiáceos é o principal fator determinante no humor da paciente."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-64876","number":"64876","sourceNumber":"64876","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Sobre a administração de medicações em idosos, assinale a alternativa correta.","options":{"A":"Deve ser dada preferência às medidas farmacológicas, antes da tentativa do uso de qualquer\nmedida não farmacológica, especialmente no grupo de idosos frágeis.","B":"As manisfestações clínicas e o manejo farmacológico em idosos são bem claros e, na maioria\ndos casos, obedecem a protocolos estabelecidos\ne validados, não sendo necessária a\nindividualização da dose de um fármaco.","C":"O uso de fármacos em idosos pode ser conduzido igualmente à prescrição em um adulto jovem,\npois não existem diferenças comprovadas em relação à farmacocinética e à farmacodinâmica\nnaquele grupo etário.","D":"Internações hospitalares devido a efeitos adversos de fármacos em idosos. Contribuem para um\nquadro clínico atípico, dificultando o diagnóstico, porém ocorrem em menos de 15% dos casos.","E":"A polifarmácia em idosos pode ocorrer como resultado da própria pressão a que o médico está\nsubmetido, para resolver uma dada situação clínica, frente às múltiplas demandas que o paciente\napresenta e a necessidade de resolução rápida destas queixas."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-64911","number":"64911","sourceNumber":"64911","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Em relação à farmacocinética, assinale a alternativa correta que, em geral, se aplica à\npopulação idosa.","options":{"A":"A absorção das drogas está alterada; o volume de distribuição está diminuindo no caso de\nsubstâncias lipossolúveis; há diminuição dos níveis plasmáticos no caso de substâncias\nhidrossolúveis.","B":"A absorção das drogas está inalterada; o volume de distribuição está diminuindo no caso de\nsubstâncias lipossolúveis; há diminuição dos níveis plasmáticos no caso de substâncias\nhidrossolúveis.","C":"A absorção das drogas está inalterada, o volume de distribuição está aumentado no caso de\nsubstâncias lipossolúveis; há diminuição dos níveis plasmáticos no caso de substâncias\nhidrossolúveis.","D":"A absorção das drogas está inalterada; o volume de distribuição está aumentando no caso de\nsubstâncias lipossolúveis; há aumento dos níveis plasmáticos no caso de substâncias\nhidrossolúveis.","E":"A absorção das drogas está alterada; o volume de distribuição está diminuindo no caso de\nsubstâncias lipossolúveis; há aumento dos níveis plasmáticos no caso de substâncias\nhidrossolúveis."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-60272","number":"60272","sourceNumber":"60272","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"O tabagismo é conhecido como fator envolvido na gênese de diversos tipos de câncer.\nSobre cigarro e câncer, é INCORRETO afirmar:","options":{"A":"O fumo é responsável por mais de 1 milhão de mortes anualmente no mundo.","B":"Os fatores mais importantes na determinação do câncer de pulmão em fumantes são: a duração\ne a quantidade, sendo que o risco aumenta\nconforme aumenta o numero de cigarros fumados.","C":"O tabagismo aumenta o risco de todos os tipos histológicos de câncer de pulmão: carcinoma\nespinhoso, carcinoma de pequenas células, adenocarcinoma e carcinoma de células gigantes.","D":"Cessação do tabagismo mantém o risco de câncer de pulmão de ex-tabagistas elevado por\nalguns anos comparado ao risco de quem nunca fumou.","E":"O tabagismo tem relação com câncer de boca, laringe, pulmão, estômago, mas não guarda\nrelação com o câncer de bexiga, ureter e pelve renal."},"answer":"E","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-62463","number":"62463","sourceNumber":"62463","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Lactente de 6 meses de idade é levada ao pronto-socorro por sua mãe, com história de\nter caído do berço ao tentar pular por cima da grade. Ao exame apresenta hematoma em tronco e\nfratura em metáfise proximal de tíbia esquerda. Além dos cuidados com as lesões, qual outra\nconduta o pediatra deverá adotar?","options":{"A":"Denunciar a mãe à polícia.","B":"Orientar a mãe para que aumente a grade do berço.","C":"Encaminhar a criança para exame de corpo de delito com médico legista.","D":"Orientar a mãe para ficar mais atenta aos acidentes domésticos.","E":"Notificar ao conselho tutelar a suspeita de maus-tratos."},"answer":"E","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-45437","number":"45437","sourceNumber":"45437","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Assinale a alternativa INCORRETA quanto aos sinais e sintomas que são compatíveis\ncom insuficiência cardíaca em um lactente:","options":{"A":"Ritmo de galope, baixo peso para a idade.","B":"Taquipneia, taquicardia, pele úmida e fria.","C":"Índice cardiotorácico de 70%, dispneia aos esforços.","D":"Cardiomegalia, abaulamento precordial.","E":"Edema de membros inferiores, hepatimetria normal."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-45526","number":"45526","sourceNumber":"45526","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Paciente epiléptico com crises caracterizadas por: mal-estar epigástrico, parada\ncomportamental, automatismos oromandibulares e\ngestuais à direita, distonia à esquerda (na mão),\nevoluindo para generalização secundária. Pergunta-se: esta crise é sugestiva de início em qual\nlocalização?","options":{"A":"Lobo temporal D.","B":"Lobo temporal E.","C":"Lobo frontal D.","D":"Lobo frontal E.","E":"Lobo parietal D."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-45897","number":"45897","sourceNumber":"45897","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Assinalar a alternativa que corresponda a vacinação completa do profissional de saúde\nque presta assistência tanto para pacientes\nadultos como pediátricos.","options":{"A":"Hepatite A e B, gripe, antitetânica, tríplice viral, antivaricela, antiamarílica, pneumococcus.","B":"Hepatite A e B, H1N1, gripe, dengue, antitetânica, varicela, tríplice viral, pneumococcus.","C":"Hepatite B, H1N1, gripe, antiamarílica, varicela, dengue, antiamarílica.","D":"Hepatite A, B e C, H1N1, gripe, antitetânica, varicela, antiamarílica, pneumococcus.","E":"Hepatite A e B, H1N1, gripe tríplice viral, antitetânica, antivaricela, pneumococcus."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-34517","number":"34517","sourceNumber":"34517","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Considerando que as alterações do estado mental correspondem a 30% das avaliações\nde emergência nos paciente idosos, não podemos\nafirmar que:","options":{"A":"O estado mental frequentemente serve como parâmetro da saúde geral do idoso e, geralmente,\né o único sintoma de doenças subjacentes\ngraves.","B":"O delirium, síndrome clínica caracterizada por distúrbio agudo da atenção e da cognição, não\ndependente de fatores predisponentes e tem como patogênese exclusiva desarranjos globais por\ndiminuição generalizada da atividade cortical, com falha da transmissão colinérgica em pacientes\nidosos internados.","C":"As características principais do delirium incluem o início agudo e a desatenção, além de\ndesorganização do pensamento, alteração do nível de consciência, retardo ou agitação\npsicomotora, alucinações, e inversão do ciclo sono-vigília.","D":"Depressão e distúrbios psicóticos não orgânicos são diagnósticos diferenciais do delirium.","E":"Em geral, devem ser utilizadas as abordagens não farmacológicas em todos os pacientes com\ndelirium e as farmacológicas devem ser reservadas apenas para os pacientes nos quais os\nsintomas de delirium possam resultar na interrupção das terapias médicas ou ameaçar a segurança\nde si ou de outrem."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-31889","number":"31889","sourceNumber":"31889","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"A Síndrome de Korsakoff é uma síndrome amnéstica causada por:","options":{"A":"Deficiência de vitamina B12.","B":"Deficiência de acetilcolina.","C":"Deficiência de vitamina B1.","D":"Ação direta do álcool.","E":"Idade avançada."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-34591","number":"34591","sourceNumber":"34591","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"A definição de caso de síndrome respiratória aguda grave (SRAG) em adultos é:","options":{"A":"Paciente com febre alta aferida, tosse e dispneia, acompanhada de aumento da frequência\ncardíaca; hipotensão, e podendo ou não ser\nacompanhado de alterações laboratoriais e\nradiológicas.","B":"Pacientes com febre alta aferida, tosse e dispneia, acompanhada de aumento da frequência\ncardíaca e respiratória; e podendo ou não\nser acompanhado de alterações laboratoriais e\nradiológicas.","C":"Paciente com febre alta mesmo que referida, tosse e dispneia, podendo ou não ser\nacompanhado de alterações laboratoriais e radiológicas.","D":"Paciente com febre alta mesmo que referida, tosse e dispneia e que tenham alterações\nlaboratoriais e radiológicas.","E":"Paciente com febre alta mesmo que referida, tosse e dispneia, acompanhada de aumento da\nfrequência respiratória; hipotensão, podendo ou não ser acompanhada de alterações laboratoriais e\nradiológicas."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-25739","number":"25739","sourceNumber":"25739","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Nos casos de tétano orienta-se:","options":{"A":"O reforço vacinal deve ser feito a cada 5 anos","B":"O soro antitetânico ou imunoglobulina antitetânica deve ser usado em todos os casos de tétano\nacidental","C":"A limpeza cirúrgica inadequada com permanência de material estranho pode ser responsável\npela manutenção da doença","D":"O tétano não é considerado uma doença imunoprevinivel.","E":"Vacina antitetânica deve ser administrado 2, 4, 6, 15 e 24 meses."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-359387","number":"359387","sourceNumber":"359387","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Mulher de 42 anos queixa-se de fraqueza e dor proximal nos membros superiores e\ninferiores há duas semanas. Apresenta astenia, dor, edema e vermelhidão nas articulações das\nmãos e rigidez matinal de 40 minutos. Ao exame físico, apresenta pápulas arroxeadas na face\ndorsal das articulações metacarpofalangeanas e interfalangeanas das mãos. A face apresenta\neritema malar envolvendo as sulcos nasolabiais. Exames de laboratório: Hg 10,5g/dL; leucócitos\n6.540/mm³; neutrófilos 3.450/mm³; linfócitos 1.340/mm³; plaquetas 169.000/mm³; CPK 540U/L; FAN\nreagente 1/320 (padrão citoplasmático pontilhado fino); fator reumatoide não reagente; anti-SSA\nnão reagente; anti-DNA não reagente; anti-Sm não reagente; anti-RNP não reagente. Assinale a\nalternativa que apresenta o diagnóstico MAIS PROVÁVEL nesse caso:","options":{"A":"Artrite reumatoide.","B":"Dermatomiosite.","C":"Doença mista do tecido conjuntivo.","D":"Lupus eritematoso sistêmico."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-301222","number":"301222","sourceNumber":"301222","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Mulher de 23 anos, atendente de supermercado, é levada ao Pronto Socorro com relato\nde ter apresentado, durante o trabalho,\numa crise convulsiva interpretada como do tipo\n\ntônico-clônico generalizada de dois minutos de duração. Nega quaisquer eventos neurológicos\nprévios. Não possui comorbidades conhecidas,\nnega trauma anterior, não faz uso de medicamentos\ne nem de drogas lícitas ou ilícitas. O exame clínico e neurológico, assim como os exames de\nlaboratório e a tomografia computadorizada do crânio, não apresentam anormalidades. Assinale a\nalternativa que apresenta a conduta MAIS ADEQUADA nesse caso.","options":{"A":"Dar alta com a solicitação de eletroencefalograma, ressonância magnética do crânio e\nencaminhamento ao neurologista","B":"Prescrever dose de ataque de fenitoína e dar alta com anticonvulsivante oral, que deve ser\nusado, pelo menos, por 1 ano","C":"Prescrever dose de ataque de fenitoína pela via IV e manter observação hospitalar por 24h","D":"Transferir para hospital com neurologista, para realizar a extensão propedêutica com a paciente\ninternada"},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-255920","number":"255920","sourceNumber":"255920","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Mulher de 81 anos comparece para consulta ambulatorial. Familiares relatam que a\npaciente está sonolenta, confusa e desorientada há cerca de 12 dias. Negam febre, sintomas\nrespiratórios, abdominais ou urinários. O apetite está preservado. É portadora da doença de\nAlzheimer, asma brônquica, rinite alérgica, incontinência urinária, osteoporose, acalasia\nidiopática e\nhipertensão arterial sistêmica. É dependente para as atividades instrumentais de vida diária e\nrequer auxílio para banho e para se vestir. Está em uso de losartana, alendronato, vitamina D,\ncarbonato de cálcio e dexclorfeniramina se sintomas nasais alérgicos. Há 15 dias iniciou o uso de\noxibutinina para o tratamento de incontinência urinária e clonidina para ajuste da pressão\narterial.\n\nAo exame físico, apresenta PA 128/78mmHg, FC 61bpm, FR 15ipm, SpO2 98%. Está sonolenta,\ndesorientada no tempo e no espaço, com\nredução da atenção, abre os olhos ao chamado e\nresponde a comandos simples. Não apresenta outras anormalidades. Os exames de laboratório\nestão dentro dos limites da normalidade. Cartão de vacinação: dupla adulto aos 76 anos e influenza\nanualmente nos últimos cinco anos. Realizou colonoscopia aos 69 anos, que não apresentou\nanormalidades. Assinale a alternativa que apresenta uma medida ADEQUADA para a prevenção de\ndoenças nessa paciente.","options":{"A":"Administrar vacinas para herpes-zoster vírus e pneumocócica 23.","B":"Realizar nova colonoscopia","C":"Realizar mamografia","D":"Solicitar perfil lipídico e glicemia de jejum"},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-203312","number":"203312","sourceNumber":"203312","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Um homem de 35 anos é trazido ao pronto-socorro por familiares que relatam perda\nsúbita de consciência com movimentos\ntônico-clônicos generalizados que já duravam sete minutos\nà admissão. Negaram trauma, uso de drogas ilícitas ou de medicamentos, comorbidades\nconhecidas ou episódio semelhante prévio. A glicemia capilar era 97 mg/dL. Sobre esse quadro\nclínico, assinale a alternativa CORRETA:","options":{"A":"A conduta imediata deve ser infusão intravenosa de fenitoína e realização de tomografia\ncomputadorizada do crânio.","B":"Deve-se proteger a cabeça e posicionar o paciente em decúbito lateral para evitar aspiração,\nenquanto se aguarda a resolução do quadro, uma vez que a maioria das crises convulsivas é\nautolimitada.","C":"É necessária a realização de eletroencefalograma para se firmar o diagnóstico definitivo.","D":"Trata-se de uma emergência neurológica com alta mortalidade e deve ser administrado\nmidazolam pela via intramuscular."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-203279","number":"203279","sourceNumber":"203279","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Lactente, sexo masculino, 20 meses de idade apresenta-se com atraso do\ndesenvolvimento neuropsicomotor secundário à infecção\ncongênita por Zika vírus. É trazido pela\nmãe com relato de crise convulsiva caracterizada por movimentos incoordenados de membro\nsuperior direito com duração de 20 minutos, sem perda de consciência. Informa que a criança\napresenta febre baixa há cerca de três dias, com coriza e tosse. Ao exame físico, evidencia-se\ncriança acordada, atenta ao meio, temperatura axilar 38°C, eupneica, com hiperemia de orofaringe,\nsem sinais menígeos, sem outras alterações significativas. Assinale a alternativa que contém dados\nque indicam RISCO AUMENTADO de epilepsia nesse caso:","options":{"A":"Característica focal da crise, duração igual a 20 minutos e atraso do desenvolvimento\nneuropsicomotor.","B":"Crise desencadeada por febre baixa, crise após 24 horas do início da febre e ausência de perda\nde consciência.","C":"Duração da crise igual a 20 minutos, ausência de perda de consciência e ausência de sinais\nmeníngeos.","D":"Idade, crise desencadeada por febre baixa e atraso do desenvolvimento neuropsicomotor."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-149945","number":"149945","sourceNumber":"149945","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"No que concerne à síndrome de Guillain-Barré (polirradiculoneuropatia aguda ou\nsubaguda, de caráter progressivo), assinale a alternativa ERRADA:","options":{"A":"Sua etiopatogenia é alvo de controvérsia, mas acredita-se que a afecção seja mediada por\nfatores imunitários; entre os possíveis gatilhos,\nsuspeita-se de que possa estar incluída a infecção\npelo vírus Zika.","B":"Embora possam ocorrer, os distúrbios sensitivos são em geral menos conspícuos que os\ndistúrbios motores.","C":"Na análise do liquor, o achado de elevada concentração de proteína sem aumento da\ncelularidade favorece o diagnóstico da afecção.","D":"O tratamento de eleição é a corticoterapia (prednisona 1,0 mg/kg por dia), ao passo que outras\nmodalidades terapêuticas, como plasmaférese e a administração por via intravenosa de\nimunoglobulina, não beneficiam os pacientes acometidos pela doença."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-78346","number":"78346","sourceNumber":"78346","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Com relação à saúde do idoso, é CORRETO afirmar que:","options":{"A":"Entre os fatores de risco para quedas, observa-se idade maior que 80 anos, o gênero feminino e\ndeficit cognitivo.","B":"Delírio, restrição da mobilidade, retenção urinária, infecção e efeitos da medicação são causas\nreversíveis de incontinência urinária.","C":"A deficiência em processar informações associadas ao tempo resulta em um número\nsignificativo de colisões traseiras provocadas por motoristas idosos.","D":"Broncodilatadores, digitálicos, hipertireoidismo e asma estão relacionados com sintomas de\ndepressão em idosos."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-71445","number":"71445","sourceNumber":"71445","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Adolescente, 13 anos, sexo feminino, chega acompanhada da mãe. Mãe informa\nsarcasticamente: ''Essa menina parece burra,\nporque sempre toma bomba na escola, não fala nada\ne é brigona. Tá emagrecendo, mas não falta comida lá em casa! Agora apareceu com isso aí na\ncabeça e tá até com mau cheiro''. Adolescente sentada ao lado da mãe, calada, encolhida, olhando\npra baixo. Só fala quando interrogada, respondendo em voz muito baixa, com frases curtas.\n\nSomente com esses dados poderíamos pensar em:","options":{"A":"Tratar-se de adolescente apresentando sintomas típicos de bulimia.","B":"Tratar-se de adolescente apresentando sinais e sintomas sugestivos de depressão e de bulimia.","C":"Tratar-se de adolescente apresentando sinais e sintomas sugestivos de depressão e de\nviolência doméstica.","D":"As hipóteses B e C estão corretas."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-60387","number":"60387","sourceNumber":"60387","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Mulher de 32 anos é atendida no Centro de Saúde e traz consigo cartão de vacinação.\nNão está grávida e o médico verifica que o\nesquema básico de imunização está completo até seus\n15 anos de idade. São orientações corretas, quanto à continuidade de seu esquema vacinal,\nEXCETO:","options":{"A":"A vacina contra difteria e tétano tipo adulto dever ser administrada a cada 10 anos.","B":"A vacina contra varicela não é necessária em caso de história prévia de catapora.","C":"A vacina tríplice viral deverá ser complementada com 1 ou 2 doses.","D":"As vacinas contra as hepatites A e B serão necessárias se não houver evidência sorológica de\nimunidade."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-45236","number":"45236","sourceNumber":"45236","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Homem de 29 anos de idade, com história de etilismo pesado, foi trazido pela família ao\npronto-socorro porque estava muito sonolento e agitado há 2 dias. Ao exame, o paciente alternava\nagitação psicomotora com sonolência; estava desorientado; desatento; taquicárdico (102 bpm) e\napresentava sudorese; tremores de mãos; PA: 150 x 105 mmHg. Após instituir hidratação\nintravenosa e iniciar investigação da causa do quadro de delirium, qual é o medicamento prioritário\nneste caso?","options":{"A":"Clonidina VO (0,1-0,2 mg/dia).","B":"Dissulfiram VO (125-500 mg/dia).","C":"Lorazepam IV ou IM (1-4 mg/dia).","D":"Propranolol VO (20-80 mg/dia)."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-45052","number":"45052","sourceNumber":"45052","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"A dor pode ser conceituada como uma experiência sensorial desagradável associda a\ndano tecidual real ou potencial. É um sintoma\nextremamente frequente nos pacientes em\nenfermarias e ambulatórios, mas ainda cercada de mitos e preconceitos que atrapalham seu\nmanejo apropiado. Em relação á dor crônica, assinale a alternativa ERRADA:","options":{"A":"A associação de drogas adjuvantes como carbamazepina, gabapentina, bifosfonatos e outras\nauxiliam no tratamento de dores crônicas.","B":"A metadona é mais potente e eficaz que a morfina para a dor neuropática.","C":"A prescrição de analgésicos deve seguir os seguintes critérios básicos da Organização Mundial\nde Saúde: pela boca, pelo relógio, pela escada\nanalgésica, individualizada e, com atenção aos\ndetalhes.","D":"O risco de depressão respiratória e dependência psicológica é muito alto em um paciente com\ndor crônica e, por isto, a morfina deve ser\nevitada nestes pacientes e a meperidina deve ser a\ndroga de escolha,"},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-31507","number":"31507","sourceNumber":"31507","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Senhor de 72 anos, marceneiro em atividade, seis anos de escolaridade. Segundo\nrelato da sua esposa, vem apresentando, há\ncerca de dois anos, esquecimento, episódios de\ndesorientação temporal e espacial com interferência em sua atividade profissional. Foram aplicados\ntestes de avaliação do estado cognitivo com resultados abaixo do escore esperado para sua idade\ne escolaridade nos domínios: memória, orientação temporal e linguagem. Não apresenta sintomas\ndepressivos. Escala de avaliação funcional com alterações para a execução das atividades\ninstrumentais da vida diária. Sem doenças clínicas evidentes, nem uso de medicamentos. Qual o\ndiagnóstico mais provável?","options":{"A":"Delirium.","B":"Demência frontotemporal.","C":"Senilidade.","D":"Síndrome demencial."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-31559","number":"31559","sourceNumber":"31559","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Sobre a prevenção de doenças respiratórias em idosos, podemos afirmar:","options":{"A":"A vacina contra influenza é válida por cinco anos, não devendo ser repetida antes desse\nperíodo.","B":"A vacina pneumocócica deve ser repetida anualmente no outono.","C":"É recomendada uma dose anual de vacina contra a influenza durante a primavera.","D":"Pacientes com mais de 65 anos devem receber, pelo menos, uma dose de vacina pneumocócica\ndurante a vida."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-372556","number":"372556","sourceNumber":"372556","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Um homem de 40 anos, emagrecido, foi admitido na Santa Sasa de Alfenas com\nhistória de dificuldade de marcha há 6\nmeses, com piora há 1 semana. Nega doenças prévias. Ao\nexame físico, tem andar com base alargada, parestesias e disestesias, sobretudo em membros\ninferiores, perda de sensibilidade propriocetptiva e vibratória, além de pupilas de\nArgyll-Robertson.\nCom base nas informações, marque a alternativa que apresenta o diagnóstico mais provável:","options":{"A":"Déficit de vitamina B12.","B":"Neurotuberculose.","C":"Neurosifilis parenquimatosa.","D":"Neurotoxoplasmose."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-365969","number":"365969","sourceNumber":"365969","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Um paciente adulto apresenta episódios de crises focais com consciência preservada,\nfrequentemente com sensações viscerais epigástricas ascendentes, seguidas de perda de contato\ncom o meio e automatismos oromastigatórios e manuais. Sua história médica revela que essas\ncrises tiveram início na infância tardia. A forma mais provável de epilepsia descrita é:","options":{"A":"Epilepsia do lobo frontal.","B":"Epilepsia generalizada idiopática.","C":"Epilepsia temporal associada à esclerose de hipocampo.","D":"Epilepsia mioclônica juvenil."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-365964","number":"365964","sourceNumber":"365964","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Paciente, 45 anos, sexo feminino, consulta seu médico relatando dor persistente no\nbraço direito após um acidente de carro ocorrido há 6 meses. Ela descreve a dor como uma\nsensação de queimação e formigamento. Com base na qualidade sensitiva da dor descrita, a\nclassificação mais provável dessa dor seria:","options":{"A":"A dor é aguda e o diagnóstico está associado à distensão ou espasmo de uma víscera oca.","B":"A dor é bem localizada e o diagnóstico frequentemente está associado à inflamação de um\nórgão.","C":"Geralmente é uma dor surda e profunda, muitas vezes referida a uma localização distante da\nlesão real e o diagnóstico é sugerido por padrões como irradiação da dor ou sintomas que não\nestão diretamente relacionados a área afetada.","D":"Geralmente é vaga, e o diagnóstico é sugerido por dor desproporcional à lesão tecidual,\ndisestesia."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-361752","number":"361752","sourceNumber":"361752","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Paciente do sexo feminino, 30 anos, comparece ao AGD por queixa de fraqueza há 6\nmeses. Relata que acorda bem, mas que, ao longo do dia, sente um cansaço progressivo, com\nptose, alteração visual caracterizada como diplopía. Realizou em um PS externo a aplicação de\nbolsa de gelo durante a ptose, que melhorou o quadro. Nega outras comorbidades conhecidas. A\nrespeito do caso supracitado, assinale a alternativa correta.","options":{"A":"A despolarização do túbulo T, que é uma estrutura presente juntamente com o retículo\nsarcoplasmático, induz a liberação de íons sódio, que participarão da contração muscular.","B":"A terapia sintomática objetiva melhorar a condução na junção neuromuscular pelo uso de\ncolinesterásicos (ex. piridostigmina), que inibem a hidrólise da acetilcolina pela\nacetilcolinesterase,\naumentando o tempo de exposição dos receptores aos mediadores químicos.","C":"A junção neuromuscular é formada pela porção terminal do neurônio motor, a fenda sinaptica e a\nporção pós-juncional do músculo efetor. Para que a sinapse ocorra, é necessário que haja a\nliberação de vesículas contendo cálcio - principal neurotransmissor - na fenda sináptica.","D":"A ação dos autoanticorpos nos receptores nicotínicos pós- sinápticos faz com que haja menor\nação da acetilcolina na fenda sináptica, o\nque diminuirá a produção de potencial de ação\npropagada pelos túbulos T, com menor liberação de cálcio pelo retículo sarcoplasmático."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-355383","number":"355383","sourceNumber":"355383","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Uma criança de 5 anos é levada ao pronto-socorro apresentando fraqueza progressiva\ne ascendente nas pernas há 3 dias. Durante o\nexame físico, é observado um déficit motor simétrico\nnas pernas, com permanência e recuperação rápida dos movimentos quando é aplicado um\nestimulo doloroso. A criança também apresenta reflexos tendinosos profundos diminuídos. O\npaciente possui histórico de infecção respiratória alta recente. Diante desses achados clínicos,\nqual\né o diagnóstico mais provável?","options":{"A":"Poliomielite.","B":"Mielite transversa.","C":"Encefalite viral.","D":"Síndrome de Guillain-Barré."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-342045","number":"342045","sourceNumber":"342045","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Mulher, 20 anos de idade, dá entrada na Unidade de Pronto Atendimento duas horas\napós episódio de crise tônico-clônica\ngeneralizada. Refere ser o segundo episódio, tendo o primeiro\nocorrido há dois meses. Nega comorbidades, trauma, uso de álcool, tabaco ou drogas ilícitas. Faz\nuso apenas de contraceptivo oral. Ao exame, apresenta-se em bom estado geral, sinais vitais\nestáveis. Exame segmentar e neurológico sem achados. Realizada tomografia computadorizada de\ncrânio sem alterações. Diante do caso clínico, com relação ao diagnóstico mais provável, pode-se\nafirmar:","options":{"A":"Durante ou após uma crise, pode ocorrer morte súbita inesperada decorrente de apneia ou\narritmia.","B":"As crises sempre ocorrem após um fator desencadeante, como a estimulação luminosa\nintermitente.","C":"Apesar de haver interferência na qualidade de vida a mortalidade é equiparável à da população\ngeral.","D":"As crises geralmente deixam sequelas neurológicas, levando a déficit cognitivo."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-342046","number":"342046","sourceNumber":"342046","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Mulher, 20 anos de idade, dá entrada na Unidade de Pronto Atendimento duas horas\napós episódio de crise tônico-clônica\ngeneralizada. Refere ser o segundo episódio, tendo o primeiro\nocorrido há dois meses. Nega comorbidades, trauma, uso de álcool, tabaco ou drogas ilícitas. Faz\nuso apenas de contraceptivo oral. Ao exame, apresenta-se em bom estado geral, sinais vitais\nestáveis. Exame segmentar e neurológico sem achados. Realizada tomografia computadorizada de\ncrânio sem alterações. Com base no quadro descrito, indique o exame complementar mais\nadequado neste momento:","options":{"A":"Ressonância nuclear magnética de crânio.","B":"Eletroencefalograma.","C":"Angiotomografia computadorizada de crânio.","D":"Exame de líquor."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-342047","number":"342047","sourceNumber":"342047","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Mulher, 20 anos de idade, dá entrada na Unidade de Pronto Atendimento duas horas\napós episódio de crise tônico-clônica\ngeneralizada. Refere ser o segundo episódio, tendo o primeiro\nocorrido há dois meses. Nega comorbidades, trauma, uso de álcool, tabaco ou drogas ilícitas. Faz\nuso apenas de contraceptivo oral. Ao exame, apresenta-se em bom estado geral, sinais vitais\nestáveis. Exame segmentar e neurológico sem achados. Realizada tomografia computadorizada de\ncrânio sem alterações. Indique a melhor conduta terapêutica a ser realizada, neste momento, na\npaciente:","options":{"A":"Aguardar a realização do exame complementar para prescrição de fármaco.","B":"Expectante, sendo prescindível o início de medicação anticonvulsivante.","C":"Prescrever diazepam 10mg, via intravenosa, como primeira escolha medicamentosa.","D":"Iniciar anticonvulsivante, considerando o uso do contraceptivo oral na escolha do fármaco."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-340707","number":"340707","sourceNumber":"340707","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"A neuropatia periférica diabética dolorosa NPDD caracteriza-se por dor neuropática na\nárea corpórea afetada pela neuropatia, que piora com repouso, durante o sono, e melhora com\natividade física. Sobre isso, pode-se afirmar que:","options":{"A":"A dor crônica não traz impacto negativo na qualidade de vida, no humor e na funcionalidade de\npessoas com diabetes, causando comorbidades\ngraves, como insônia, ansiedade, depressão e\nperda de funcionalidade.","B":"A dor crônica traz impacto negativo na qualidade de vida, no humor e na funcionalidade de\npessoas com diabetes, causando comorbidades\ngraves, como insônia, ansiedade, depressão e\nnunca perda de funcionalidade.","C":"A dor crônica traz impacto negativo na qualidade de vida, no humor e na funcionalidade de\npessoas com diabetes, causando comorbidades\ngraves, como insônia, ansiedade, depressão e\nperda de funcionalidade.","D":"A dor crônica traz impacto negativo na qualidade de vida, no humor e na funcionalidade de\npessoas sem diabetes, causando comorbidades\ngraves, como insônia, ansiedade, depressão e\nperda de funcionalidade."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-340713","number":"340713","sourceNumber":"340713","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Dos agentes etiológicos apresentados abaixo, qual não está associado à Síndrome de\nGuillain-Barré?","options":{"A":"C. jejuni.","B":"Zika vírus.","C":"Rickettsia rickettsii.","D":"M. pneumoniae."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-340725","number":"340725","sourceNumber":"340725","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Sobre as características da Síndrome de Guillain-Barré, assinale a alternativa correta.","options":{"A":"Líquor com redução do número de proteínas.","B":"Déficit motor assimétrico de acometimento crônico.","C":"Déficit motor progressivo, geralmente ascendente, de instalação aguda.","D":"Déficit motor assimétrico que se inicia pelos membros superiores."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-330319","number":"330319","sourceNumber":"330319","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Lactente de 3 meses, sexo feminino, gestação sem intercorrências, pais sem\nconsanguinidade apresenta as queixas a seguir:\nchoro fraco, dispneia ao mamar, é mais molinho e\nquando comparando com o irmão mais velho percebe-se que o pescoço está sem sustento. No\nexame físico chama a atenção a fasciculação de língua, hiporreflexia aquileu, patelar e bicipital,\nrespiração com esforço abdominal e sensório preservado. Diante do caso apresentado, assinale a\nalternativa que apresenta o PROVÁVEL diagnóstico da criança.","options":{"A":"Síndrome de Prader Willi.","B":"Amiotrofia espinhal tipo I.","C":"Paralisia cerebral.","D":"Hipotonia fisiológica do lactente."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-311273","number":"311273","sourceNumber":"311273","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Considerando a Panencefalite Esclerosante Subaguda do Sarampo, assinale a\nalternativa correta.","options":{"A":"Tem aumentado suas taxas desde a introdução da vacina tríplice viral.","B":"É uma complicação tardia benigna da infecção pelo sarampo.","C":"O risco de desenvolver panencefalite esclerosante subaguda é maior se a criança tiver infecção\npelo sarampo antes dos 2 anos de idade.","D":"Ocorre em cada 1000 casos de sarampo."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-301024","number":"301024","sourceNumber":"301024","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Lactente de 4 meses de vida, sexo masculino, gestação sem intercorrências, pais\nprimos de primeiro grau, comparecem à\nconsulta pediátrica devido a atraso do desenvolvimento,\ncaracterizado por não sustento cervical, movimentação ativa pobre, porém mantém excelente\ncontato fixando e seguindo com o olhar para todas as direções, sorriso social e esboço de\nbalbucios. No exame físico, chama a atenção a fasciculação de língua, hiporreflexia aquileu, patelar\ne biciptal, respiração com esforço abdominal e sensório preservado. Diante do caso descrito, qual é\na conduta adequada?","options":{"A":"Orientar fisioterapia e observar a evolução do paciente.","B":"Realizar tomografia de crânio.","C":"Pesquisar erros inatos do metabolismo.","D":"Solicitar imediatamente exame para Amiotrofia Espinhal (AME)."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-301025","number":"301025","sourceNumber":"301025","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Paciente, 14 anos de idade, sexo feminino, sem comorbidades, excelente rendimento\nescolar, pais sem consanguinidade, evoluiu\ncom formigamento em membros inferiores, que\nprogride no dia subsequente com fraqueza de membros inferiores a impedindo de deambular. Mãe\nrelata que filha há 21 dias teve Covid-19 confirmado por RT-PCR, mas que já estava assintomática\nhá mais de 10 dias.Ao exame físico, a paciente apresentava arreflexia aquileu, patelar e bicipital,\nnervos cranianos preservados e sinais e sintomas de disautonomia (taquicardia, picos hipertensivos\ne sudorese). Realizada propedêutica que mostrou hemograma sem alterações, líquor: células: 01\ncel/mm³ , hemácias: 05 hem/mm³ , glicose: 67 mg/dL e proteína: 85 mg/dL. Diante do caso descrito,\nqual é a melhor hipótese diagnóstica?","options":{"A":"Encefalomielite disseminada aguda (ADEM).","B":"Encefalite autoimune anti-NMDA.","C":"Mielite transversa.","D":"Guillain Barre."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-259391","number":"259391","sourceNumber":"259391","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Mulher de 72 anos, comparece à consulta médica com o seguinte relato: há cerca de 2\nmeses, com quadro de dispneia, incialmente em grau II (mmRc), atualmente em grau IV (mmrC)\ncom profunda limitação às atividades do cotidiano. Refere incapacidade para pentear cabelo e uso\nde apoio para levantar-se de cadeiras, além de mudança de cor em pontas digitais de acordo com\na temperatura do ambiente. Ao exame físico nota-se: pápulas eritematosas em superfícies dorsais\ndas articulações metacarpofalangeanas e interfalangeanas simétricas. Mãos com aspecto\nhiperceratótico, com fissuras na região palmar e superfície lateral dos dedos. Joelhos com\nhiperemia local e aumento do volume, com limitação a extensão e flexão. Ausculta respiratória com\npresença de crepitações meso-teleinspiratórias em terços médio e inferior bilateralmente, com\nsaturimetria em ar ambiente: 87%, Frequência respiratória: 28irpm, Pressão arterial: 130/80mmhg,\nFrequência cardíaca: 90bpm. A paciente encontrava-se com exames laboratoriais recentes\npreviamente realizados, com os seguintes resultados: Creatinofosfoquinase: 3000 Ui/L (VR: até 500\nUI/L), HB:10,0 g/dL, Ht: 30% Leucograma: 8000 cels/mm3 ( 80% neutrófilos, 15% linfócitos, 3%\neosinófilos, 2% macrófagos) plaquetas: 100.000 uréia: 60mg/dl creatinina: 1,4mg/dL FAN: 1/640\n(padrão citoplasmático pontilhado fino), VHS: 80 mm. Tomografia de tórax: múltiplas consolidações\nbilaterais e áreas em vidro fosco esparsas. Diante do contexto clínico acima, qual exame\ncomplementar poderia contribuir para o diagnóstico definitivo da condição?","options":{"A":"Ecocardiograma transtorácico.","B":"Eletroneuromiografia de membros superiores e inferiores.","C":"Espirometria pré e pós broncodilatador.","D":"Radiografia de mãos e punhos."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-266644","number":"266644","sourceNumber":"266644","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"A convulsão febril é a causa mais comum de convulsão na infância. Em relação às\nconvulsões na infância, assinale a alternativa INCORRETA:","options":{"A":"O status convulsivo é a persistência de uma crise convulsiva ou a sucessão delas sem\nrecuperação da consciência, por mais de 30 minutos.","B":"O eletroencefalograma é o exame mais importante no diagnóstico e para diferenciação do tipo\nde epilepsia.","C":"O exame do líquor está indicado em todo quadro de convulsão.","D":"A escolha da droga anticonvulsivante dependerá de uma série de fatores como idade, alterações\nno EEG, tipo de crise, etc."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-244508","number":"244508","sourceNumber":"244508","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"A incidência da miastenia gravis - MG varia de 1-9 por milhão de habitantes, e a\nprevalência de 25-142 por milhão de habitantes, havendo um discreto predomínio em mulheres. A\nidade de início é bimodal, sendo os picos de ocorrência em torno de 20-34 anos para mulheres e\n70-75 anos para homens. O item errado é:","options":{"A":"A miastenia gravis (MG) é uma doença autoimune da porção pós-sináptica da junção\nneuromuscular caracterizada por fraqueza flutuante\nque melhora com o repouso e piora com o\nexercício, infecções, menstruação, ansiedade, estresse emocional e gravidez.","B":"A fraqueza pode ser limitada a grupos musculares específicos (músculos oculares, faciais,\nbulbares), mas nunca generalizada.","C":"A crise miastênica é definida por insuficiência respiratória associada à fraqueza muscular\ngrave.","D":"Na maioria dos pacientes, a MG é causada por anticorpos contra receptores de acetilcolina\n(ACh)."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-244509","number":"244509","sourceNumber":"244509","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Analisando as anormalidades de musculatura bulbar e facial associadas à Miastenia\nGravis - MG, somente não podemos aceitar que:","options":{"A":"Regurgitação nasal de líquidos ou sólidos pode resultar do acometimento dos músculos\nfaríngeos e palatais.","B":"Fraqueza concomitante de língua, disartria e voz anasalada podem sobrevir.","C":"Fraqueza facial pode ser detectada pedindo ao paciente que feche os olhos contra resistência.\n\nEventualmente, pode apresentar um \"\"sorriso canino\"\" devido à falência da musculatura do canto\nda boca e à retração labial.","D":"Todos os pacientes apresentam dificuldade de mastigação e deglutição, podendo haver\ninclusive emagrecimento associado."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-244510","number":"244510","sourceNumber":"244510","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Sobre anormalidades respiratórias e musculares associadas à Miastenia Gravis - MG,\nsomente mostra erro o item:","options":{"A":"Ocasionalmente os pacientes podem apresentar-se com insuficiência respiratória por fraqueza\ndiafragmática e de músculos respiratórios assessórios, não configurando a crise miastênica.","B":"Uma maneira eficaz de avaliar disfunção respiratória à beira do leito é solicitar aos pacientes\nque\ncontem em voz alta até 20 após uma inspiração máxima. Caso seja incapaz de realizar tal tarefa\nsem interromper para respirar novamente, sua capacidade vital forçada pode ser estimada em\nmenos de um litro.","C":"Demais partes do exame neurológico como a sensibilidade e reflexos usualmente são normais.","D":"Envolvimento apendicular com fraqueza muscular dos membros e do pescoço é encontrado em\naté 30% dos pacientes, sendo que em apenas 3% destes o predomínio é distal."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-239820","number":"239820","sourceNumber":"239820","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Paciente de 40 anos, sexo feminino, comparece ao pronto atendimento queixando-se\nde fraqueza nas pernas. Relata que ontem, ao subir\nescadas, notou que seu pé direito estava\n\n?caído?. Mais tarde percebeu que o pé esquerdo também estava fraco. Hoje, pela manhã, não\nconseguiu se levantar, pois não conseguia\nfletir o quadril. Nega febre, dor ou trauma recente.\nRelata que apresentou quadro de diarreia há 2 semanas. Exame de sensibilidade de membros\ninferiores sem alterações. Exame de força motora e reflexos osteotendíneos descrito abaixo: força\nmotora de membros inferiores pela escala MRC (MID/MIE); flexão do quadril 1/1; extensão do\njoelho 0/0; flexão e extensão plantar 0/0; reflexos osteotendíneos de membros inferiores (MID/MIE):\npatelar ausente/ausente; aquileu ausente/ausente; reflexo cutâneo-plantar: ausente/ausente. Diante\ndo quadro clínico exposto acima, assinale o diagnóstico mais provável:","options":{"A":"Paralisia espástica tropical.","B":"Miastenia gravis.","C":"Esclerose múltipla.","D":"Síndrome de Guillain-Barré."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-239826","number":"239826","sourceNumber":"239826","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Paciente de 22 anos com diagnóstico de epilepsia desde os 18 anos. Ficou sem utilizar\nsuas medicações nos últimos dois dias. Trazido ao pronto atendimento por familiares que relatam\nque paciente apresentou em casa duas crises tônico-clônica generalizadas, com duração de cerca\nde 3 minutos, sem recobrar a consciência entre elas. No caminho para o pronto atendimento\napresentou mais duas crises semelhantes e, nesse momento está apresentando uma crise\n\ntônico-clônica generalizada que já duram 6 minutos. Assinale a alternativa que possui a conduta\nmais adequada:","options":{"A":"Administrar fenitoína EV até 3 doses com intervalo de 5-10 minutos. Caso não responda ao\ntratamento, administrar benzodiazepínico parenteral.","B":"Administrar benzodiazepínico parenteral (repetir a cada 5-10 minutos se necessário) e,\nconcomitantemente, fenitoína EV.","C":"Administrar benzodiazepínico parenteral (repetir a cada 5-10 minutos se necessário) até que as\ncrises acabem. Somente após a resolução das crises, administrar fenitoína EV.","D":"Administrar benzodiazepínico parenteral (repetir a cada 5-10 minutos se necessário). Caso não\nresponda ao tratamento, administrar fenitoína EV."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-238764","number":"238764","sourceNumber":"238764","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"No que se refere às Convulsões Febris na infância, marque a alternativa CORRETA:","options":{"A":"O Eletroencefalograma (EEG) deve ser realizado rotineiramente, uma vez que contribui para o\ndiagnóstico e tratamento.","B":"A profilaxia secundária é indicada no caso de crise focal simples, com o uso de\nbenzodiazepínicos durante os episódios febris.","C":"A maioria das crianças já chega ao pronto socorro no período pós-ictal. Nos casos em que a\ncriança está em convulsão, o tratamento agudo é igual a qualquer crise epiléptica, independente de\nsua etiologia.","D":"A crise febril é definida como uma crise epiléptica que ocorre entre 1 mês e 5 anos de idade,\nassociada a doença febril, não causada por uma infecção do sistema nervoso central."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-238650","number":"238650","sourceNumber":"238650","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Considere o caso clínico a seguir. Criança do sexo masculino, 9 anos de idade, dá\nentrada em pronto-socorro com queixa de dor\nnas pernas e perda de força nelas. Relata que, no\ndia anterior, sentiu um formigamento nos membros inferiores. Mãe relata que há 15 dias paciente\nteve um quadro de pneumonia atípica tratada com claritromicina, sendo previamente uma criança\nhígida, sem intercorrências na gestação, parto e desenvolvimento. Ao exame físico, tinha força\nreduzida globalmente, pior em membros inferiores, ausência de reflexos osteotendíneos, nervos\ncranianos sem sinais de acometimento e restante de exame sem alterações dignas de nota.\n\nRealizado liquor que mostrou uma célula por mm³, 3 hemácias por mm³, glicose de 75 mg/dl e\nproteína 120 mg/dl, hemograma e íons sem alterações. Diante do exposto, qual é o diagnóstico\nmais provável?","options":{"A":"Síndrome de Guillain-Barré.","B":"Mielite transversa.","C":"ADEM (encefalomielite disseminada aguda).","D":"Neuromielite óptica (doença de Devic)."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-255031","number":"255031","sourceNumber":"255031","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"I.B.G, 1 ano e 3 meses, previamente hígida, é levada ao pronto atendimento pela mãe,\ncom história de ter apresentado crise convulsiva tônico-clônico generalizada, com duração de 3\nminutos, ficando sonolenta logo após a crise, que cessou espontaneamente a caminho do hospital.\nMãe conta que criança apresentava tosse e coriza há 1 dia, sem desconforto respiratório, em bom\nestado geral. Ao exame físico admissional: REG, corada, hidratada, acianótica, anictérica, febril\n(temp:38,9ºC), sem edemas. Ausência de irritabilidade, ou rigidez de nuca. Sonolenta ao exame,\nporém acordava à manipulação. Otoscopia: membrana timpânica translúcida bilateralmente.\n\nOroscopia: leve hiperemia, sem exsudato ou petéquias em pálato. Sem lesões de pele. ACV:\nBulhas Rítmicas e normofonéticas em 2 tempos, sem sopros, FC: 130bpm. AR: Murmúrios\nVesiculares presentes bilateralmente, sem ruídos adventícios, eupneica, sat:98% em AA, FR\n\n:30irpm. Ausência de esforço respiratório. Abdômen: inocente. MM: Sem alterações; Na\ninvestigação diagnóstica da crise convulsiva, quais\nexames seriam necessários para este caso?","options":{"A":"Mapeamento cerebral.","B":"Tomografia de crânio e eletroencefalograma.","C":"Eletroencefalograma.","D":"Nenhum exame é necessário.","E":"Ressonância Magnética."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-239902","number":"239902","sourceNumber":"239902","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Homem, 77 anos, hipertenso e diabético, levado ao atendimento de urgência devido\ncrise convulsiva presenciada em domicilio. Sem\nhistoria previa de crises convulsivas. Em uso\nregular de Losartana, Hidroclorotiazida, Metformina e Glibenclamida. Ao ser avaliado, já em período\npos-ictal, estabilidade hemodinâmica e dados vitais normais, sem déficits focais. A primeira\nhipótese diagnostica para causa do evento:","options":{"A":"AVC","B":"Lesão expansiva intracraniana","C":"Hipotensão","D":"Hipoglicemia"},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-184566","number":"184566","sourceNumber":"184566","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Pacientes com dor neuropática se beneficiam do tratamento com inibidores da\nreceptação de serotonina e noradrenalina\ncomo os antidepressivos tricíclicos. Os opióides não\napresentam uma eficácia satisfatória no controle da dor neuropática, exceto dois deles que são\nconsiderados ?opióides atípicos? por apresentarem efeitos tanto nos receptores NMDA (Metadona)\nou por apresentar efeito na inibição da receptação de serotonina e noradrenalina exercendo efeito\nanalgésico sinérgico no controle da dor neuropática. Dos opióides abaixo qual deles exerce efeito\nsinérgico na dor neuropática por inibição da receptação de noradrenalina e serotonina?","options":{"A":"Morfina.","B":"Oxicodona.","C":"Tramadol.","D":"Pregabalina."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-179076","number":"179076","sourceNumber":"179076","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Lactente, 6 meses, é trazido ao serviço de emergência com história de febre há 24\nhoras e crise convulsiva, inédita,\ngeneralizada tônico-clônica, de curta duração, que cessou\nespontaneamente. Ao exame físico, a criança estava febril e com o exame neurológico normal. O\nacompanhante da criança não soube informar sobre a situação atual do calendário vacinal da\ncriança. Com base nessas informações, a conduta mais indicada para planejamento diagnóstico é:","options":{"A":"Coleta de líquor para análise laboratorial","B":"Tomografia computadorizada de crânio","C":"Pesquisa de erros inatos do metabolismo","D":"Eletroencefalograma"},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-178273","number":"178273","sourceNumber":"178273","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Tiago, 6 meses de idade é levado ao pronto-socorro com história de ter apresentado\ncrise generalizada tônico-clônica há 1 hora, com\nduração de 3 minutos. Ao exame físico,\n\nencontra-se febril, muito sonolento, sem sinais meníngeos, e o restante do exame sem alterações.\nEm relação ao caso, assinale a alternativa\nINCORRETA.","options":{"A":"O paciente deve receber, imediatamente, fenitoína na dose de 15 mg/kg, pelo risco de\napresentar nova crise.","B":"Não é necessário introduzir medicação anticonvulsivante nesse momento, por se tratar de\ncrise única e de curta duração.","C":"Devem-se checar os antecedentes familiares para convulsão febril e epilepsia.","D":"Apesar de o diagnóstico mais provável ser de convulsão febril benigna, deve-se cogitar nesse\ncaso a coleta de líquor.","E":"O eletroencefalograma tem valor prático, pois define o diagnóstico e a probabilidade de\nrecorrências."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-184567","number":"184567","sourceNumber":"184567","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Lactente do sexo masculino de 7 meses, apresentava desenvolvimento\nneuropsicomotor adequado até que, há mais ou\nmenos seis dias, iniciou quadro de alteração do\ncomportamento, caracterizado por períodos de irritabilidade, seguidos de sonolência. Quando está\nacordado, apresenta movimentos frequentes e espontâneos, que a mãe descreve como ?sustos?,\nseguidos de flexão dos braços e queda da cabeça. Ao exame f?sico: hipotonia global e regressão\ndo desenvolvimento neuropsicomotor. O achado eletroencefalográfico que confirma o diagnóstico\né:","options":{"A":"Hipssaritmia.","B":"Isoeletricidade.","C":"Traçado normal.","D":"Descargas do tipo ponta-onda lenta contínua."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-181290","number":"181290","sourceNumber":"181290","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Em relação às convulsões, é incorreto afirmar:","options":{"A":"As crises atônicas são caracterizadas por contrações e relaxamentos musculares rítmicos.","B":"A síndrome de Dravet é considerada o espectro fenotípico mais grave da convulsão febril plus.","C":"As convulsões sintomáticas agudas são secundárias a um problema agudo que afeta a\nexcitabilidade cerebral, como desequilíbrio eletrolítico ou meningite.","D":"Nas crises generalizadas, as primeiras alterações clínicas e EEG indicam envolvimento\nsincrônico de ambos os hemisférios cerebrais."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-182028","number":"182028","sourceNumber":"182028","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Mulher 20 anos procura atendimento com queixa de dificuldade em deglutição, diplopia\nintermitente, fraqueza muscular generalizada e ptose palpebral de predomínio vespertino. Assinale\na alternativa que descreve corretamente a principal hipótese diagnóstica e o exame diagnóstico\nmais adequado, respectivamente:","options":{"A":"Miastenia gravis ? anticorpo anti citoplasma de neutrófilo.","B":"Esclerose lateral amiotrófica ? eletroneuromiografia.","C":"Miastenia gravis ? anticorpo anti receptor de acetilcolina.","D":"Paralisia do terceiro par craniano (oculomotor) ? ressonância de encéfalo."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-181963","number":"181963","sourceNumber":"181963","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"O diagnóstico de epilepsia é realizado quando há:","options":{"A":"Crises epilépticas prolongadas, duração maior que 5 a 10 minutos, contínuas e intermitentes.","B":"Crises curtas, menos de 5 minutos, recuperação completa, sem déficits ou doenças associadas.","C":"Duas ou mais crises epilépticas com intervalo de pelo menos 1 mês.","D":"Duas ou mais crises epilépticas com intervalo maior do que 24 horas."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-153129","number":"153129","sourceNumber":"153129","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Paciente A: mulher, 32 anos, com história de três episódios de déficits sensitivos e\nmotores, separados entre si pelo período\naproximado de três semanas, com duração de dois dias e\npresença de sequela residual, acometendo sequencialmente todo o dimídio direito, mão esquerda e\nhemiface inferior esquerda nos últimos seis meses. Refere sensação de choque na parte posterior\ndo dorso e dos membros inferiores ao flexionar o pescoço. Há três dias vem apresentando\ndiminuição da acuidade visual em olho direito, associado a dor retro-ocular do mesmo lado.\n\nPaciente B: homem 59 anos, com paraparesia ascendente e progressiva em MMII há dois meses,\nsem déficits sensitivos, acometendo\nsequencialmente o tronco e os MMSS. Não havia\ncomprometimento de pares cranianos ou musculatura cervical. Paciente C: Homem, 30 anos, com\nparaplegia de início súbito há três dias, associado a anestesia para todas as modalidades\nsensitivas, bilateralmente até o nível do umbigo. Verificou-se também a presença de retenção\nurinária indolor. Assinale a alternativa que mostra os exames que deveriam ser solicitados\ninicialmente nos pacientes A, B e C, respectivamente.","options":{"A":"Ressonância Nuclear Magnética (RNM) de encéfalo, eletroneuromiografia, RNM de medula.","B":"TC contrastada de encéfalo, RNM de medula, TC contrastada de medula.","C":"RNM de encéfalo, RNM de medula, pesquisa de bandas oligoclonais no líquor.","D":"Pesquisa de bandas oligoclonais no líquor, eletroneuromiografia, Eletroneuromiografia.","E":"Potenciais visuais evocados, eletroneuromiografia, RNM de encéfalo"},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-155241","number":"155241","sourceNumber":"155241","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Sobre a escolha de drogas antiepilépticas na infância, é CORRETO afirmar que:","options":{"A":"Nas crises generalizadas tônico-clônicas, o topiramato e a lamotrigina estão entre as primeiras\nescolhas de tratamento.","B":"Nas crises parciais, o fenobarbital e lamotrigina são de primeira escolha.","C":"Para espasmos infantis, a primeira escolha é o ácido valpróico.","D":"Nas crises generalizadas de ausência, o ácido valpróico é medicamento de primeira linha."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-158168","number":"158168","sourceNumber":"158168","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"O tratamento da crise convulsiva tem como objetivo prevenir possíveis sequelas\nneurológicas e complicações sistêmicas. Sobre o tratamento da crise convulsiva, assinale a\nalternativa INCORRETA.","options":{"A":"Deve-se receitar o etomidato.","B":"Deve-se oferecer oxigênio por cateter nasal.","C":"Deve-se manter permeabilidade das vias aéreas.","D":"Deve-se receitar diazepam ou midazolam."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-129276","number":"129276","sourceNumber":"129276","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"A respeito da síndrome de Guillain-Barré, é INCORRETO afirmar que:","options":{"A":"O liquor pode estar normal na primeira semana de evolução.","B":"O liquor pode mostrar aumento de proteína.","C":"É caracterizada por paralisia flácida.","D":"Os reflexos profundos encontram-se normais."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-131776","number":"131776","sourceNumber":"131776","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Dona Maria Tereza está preocupada, pois o cachorro de sua vizinha, hígido, arranhou\nhoje o seu pé. Você observa ferimento\núnico, com sangramento em região plantar do pé direito.\n\nPassados quatro dias do ocorrido, o cachorro que arranhou Dona Maria Tereza desapareceu. Qual\na conduta CORRETA diante desta situação?","options":{"A":"Não há necessidade de mudanças e o esquema profilático deve ser interrompido.","B":"Aplicar uma dose de vacina e interromper o esquema profilático.","C":"Aplicar mais três doses de vacina, sem aplicação de soro antirrábico.","D":"Aplicar mais três doses de vacina e soro antirrábico.","E":"Aplicar apenas soro antirrábico."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-135622","number":"135622","sourceNumber":"135622","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Uma unidade de saúde da família deve ser responsável pelo cadastro e\nacompanhamento de seus usuários. Ao realizar\numa visita domiciliar a uma paciente idosa, obesa,\ndiabética restrita ao lar e com dificuldade para seguir as orientações da equipe porque mora\nsozinha e não enxerga bem, você deverá solicitar:","options":{"A":"Ajuda ao Conselho do Idoso, para que a mesma seja acompanhada por recursos sociais do\nbairro, envolver toda a equipe no plano de cuidados.","B":"A presença da família para ajudar no plano de cuidados denunciando ao Ministério Publico por\nnegligência ou maus tratos, já que a senhora é incapaz.","C":"Referência para atenção secundária até estabilização do quadro e internação numa instituição\nde longa permanência por causa das dificuldades\npercebidas.","D":"Referência para endocrinologista para tratamento medicamentoso, ao fisioterapeuta para\nmelhorar a mobilidade e ao nutricionista para orientar dieta."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-113261","number":"113261","sourceNumber":"113261","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Com a redução da taxa de fecundidade e da mortalidade e com o aumento da\nexpectativa de vida, o processo de\nenvelhecimento da população se tornou cada vez mais evidente\nna sociedade. Considerando a avaliação funcional da pessoa idosa, assinale a alternativa\nINCORRETA:","options":{"A":"A avaliação funcional busca verificar, de forma sistematizada, em que nível as doenças ou\nagravos impedem o desempenho, de forma autônoma e independente, das atividades da vida\ndiária das pessoas idosas.","B":"A caderneta de saúde da pessoa idosa pode ser considerada um instrumento valioso para a\nidentificação de pessoas idosas frágeis ou em risco de fragilização, podendo ser utilizada para\navaliação de funcionalidade da pessoa idosa.","C":"A avaliação funcional tem como meta a independência e a autonomia, pelo maior tempo\npossível, da pessoa idosa.","D":"A presença de declínios na funcionalidade da pessoa idosa pode sugerir um processo natural de\nenvelhecimento.","E":"Quando se avalia a funcionalidade da pessoa idosa é necessário diferenciar desempenho e\ncapacidade funcional. Desempenho avalia o que o idoso realmente faz no seu dia a dia e\ncapacidade funcional avalia o potencial que a pessoa idosa tem para realizar a atividade."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-105817","number":"105817","sourceNumber":"105817","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Ao brincar com um macaco que se encontra em cativeiro há mais ou menos dois anos,\nLucas, 8 anos, sofreu mordedura única e superficial no dedo. Segundo o esquema de profilaxia da\nRaiva Humana, assinale a conduta CORRETA:","options":{"A":"observar o animal por dez dias","B":"Iniciar tratamento com duas doses, uma no dia 0 e outra no dia 3 e observar o animal preso por\n10 dias","C":"Aplicar cinco doses da vacina e não observar o animal","D":"Aplicar cinco doses da vacina e soro e não observar o animal","E":"Aplicar cinco doses da vacina e não aplicar o soro se o animal morrer, desaparecer ou se tornar\nraivoso durante os 10 dias de observação."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-105386","number":"105386","sourceNumber":"105386","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Um cão doméstico, sem suspeita de raiva, causa um ferimento superficial, único e\npouco extenso no tórax de seu dono, um homem de\n21 anos. O cão vive em seu quintal, sempre\nfechado, e o homem não possui nenhuma comorbidade. Em relação à melhor conduta preconizada\npelo Ministério da Saúde sobre o esquema para profilaxia da raiva humana com vacina de cultivo\ncelular, assinale a alternativa CORRETA:","options":{"A":"Lavar com água e sabão; iniciar esquema profilático com 2 doses de vacina e observar o animal\ndurante 5 dias, para avaliar próximas condutas.","B":"Iniciar esquema profilático com 3 doses de vacina e observar o animal durante o período de 10\ndoses, a fim de decidir as próximas medidas.","C":"Além de lavar o ferimento com água e sabão, o animal deverá ser observado durante 10 dias\napós a exposição; se o animal permanecer\nsadio no período de observação, pode-se encerrar o\ncaso; se o animal morrer, desaparecer ou se tornar raivoso, administrar 5 doses de vacina (dias 0,\n3, 7, 14 e 28).","D":"Limpar a ferida com degermante; observar o animal durante 10 dias após a exposição; iniciar o\nesquema profilático com 3 doses de vacina e aguardar evolução do paciente e do animal."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-109947","number":"109947","sourceNumber":"109947","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"As grandes Síndromes Geriátricas têm como atributos a complexidade terapêutica,\nmúltipla etiologia, não constituir risco de vida\niminente e comprometer severamente a qualidade de\nvida dos portadores e, muitas vezes, os familiares. Essas síndromes podem-se apresentar isoladas\nou em associação e implica em grande dano funcional para o indivíduo, impedindo o\ndesenvolvimento das atividades de vida diária. Não se enquadra no conceito de síndrome\ngeriátrica:","options":{"A":"Insuficiência cardíaca.","B":"Incontinência urinária e fecal.","C":"Instabilidade postural.","D":"Insuficiência cerebral."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-109954","number":"109954","sourceNumber":"109954","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"A avaliação multidimensional do idoso é realizada através da revisão dos sistemas\nfisiológicos principais, divididos em: avaliação\ndas atividades de vida diária, mobilidade, cognição,\nhumor e comunicação. De acordo com a Linha Guia de Atenção à Saúde do Idoso (2006) são\nconsiderados instrumentos de avaliação de AVDs (Atividades de Vida Diária) básicas e\ninstrumentais:","options":{"A":"Índice de Katz e escala de Lawton-Brody.","B":"Mini-mental de Folstein e teste do relógio.","C":"Tabela de Snellen e escala de Pfeffer.","D":"Clinical Dementia Rating Scale (CDR) e Inventário Neuropsiquiátrico (NPI)."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-109889","number":"109889","sourceNumber":"109889","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"A doença de Alzheimer é a mais frequente doença neurodegenerativa. Trata-se de uma\ndoença que acarreta alterações do\nfuncionamento cognitivo (memória, linguagem, planejamento,\nhabilidades visuais-espaciais) e muitas vezes também do comportamento (apatia, agitação,\nagressividade, delírios), que limitam progressivamente a pessoa nas suas atividades da vida diária.\nDe acordo com o Protocolo Clínico e Diretrizes Terapêuticas da Doença de Alzheimer aprovado\npela Portaria Nº 1.298, de 21 de Novembro de 2013, para o tratamento da DA, os fármacos que\npodem melhorar os sintomas primariamente nos domínios cognitivos e na função global, sendo\nindicados em demência leve a moderada são:","options":{"A":"Levodopa/Carbidopa, Pramipexol e Amantadina.","B":"Mirtazapina, Memantina e Olanzapina.","C":"Donepezila, Galantamina e Rivastigmina.","D":"Ginkgo biloba, Suplementação de vitamina D e Risperidona."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-103100","number":"103100","sourceNumber":"103100","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Na síndrome de Munchausen por procuração, podemos afirmar, EXCETO:","options":{"A":"Os sintomas são fabulados ou produzidos na criança para que o profissional da saúde, em\nespecial o pediatra, maltrate a criança com exames invasivos, internações e tratamentos\ndesnecessários.","B":"O agressor tem a necessidade constante de desafiar o saber da equipe médica.","C":"A vítima é excluída da vida infantil, privada do lazer e está sempre sob ação de seu agressor.","D":"A vítima apresenta um comportamento inconformado."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-120767","number":"120767","sourceNumber":"120767","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"A Raiva Humana é uma doença potencialmente fatal, poucos casos de\nsobreviventes foram registrados na literatura\nmédica até o momento. A melhor forma de\nprevenção dos casos consiste na profilaxia da doença, para as pessoas com alto risco de\nexposição ao vírus da Raiva ou para as pessoas expostas ao vírus, através de acidentes com\nanimais. Ao ser procurado no ambulatório por um médico veterinário, que foi mordido há uma hora\npor um bovino, na mão direita, ferimento múltiplo e com sangramento discreto, e cujo animal\nencontra-se sob suspeita de Raiva, em observação no Hospital Veterinário. O veterinário conta\nque fez profilaxia pré-exposição para raiva há um ano atrás, esquema completo, com sorologia\nmaior que 0,5 UI. Qual a conduta recomendada para este caso, segundo as Normas para\nProfilaxia da Raiva preconizadas pelo Ministério da Saúde?","options":{"A":"Soro-vacinação, com cinco doses de vacina antirrábica de cultivo celular e soro\nheterólogo aplicado ao redor da mordida.","B":"Vacinação, com cinco doses da vacina antirrábica e dosagem de anticorpos para raiva\nquinze dias após.","C":"Sacrifício do bovino suspeito e análise do cérebro do animal para Raiva. Aguardar o\nresultado do exame do bovino para indicar novas doses de vacina antirrábica.","D":"Realizar duas doses de vacina antirrábica com intervalo de três dias. Não indicar soro\nantirrábico. Realizar sorologia 14 dias após a última dose de vacina.","E":"Vacinar o bovino com uma dose da vacina\nantirrábica animal."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-120770","number":"120770","sourceNumber":"120770","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Estagiário do serviço de Pediatria procurou o serviço da vigilância epidemiológica para\ninformar que ontem pela manhã, quando se levantou, encontrou um bicho no chão do seu\nquarto que ele achava que era um morcego. Pegou o animal dentro de um saco e jogou no\nlixo. Porém percebeu que houve uma mordedura única em dedo indicador direito. Qual a\nconduta indicada para o caso:","options":{"A":"Não é necessário vacina nem soro anti-rábico.","B":"Iniciar esquema vacinal de 02 doses de antirrábica com intervalos de 0 e 3 dias.","C":"Iniciar esquema vacinal de 05 doses de antirrábica com intervalos de 0, 3, 7, 14 e 28 dias","D":"Administrar Soro anti-rábico e iniciar esquema de vacinação antirrábica 05 doses","E":"Administrar apenas soro anti-rábido e\ndispensar a vacinação antirrábica."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-80904","number":"80904","sourceNumber":"80904","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Joselino, 67 anos, comparece pela primeira vez em uma unidade de saúde da família,\nacompanhado pela sua filha, para consulta, apresentando múltiplas queixas. Considerando as\ncaracterísticas do trabalho do médico de família, assinale a alternativa INCORRETA:","options":{"A":"O idoso pode ser portador de múltiplas doenças, o que não deve ser confundido com a\ncaracterística poliqueixosa atribuída a essa faixa etária.","B":"A Avaliação Geriátrica Ampla (AGA), por si só, é suficiente para dar diagnósticos, o que\nfacilita o\ntrabalho do médico de família.","C":"O médico deve priorizar as informações do paciente, dirigindo-se ao acompanhante somente se\nnecessário.","D":"Além da escuta qualificada, a utilização da avaliação multidimensional do idoso, ou AGA, deve\nser aplicada nessa situação.","E":"A AGA é um instrumento de rastreamento, que pode identificar problemas de saúde\ncondicionantes de declínio funcional."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-80805","number":"80805","sourceNumber":"80805","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Cristina, na pré-escola, ao colocar a mão em um oco de árvore, foi mordida no dedo por\num morcego. O animal foi levado para uma clínica e o técnico referiu que aquele morcego era de\numa espécie que só comia frutas. Após lavar o ferimento com água e sabão, a criança foi levada ao\nserviço de profilaxia da raiva para avaliação. Assinale a conduta CORRETA:","options":{"A":"Observar o animal durante 10 dias após a exposição. Se o animal permanecer sadio no período\nde observação, encerrar o caso. Se o animal\nmorrer, desaparecer ou se tornar raivoso, administrar\n5 doses de vacina (dias 0, 3, 7, 14 e 28).","B":"Iniciar tratamento com duas doses de vacina\n\n(dias 0 e 3). Observar o animal durante 10 dias após exposição. Se o animal permanecer sadio no\nperíodo de observação, encerrar o caso. Se o animal morrer, desaparecer ou se tornar raivoso,\ncontinuar o tratamento, administrando o soro e completando o esquema até 5 (cinco) doses. Aplicar\numa dose entre o 7º e o 10º dia e uma dose nos dias 14 e 28.","C":"Iniciar imediatamente o tratamento com 5 (cinco) doses de vacina administradas nos dias 0, 3, 7,\n14 e 28.","D":"Iniciar imediatamente o esquema profilático com soro e 5 (cinco) doses de vacina nos dias 0, 3,\n7, 14 e 28.","E":"Iniciar tratamento com duas doses de vacina (dias 0 e 3). Observar o animal durante 10 dias\napós a exposição. Se o animal permanecer sadio no período de observação, suspender o\ntratamento e encerrar o caso. Se o animal morrer, desaparecer ou se tornar raivoso, completar o\nesquema até 5 (cinco) doses. Aplicar uma dose entre o 7º e o 10º dia e uma dose nos dias 14 e\n28."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-80766","number":"80766","sourceNumber":"80766","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Você recebe em seu consultório um casal fumante procurando por ajuda para parar de\nfumar. Ele tem 42 anos e é portador de esquizofrenia, com tratamento regular e estável há 24\nmeses. Refere que fuma há cerca de 20 anos e atualmente consome cerca de 40 cigarros por dia.\nA esposa tem 35 anos e foi submetida há cerca de 6 meses a angioplastia com colocação de stent\nem artéria descendente anterior por um infarto agudo do miocárdico. Encontra-se estável e com\ntratamento otimizado para insuficiência cardíaca, consequente ao infarto. Fuma há 18 anos, cerca\nde 20 cigarros por dia. O motivo principal da procura pelo atendimento é a gravidez da esposa após\nvários anos de tentativas sem sucesso. Assinale a alternativa INCORRETA:","options":{"A":"O tabagismo representa atualmente a segunda causa de morte prevenível no mundo.","B":"O tratamento do tabagismo tem dois componentes básicos: a terapia cognitivo-comportamental e\no tratamento medicamentoso. As duas estratégias\ncombinadas aumentam mais a chance de\nsucesso que sozinhas.","C":"A principal droga utlizada para cessação do tabagismo em paciente esquizofrênico é a\nbupropriona. Nestes pacientes, a reposição de nicotina não se mostrou efetiva na cessação do\ntabagismo.","D":"Todos os tratamentos medicamentosos disponíveis se mostraram efetivos e seguros em\npacientes com doença cardiovascular estável.","E":"O tratamento farmacológico disponível não pode ser utilizado nas grávidas, exceção às\ntabagistas pesadas que não conseguem parar\napenas com a terapia cognitivo-comportamental."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-80827","number":"80827","sourceNumber":"80827","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"João, cinco meses, dá entrada no pronto-socorro, trazido pelo pai, que refere ter\nencontrado o filho desmaiado e caído ao pé da escada de sua casa. Ao exame: não apresenta\nequimoses ou hematomas na cabeça, membro inferior esquerdo engessado devido à queda\nanterior que provocou a fratura do fêmur. Fundo de olho apresenta hemorragia retiniana e a\ntomografia de crânio detecta hemorragia subaracnóidea. O diagnóstico CORRETO é:","options":{"A":"Traumatismo cranioencefálico devido à queda.","B":"Síndrome do bebê sacudido devido a maus-tratos.","C":"Acidente vascular cerebral devido à malformação vascular cerebral.","D":"Síndrome convulsiva devido à epilepsia.","E":"Tromboembolismo gorduroso devido à fratura do fêmur."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-62497","number":"62497","sourceNumber":"62497","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Ao chutar a vasilha de comida em que o gato da casa estava se alimentando, Catarina,\nde 5 (cinco) anos, levou mordida única e\nprofunda em panturrilha. Procurou imediatamente o\nserviço de saúde, pois o ferimento estava sangrando bastante. O gato pode ser observado na\nresidência da criança. Todas as orientações abaixo são recomendadas, EXCETO:","options":{"A":"Lavar o ferimento o mais rápido possível, independente do tempo transcorrido, com água\ncorrente abundante e sabão.","B":"Observar o animal em local apropriado durante os 10 dias após a exposição, alimentando-o\nnormalmente.","C":"Iniciar esquema profilático com 2 (duas) doses, uma no dia 0 e outra no dia 3. Se o animal\nmorrer, desaparecer ou se tornar raivoso,\ncompletar o esquema até 5 (cinco) doses e aplicar o soro\nantirrábico.","D":"Iniciar o esquema profilático com soro e 5 doses de vacina nos dias 0, 3, 7, 14 e 28.","E":"Proceder a profilaxia do tétano segundo o esquema preconizado, caso não seja vacinado ou\nesteja com esquema vacinal incompleto."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-48603","number":"48603","sourceNumber":"48603","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"O Sr. Pedro e Dona Margarida moram em uma casa e, para fins de guarda, adquiriram\num pastor alemão, o Rex. Dona Margarida sofreu\num enfarto do miocárdio, sendo socorrida por seu\nmarido e encaminhada à UTI. Foi recomendado ao Sr. Pedro que retornasse para casa. Ao chegar,\nRex procurou por Dona Margarida e, não a encontrando, começou a rosnar para o dono,\n\nimpedindo-o de entrar. O Sr. Pedro forçou a entrada na casa e viu-se engalfinhando com seu\npróprio cachorro. As lesões produzidas foram\nmúltiplas, profundas e com sede em diversas regiões\ndo corpo. O animal foi encaminhado para o canil municipal e o Sr. Pedro foi encaminhado ao\nserviço de profilaxia da Raiva. Assinale a alternativa CORRETA em relação à conduta para o caso:","options":{"A":"Lavar com água e sabão. Observar o animal durante 10 dias após à exposição. Se o animal\npermanecer sadio no período de observação, encerrar o caso. Se o animal morrer, desaparecer ou\nse tornar raivoso, administrar 5 (cinco) doses de vacina (nos dias 0, 3, 7, 14 e 28).","B":"Lavar com água e sabão. Observar o animal durante 10 dias após à exposição. Se o animal\npermanecer sadio no período de observação, encerrar o caso. Se o animal morrer, desaparecer ou\nse tornar raivoso, administrar soro e 5 (cinco) doses de vacina (nos dias 0, 3, 7, 14 e 28).","C":"Lavar com água e sabão. Iniciar imediatamente o tratamento com 5 (cinco) doses de vacina\nadministradas nos dias 0, 3, 7, 14 e 28.","D":"Lavar com água e sabão. Observar o animal durante 10 dias após exposição. Iniciar tratamento\ncom duas doses, uma no dia 0 e outra no dia 3.\nSe o animal permanecer sadio no período de\nobservação, encerrar o caso. Se o animal morrer, desaparecer ou se tornar raivoso, dar\ncontinuidade ao tratamento, administrando o soro e completando o esquema até 5 (cinco) doses.","E":"Lavar com água e sabão. Administrar o soro."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-48595","number":"48595","sourceNumber":"48595","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Uma criança de 11 anos chega à UBSF apresentando várias escoriações pelo corpo,\nvítima de um atropelamento quando a mesma se\nlocomovia com bicicleta. A mãe da criança insiste\nque a criança deve se vacinar contra o tétano, pois alega que \"ela ainda não foi vacinada contra o\nTétano\". Ao examinar o Cartão de Vacina, a técnica de enfermagem diz à mãe que o cartão está\nem dia e adequado para a idade. Analisando o caso à luz do Programa Nacional de Imunizações, a\ntécnica de enfermagem deve:","options":{"A":"Aplicar uma dose de reforço de DPT, pois já se passaram mais de 5 (cinco) anos da última dose\nde vacina que contém o componente tetânico.","B":"Iniciar esquema de 3 (três) doses de dT com intervalo de 2 meses entre elas.","C":"Aplicar uma dose de reforço da dT, pois já se passaram mais de 5 (cinco) anos da última dose\nde vacina que contém o componente tetânico.","D":"Não aplicar nenhuma dose de vacina contra o tétano.","E":"Não aplicar dose de reforço da dT, pois não se passaram 10 anos da última dose de vacina que\ncontém o componente tetânico."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-33818","number":"33818","sourceNumber":"33818","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Com relação à Síndrome de Abstinência Alcoólica (SAA), marque a alternativa\nINCORRETA:","options":{"A":"Os benzodiazepínicos, por serem drogas depressoras do sistema nervoso central e\napresentarem a maior margem de segurança e baixo custo, são considerados os agentes\nfarmacológicos de escolha.","B":"As crises convulsivas generalizadas são bem controladas com doses adequadas de\nbenzodiazepínicos e existem poucas evidências de que a fenitoína e a gabapentina possam\ntambém ser eficazes.","C":"Os antipsicóticos devem ser evitados para controle do estado confusional, pois reduzem o limiar\nconvulsivo.","D":"O delirium tremens é a forma mais grave e temida da SAA, ocorrendo em cerca da metade dos\ncasos, independentemente do controle de outras condições clínicas adversas que possam estar\npresentes."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-33825","number":"33825","sourceNumber":"33825","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Com relação à Doença de Wernicke, é INCORRETO afirmar que:","options":{"A":"É caracterizada pela tríade clínica: oftalmoplegia, ataxia e confusão mental.","B":"Fazem parte do grupo de risco: os etilistas, pacientes com câncer, AIDS, inanição ou\nInsuficiência Renal Crônica Dialítica.","C":"Os pacientes que se recuperam, mostram melhora das paralisias oculares horas após a\nadministração da tiamina, mas o nistagmo horizontal pode persistir.","D":"A maioria dos pacientes apresenta recuperação completa da marcha após a instituição do\ntratamento."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-347377","number":"347377","sourceNumber":"347377","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Um recém-nascido de 12 dias de vida foi levado à unidade de pronto-socorro por\napresentar vômitos, anorexia, irritabilidade,\ndesconforto respiratório e convulsões. O hemograma\ncompleto mostrou anemia. A análise do líquido cefalorraquidiano mostrou pleocitose discreta com\npredomínio de células mononucleares, hiperproteinorraquia e glicorraquia normal. Na admissão,\nainda em crise convulsiva, foi medicado com fenobarbital, com dose de ataque de 20 mg/kg, porém\npermaneceu com crises epilépticas subentrantes. Considerando-se como a principal etiologia uma\ninfecção do sistema nervoso central, para o manejo da condição apresentada pelo paciente deverá\nser administrado","options":{"A":"diazepam, fenitoína, tiopental.","B":"fenitoína, midazolam, tiopental.","C":"fenitoína, lorazepam, piridoxina.","D":"nitrazepam, fenitoína, piridoxina."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-318560","number":"318560","sourceNumber":"318560","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Um menino com 10 anos de idade, com diagnóstico prévio de epilepsia de difícil\ncontrole, em uso de lamotrigina e\ntopiramato, está sendo atendido em sala de emergência de\nhospital de referência terciária, com quadro de mal convulsivo. A crise teve inicio há 20 minutos,\nem\ncasa, sem desencadeante definido. A glicemia de entrada foi 120 mg/dL. Está com acesso venoso\nperiférico, com fonte de oxigênio (cateter 2 litros/minuto), saturação transcutânea de 95%, pulsos\ndistais amplos, tempo de enchimento capilar de 3 segundos, auscultas pulmonar e cardíaca\nnormais, sem lesões de pele. Inicialmente, foi administrado diazepínico (3 doses) por via\nendovenosa, sem melhora dos abalos, mantendo-se hipertonia, desvio ocular e salivação. Optou-se\npor iniciar hidantalização com fenitoína, administrada em velocidade de 50 mg/minuto. Seguindo o\nprotocolo de tratamento de mal epiléptico, caso não haja reversão da crise, quais são,\nrespectivamente, a opção terapêutica a ser adotada e o principal risco do seu uso?","options":{"A":"Tiopental; arritmia cardíaca.","B":"Midazolan; hipertensão intracraniana.","C":"Propofol; instabilidade hemodinâmica.","D":"Fenobarbital sódico; depressão respiratória."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-319931","number":"319931","sourceNumber":"319931","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Criança de 4 anos de idade, sexo feminino, foi levada ao pronto-socorro (PS) devido a\nquadro de crise convulsiva tônico-clônica generalizada, iniciada havia aproximadamente 10\nminutos, associada a febre. Ao chegar ao PS, a criança encontrava-se no colo do pai, acordada,\ncom temperatura axilar de 37 °C. Na história clínica, a mãe relatou que a crise tinha sido rápida e\nque ocorreu logo após ela ter administrado à criança medicação para febre, que se encontrava em\n38,5 °C. Negou doença neurológica e outros sinais e sintomas. A criança tinha apresentado crise\nsemelhante com 18 meses de idade. As crises eram sempre com febre. A criança ficou em\nobservação por 12 horas, sem novas crises, sem alterações metabólicas. A partir do prontuário da\nfamília, o plantonista observou que a família estava em vulnerabilidade social e que, havia 2 anos,\num filho do casal, de 1 mês de idade, tivera morte súbita. Considerando o acompanhamento dessa\nfamília, assinale a opção que explicita um projeto terapêutico adequado ao caso.","options":{"A":"O acompanhamento da criança deve ser feito por especialista, o que é mais indicado para\ndescartar trauma e violência infantil.","B":"A criança deve realizar exames complementares, como tomografia cerebral, na própria\nemergência, devido ao passado de morte súbita do irmão.","C":"É necessário tranquilizar os pais e garantir um acompanhamento longitudinal da criança, com\nobservação de novas crises.","D":"A criança deve ser mantida internada para investigação, porque não é comum crise\ntônico-clônica generalizada com febre."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-355226","number":"355226","sourceNumber":"355226","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Homem de 40 anos, internado devido a quadro de fraqueza difusa, de início há 3\nsemanas, com acometimento de membros\nsuperiores e inferiores. Durante anamnese, refere que o\nquadro foi progressivo, sem perceber diferença de acometimento entre os membros, nem quanto à\nintensidade da fraqueza, nem quanto ao surgimento dos sintomas. Relata manter a intensidade da\nfraqueza ao longo do dia, sem perceber aumento ou piora de redução de força em um mesmo dia.\nNega febre, sintomas respiratórios, digestivos e urinários. Apresenta preservada a motricidade em\nface e a funcionalidade esfincteriana. Ao exame físico, força grau 3 em todos os membros,\nfraqueza predominantemente proximal, redução de tônus muscular e preservação de reflexos\ntendineos e de sensibilidade. Com base nesse quadro, o provável diagnóstico é","options":{"A":"Miastenia grave.","B":"Síndrome de Guillain-Barré.","C":"Miopatia.","D":"Polineuropatia desmielinizante inflamatória crônica.","E":"Mielite transversa cervical."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-355240","number":"355240","sourceNumber":"355240","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Paciente com 1ano e 3meses de idade dá entrada no pronto-socorro infantil\napresentando convulsão tônico-clônica, iniciada\nhá aproximadamente 20 minutos, segundo\ninformações da mãe. No exame físico da admissão, apresenta cianose central, frequência cardíaca\nde 100 batimentos por minuto; saturação de oxigênio de 80%; temperatura axilar de 38,9° C e\nconvulsão tônico-clônica. Além de monitorizar, garantir vias aéreas e ofertar oxigênio, a conduta\ninicial imediata e mais adequada para o tratamento da convulsão febril é","options":{"A":"Dipirona endovenosa.","B":"Diazepam via retal.","C":"Midazolam endovenoso.","D":"Diazepam intranasal.","E":"Midazolam intranasal."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-331139","number":"331139","sourceNumber":"331139","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Mulher de 42 anos acorda com uma sensação de \"dormência\" facial à esquerda. Após\ncerca de 2 horas, ela desenvolve otalgia\ndo lado esquerdo, hiperacusia e desconforto facial. O\nquadro seguiu-se com paralisia facial do lado esquerdo da face, com desvio da rima labial, fraqueza\nfacial e assimetria progredindo para paralisia flácida completa no início da noite. Ao exame\nfísico, a\naparência de repouso da face esquerda demonstra ptose do supercílio, fissura palpebral alargada,\napagamento do sulco nasolabial esquerdo e mau posicionamento inferior da comissura oral\nesquerda. Há completa ausência de movimento da sobrancelha, fechamento incompleto do olho\ncom esforço total e perda de sorriso, rosnado e franzimento do lábio no lado afetado. Sem outras\nalterações no exame físico e a paciente não apresenta comorbidades ou faz uso de medicações.\n\nAo comparecer ao serviço de pronto atendimento, a medicação que deve ser prescrita é a(o)","options":{"A":"prednisona.","B":"alteplase.","C":"heparina.","D":"ácido acetil salicílico.","E":"tenecteplase."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-343686","number":"343686","sourceNumber":"343686","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"A queixa de fraqueza muscular aguda na emergência, e mesmo entre pacientes\ninternados, necessita de raciocínio elucidativo\npara estabelecimento e condutas específicas. Sobre\nessa síndrome, é correto afirmar que:","options":{"A":"Piridostigmina está indicada como primeira linha na síndrome de Guillain-Barré.","B":"Plasmaférese está contraindicada em pacientes com síndrome de Guillain-Barré.","C":"bloqueadores neuromusculares estão indicados em pacientes com suspeita de Miastenia Gravis.","D":"Ptose palpebral não é um achado associado à Miastenia Gravis.","E":"a queixa de dor pode estar presente na síndrome de Guillain-Barré, especialmente na fase de\nrecuperação."},"answer":"E","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-343689","number":"343689","sourceNumber":"343689","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Sobre o estado de mal epilético é correto afirmar que:","options":{"A":"a retirada de medicamento anticonvulsivante não está entre suas principais causas.","B":"o eletroencefalograma tem pouco valor no diagnóstico.","C":"a dosagem sérica de drogas anticonvulsivantes, quando disponível, pode ser recomendada.","D":"diazepam e midazolam estão proscritos no manejo farmacológico inicial.","E":"propofol é indicado quando o paciente apresenta alergia à fenitoína em dose de ataque."},"answer":"E","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-331180","number":"331180","sourceNumber":"331180","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Médico de plantão na UPA admite um paciente de 1 ano e 7 meses de idade com\nhistória de primeiro episódio convulsivo de\nduração breve e resolução espontânea, há cerca de 20\nminutos. Na admissão, encontrava-se em estado pós-ictal e com temperatura axilar de 38,5oC, sem\noutras alterações no exame físico. História familiar com avó epilética e pais saudáveis. Assinale a\nalternativa que melhor representa o caso descrito acima com a respectiva conduta.","options":{"A":"Trata-se de uma convulsão febril benigna/ iniciar fenobarbital contínuo.","B":"Trata-se de uma provável infecção de sistema nervoso central / coletar líquor e iniciar\nceftriaxona.","C":"O paciente é portador de epilepsia familiar / tratamento com valproato de sódio.","D":"Trata-se de uma convulsão febril benigna / conduta expectante.","E":"O diagnóstico mais provável é encefalite viral/ tratamento com aciclovir endovenoso."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-269764","number":"269764","sourceNumber":"269764","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Homem de 30 anos procurou atendimento médico no serviço de urgência apresentando\nmanchas vermelhas em todo o corpo, olho\nvermelho, febre baixa, dores musculares e articulares.\n\nApós exames clínico e laboratoriais de sorologia, foi detectada infecção por Zika vírus. O quadro do\npaciente agravou, apresentando como complicação a síndrome de Guillain-Barré. Uma condição de\norigem autoimune que acomete nervos, levando a quadros de fraqueza muscular progressiva\nseguida de paralisia. Sobre esta condição neurológica, assinale a alternativa correta.","options":{"A":"Esta condição clínica resulta da progressiva destruição das bainhas de mielina das fibras\nnervosas presentes no interior da medula, assim, há progressiva diminuição até extinção dos\nimpulsos nervosos centrais.","B":"O quadro de fraqueza muscular progressiva seguida de paralisia é explicado pelo distúrbio do\ncorpo celular dos neurônios que ficam nos\ngânglios localizados na raiz dorsal dos nervos espinhais.","C":"A fraqueza muscular é decorrente da desmielinização de fibras dos nervos periféricos\nacometidos, resultando na redução ou ausência de\ncondução do impulso nervoso que levariam à\ncontração das fibras musculares.","D":"Esta condição de origem autoimune está relacionada com a morte das células denominadas de\noligodendrócitos, que realizam a produção da mielina presente nas fibras nervosas periféricas.","E":"Não há indícios na literatura que possam considerar a infecção por Zika vírus como um gatilho\npara a síndrome de Guillain-Barré."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-276706","number":"276706","sourceNumber":"276706","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Com relação as convulsões neonatais familiares benignas é correto afirmar que:","options":{"A":"O RN desenvolve crises clônicas unifocais entre a sexta e sétima semana de vida.","B":"Tem caráter autossômico dominante.","C":"Sempre ocorre crises de apneia.","D":"As crianças não desenvolvem epilepsia no futuro.","E":"O EEG intercrítico é alterado."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-276737","number":"276737","sourceNumber":"276737","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Você está de plantão no Pronto Socorro Municipal e atende um lactente de 9 meses de\nidade que apresentou crise convulsiva generalizada, tônico-clônica, há 10 minutos. Segundo a\nmãe, o paciente apresenta tosse seca, coriza hialina e febre moderada há 2 dias. A crise convulsiva\ncessou espontaneamente, após 5 minutos. Ao exame, lactente dormindo, porém reativo ao\nmanuseio, febril, hidratado, corado, otoscopia com hiperemia leve, ausculta pulmonar e cardíaca\nsem alterações, fontanelas planas e normotensas. Levando em consideração a principal hipótese\ndiagnóstica para esse caso, assinale a alternativa correta.","options":{"A":"Trata-se de evento benigno, cujo principal fator predisponente é a herança familiar.","B":"Deve-se iniciar medicação anticonvulsivante de uso contínuo por se tratar de condição crônica e\nrecidivante.","C":"O início precoce de antibioticoterapia muda o curso da doença, diminuindo a morbimortalidade.","D":"O tratamento das crises, nesse caso, é feito apenas com observação e suporte clínico.","E":"O prognóstico é reservado, com chance de evoluir para epilepsia na maioria dos casos."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-269826","number":"269826","sourceNumber":"269826","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Criança de 2 anos com quadro de infecção aguda de vias aéreas superiores há 1 dia,\nem uso de sintomáticos. Hoje apresentou\nepisódio de crise convulsiva que coincidiu com a\nascensão rápida da temperatura, o qual durou cerca de 5 minutos, sendo levada ao pronto-socorro\nonde chegou no período pós-ictal. Exame neurológico sem alterações, com ausência de sinais de\nirritação meníngea ao exame físico. Sobre manejo do caso em questão, é CORRETO afirmar que:","options":{"A":"O controle rigoroso da febre com o uso de antitérmicos e/ou banhos é o aspecto mais importante\ndo tratamento.","B":"O risco de um novo episódio convulsivo durante o mesmo quadro febril é bastante frequente, por\nisso está sempre indicada internação hospitalar.","C":"Durante a crise recomenda-se a imobilização da criança para restringir seus movimentos, bem\ncomo a introdução de um objeto ou pano no\ninterior da boca.","D":"O exame do líquido cefalorraquidiano deve ser realizado com urgência no caso em questão.","E":"Indica-se a realização de Eletroencefalograma (EEG) no pronto-socorro para estabelecimento da\nterapêutica adequada."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-277802","number":"277802","sourceNumber":"277802","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Sobre a síndrome de West, é CORRETO afirmar:","options":{"A":"O diagnóstico eletroencefalográfico corresponde a padrão de hipsarritmia.","B":"Corresponde a crises convulsivas benignas, que acometem principalmente o sexo feminino.","C":"O início é tardio, por volta de 5 anos de idade e não compromete o desenvolvimento\nneuropsicomotor.","D":"A sífilis congênita é a principal etiologia relacionada à síndrome.","E":"É relacionada a refluxo gastroesofágico grave em lactentes."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-227632","number":"227632","sourceNumber":"227632","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Um paciente de 17 anos é trazido pela equipe do SAMU para uma Unidade de\nUrgência devido ter evoluído no domicílio com\ncrise convulsiva, que segundo o quadro descrito pela\nmãe do paciente pode-se caracterizar como um episódio tônico-clônico tipo grande mal. O paciente\nchegou no hospital em estágio pós-ictal, tendo recebido 5 mg de diazepam ainda no domicílio.\n\nSubitamente o paciente reiniciou crise convulsiva, com características conforme as características\ndescritas pela mãe. Não há histórico pessoal ou\nfamiliar de crises anteriores, tampouco de traumas\nem seguimento cefálico recentes ou anteriores. Não há histórico de tabagismo, etilismo ou uso de\ndrogas ilícitas. De acordo com o quadro acima, marque a alternativa correta.","options":{"A":"A conduta inicial é realizar nova aplicação de Diazepam ou midazolam, associando fenitoína\ncaso não ocorra remissão do quadro após 10\nminutos.","B":"As causas mais comuns a considerar são os sangramentos do sistema nervoso central,\ntraumatismo cranioencefálico, abcesso cerebral, hiponatremia e meningite.","C":"Diagnósticos diferenciais incluem migrânea, ataques e ansiedade/pânico, convulsão psicogênica\nnão epilética, intoxicação por salicilatos e\ndiscinesia paroxística.","D":"Está indicada a internação hospitalar em caso de diagnósticos graves como tumores do sistema\nnervoso ou AVC; na ausência de diagnóstico a conduta é de investigação ambulatorial após\nremissão da crise.","E":"Deve-se internar o paciente para vigilância e investigação; caso ele evolua com mais de quatro\nepisódios convulsivos dentro de 24 horas pode-se confirmar o diagnóstico de epilepsia."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-227638","number":"227638","sourceNumber":"227638","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"São características clinicopatológicas principais da esclerose múltipla:","options":{"A":"Desmielinização inflamatória da sustância branca do sistema nervoso central.","B":"Alterações na função imunorreguladora das células B e produção de citocinas anti-inflamatórias.","C":"A doença não responde a tratamento com imunomoduladores.","D":"O LCR apresenta níveis de proteínas totais alterados, sem características específicas.","E":"Ocorre alteração da função dos plasmócitos, com falha da ação dos linfócitos B reguladores."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-203776","number":"203776","sourceNumber":"203776","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Assinale o(os) exame(s) que fornece(m) o diagnóstico de certeza de dermatomiosite.","options":{"A":"Exame histopatológico de pele.","B":"Biópsia muscular.","C":"Ressonância nuclear magnética.","D":"Eletromiografia.","E":"CPK & aldolase."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-215923","number":"215923","sourceNumber":"215923","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Lactente de 5 meses de idade, prematuro extremo e anoxiado grave, é atendido em\nUnidade de Pronto Atendimento com quadro de convulsão tipo tônico-clônica generalizada há\naproximadamente 10 minutos. Faz uso de Fenobarbital desde o nascimento, porém está sem a\nmedicação há dois dias. Sobre o caso descrito, assinale a alternativa correta.","options":{"A":"Por se tratar de lactente abaixo de 6 meses, a droga escolha para controle inicial da crise\nepiléptica é o fenobarbital na dose de ataque de 15 mg/kg, seguida de manutenção na dose\nanteriormente utilizada.","B":"Devem-se fazer as medidas gerais com proteção de quedas, monitorização, desobstrução e\naspiração de vias aéreas, oxigenoterapia e evitar o uso de cânulas de Guedel pelo risco de\nobstrução de vias aéreas superiores.","C":"Os benzodiazepínicos são as drogas de escolha para o tratamento inicial da crise epiléptica,\npodendo ser realizado diazepam ou midazolam via endovenosa (via prefrencial), via retal\n(diazapem) ou nasal (midazolam).","D":"Por se tratar de paciente com histórico anterior de epilepsia, em uso crônico de droga\nantiepiléptica, deve-se tratar a crise epiléptica atual com a dose habitual da medicação\nanticonvulsivante já utilizada, porém por via endovenosa.","E":"Trata-se de estado de Mal epiléptico, devendo ser tratado com benzodiazepínico, seguido de\nfenitoína em dose de ataque e valproato de sódio endovenoso. Caso não seja contralada a crise,\ntransferir o paciente para Unidade de Terapia Intensiva."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-175225","number":"175225","sourceNumber":"175225","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Nos critérios de Bohan e Peter para o diagnóstico de dermatomiosite juvenil, as lesões\npatognomônicas são","options":{"A":"sinal do xale e heliotropo.","B":"eritema malar e pápulas de Gottron.","C":"eritema malar e sinal do xale.","D":"heliotropo e pápulas de Gottron.","E":"sinal do xale e calcinoses."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-181783","number":"181783","sourceNumber":"181783","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"O Estado de Mal Convulsivo é a emergência neurológica mais comum da infância,\ndefinido pela maioria dos autores como ?uma\ncrise epiléptica única ou por crises epilépticas\nsubintrantes e sem recuperação da consciência entre os eventos com duração igual ou superior a\n30 minutos?. Sobre o Estado de Mal Convulsivo é correto afirmar que:","options":{"A":"são etiologias de quadro agudo o uso de antibióticos endovenosos (cefalosporinas, penicilinas e\nmetronidazol) e convulsão febril.","B":"a fenitoína é droga de primeira escolha na emergência na tentativa de abortar a crise\nconvulsiva.","C":"o uso de benzodiazepínicos deve ser desencorajado devido sua meia vida curta, sendo indicado\no uso de fenobarbital em dose de ataque.","D":"caso não seja conseguido acesso venoso periférico na urgência, um acesso venoso central deve\nser rapidamente obtido.","E":"o Estado de Mal Convulsivo é sempre generalizado, podendo ser do tipo tônico, clônico, ou\ntônico-clônico."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-134545","number":"134545","sourceNumber":"134545","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"A respeito das úlceras de pressão, é CORRETO afirmar que:","options":{"A":"a úlcera de pressão se desenvolve quando a pressão nos capilares é superior à pressão externa\n(partes moles envolvidas).","B":"tolerância tissular, diminuição da percepção sensorial e idade são fatores extrínsecos.","C":"a fricção e a força de cisalhamento não se alteram com a presença constante de fezes e urina.","D":"na úlcera de pressão estágio III há perda total da pele e envolvimento do tecido celular\nsubcutâneo sem comprometimento da fáscia muscular.","E":"nas úlceras de pressão estágio I há perda parcial da espessura da pele e envolvimento da\nepiderme e derme, aprensentando-se como abrasão ou cratera rasa."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-86515","number":"86515","sourceNumber":"86515","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Mulher de 55 anos procura o ambulatório de Clínica Médica para Check-up de rotina.\nEstá assintomática. Durante a anamnese, nega\ncomorbidades, refere uma cirurgia prévia\n(cesariana sem intercorrências). Menopausa há um ano. Pratica exercícios diariamente e mantém\numa alimentação saudável. Sua mãe morreu de ?câncer de intestino? aos 68 anos de idade,\ndemais parentes saudáveis. No exame físico, IMC de 24, PA: 110/80 mmHg e circunferência\nabdominal de 80 cm. Faz uso diário de cálcio e Vitamina D. A conduta mais apropriada para o\nclínico geral é solicitar, além de hemograma, bioquímica e lipidograma:","options":{"A":"ultrassonografias mamária e transvaginal.","B":"retossigmoidoscopia e ultrassom de abdome total.","C":"pesquisa de sangue oculto nas fezes e densitometria óssea.","D":"colonoscopia, mamografia, e ultrassom transvaginal.","E":"retossigmoidoscopia, radiografia de tórax e densitometria óssea."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-70807","number":"70807","sourceNumber":"70807","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Paciente hipertenso com sopro abdominal apresenta angiotomografia mostrando\nestenose da artéria renal direita. Das\nmedicações abaixo, está contraindicada para o tratamento da\nhipertensão arterial nesse paciente:","options":{"A":"Alfametildopa.","B":"Betabloqueadores.","C":"Inibidores da enzima conversora de angiotensina.","D":"Bloqueadores dos canais de cálcio."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-64174","number":"64174","sourceNumber":"64174","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Na doença de Chagas, o inseto transmissor, a forma infectante para o ser humano e\nlocal onde é encontrado são, respectivamente:","options":{"A":"flebótomo; amastigota; fezes.","B":"triatomínio; tripomastigota; urina.","C":"flebótomo; promastigota; sangue.","D":"triatomínio; tripomastigota metacíclico; fezes.","E":"triatomínio; amastigota; fezes."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-341099","number":"341099","sourceNumber":"341099","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Genitora traz ao Hospital Infantil sua filha de 1 ano e 4 meses, com quadro febril de 39º\nC, tosse produtiva e rinorreia. Dez minutos\nantes a chegada no hospital, a lactente apresentou crise\ntônica clônica generalizada com duração de 5 minutos. A mãe relata ser o primeiro episódio e que\nestá preocupada com a possibilidade de a criança ter uma doença grave. Durante o exame físico, a\npaciente encontra-se ativa e reativa ao exame, febril, com temperatura de 38º graus, com sinais de\nKernig e Brudzinski negativos. A ausculta respiratória, exame da orofaringe e otoscopia normais.\n\nQuanto apresentado, a conduta correta é:","options":{"A":"Prescrever fenobarbital e antitérmico e solicitar a avaliação imediata de neurologista.","B":"Prescrever antitérmico e orientar que a crise não produz lesão neurológica ou déficit cognitivo.","C":"Prescrever antitérmico e orientar aos pais que o risco de desenvolver epilepsia é alto se a\ncriança tiver outras crises como essa.","D":"Fazer diazepam endovenoso imediatamente e prescrever anticonvulsivante para uso contínuo\ndomiciliar.","E":"Prescrever diazepam endovenoso e solicitar eletroencefalograma."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-326430","number":"326430","sourceNumber":"326430","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Um homem de 48 anos de idade procura ambulatório de clínica médica no Centro de\nSaúde Nova Esperança com queixa de fraqueza\nprogressiva há 6 meses. Relata tropeçar com os\ndedos dos pés enquanto caminha; em certa ocasião deixou cair um copo cheio de água por se\nsentir muito fraco para tolerar o peso dele. Suspeitamos de um distúrbio acometendo o neurônio\nmotor inferior. Dos achados abaixo, qual deles não possui uma manifestação de acometimento de\nneurônio motor inferior?","options":{"A":"Diminuição do tônus muscular.","B":"Fraqueza distal maior que a proximal.","C":"Fasciculações.","D":"Reflexos tendíneos negativos.","E":"Atrofia muscular grave."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-344864","number":"344864","sourceNumber":"344864","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Sobre as convulsões na infância, assinale a alternativa correta sobre o manejo:","options":{"A":"Deve-se iniciar a monitorização hemodinâmica, seguida de suporte ventilatório conforme\nnecessidade do paciente, além de punção\nvenosa. A medicação de escolha para abortar a crise é o\nbenzodiazepínico.","B":"No atendimento inicial de paciente com crise convulsiva, deve-se inicialmente administrar o\nbenzodiazepínico, para abortar a crise, e na sequência iniciar com anamnese e exame físico\ndetalhado para melhor investigação da origem do quadro.","C":"A Tomografia de crânio sem contraste é indicada em todos os casos para descartar lesões\nexpansivas que possam causar o quadro convulsivo","D":"A principal causa de crise convulsiva na infância são as intoxicações exógenas","E":"A partir da segunda crise, faz-se necessário o uso de terapia medicamentosa profilática para\nevitar novos eventos."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-326493","number":"326493","sourceNumber":"326493","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Regina, de 2 anos, é levada à emergência pediátrica com quadro de convulsão tônico\nclônica generalizada com duração de 5 minutos.\nExame físico: T.: 37,8°C, acordada e atenta ao\nmeio. Os pais informam que a paciente é portadora de sequela de encefalopatia hipóxico-isquêmica\ndevido a quadro de asfixia neonatal, porém negam crises prévias. Diante desse quadro, o dado que\nafasta o diagnóstico de convulsão febril benigna é:","options":{"A":"Característica da crise.","B":"Presença de doença de base.","C":"Duração da crise.","D":"Idade da paciente.","E":"Perda da consciência."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-308581","number":"308581","sourceNumber":"308581","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"A diferenciação de convulsões febris simples e complexas exige uma atenta\nobservação clínica e muito boa capacidade de\ncomunicação com a família. Dentre as assertivas\nabaixo, é característica de síndrome convulsiva febril complexa:","options":{"A":"Ausência de problemas neurológicos complexos.","B":"Manifestações focais.","C":"Uma crise no período de 24 horas.","D":"Duração de 10 minutos.","E":"Crises generalizadas."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-257205","number":"257205","sourceNumber":"257205","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"A miastenia gravis é doença autoimune em que ocorre formação de anticorpos contra\nos receptores nicotínicos da junção\nneuromuscular. O principal sintoma é a fraqueza muscular.\n\nExiste forte associação da miastenia gravis com qual das neoplasias a seguir?","options":{"A":"Timoma.","B":"Carcinoma de células claras do rim.","C":"Adenocarcinoma de ovário.","D":"Carcinoma epidermoide de pulmão.","E":"Leucemia mieloide aguda."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-273857","number":"273857","sourceNumber":"273857","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Lactente de 4 meses, chega à emergência apresentando movimentos repetitivos da\ncabeça e desvio ocular para a esquerda,\ncom breves períodos de perda de contato com o meio.\nApós 20 min de iniciado o evento, evoluiu com abalos clônicos no hemicorpo esquerdo e, em\nseguida, abalos tônico-clônicos generalizados. Ainda ao exame físico: mostrava-se afebril, com\ncianose perioral, pouco irritado, com fontanela normotensa, sem outras anormalidades. Após duas\ndoses de Diazepam endovenoso, não houve melhora da crise. Qual conduta a seguir NÃO seria\napropriada nesse momento?","options":{"A":"Fenitoína 15 mg/kg.","B":"Repetir Diazepam 0,3 mg/kg.","C":"Aguardar a avaliação Neurológica, para prescrever o próximo antiepiléptico.","D":"Administrar Fenobarbital.","E":"Conduzir o lactente dentro de um ambiente semi intensivo (área vermelha da emergência)."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-264531","number":"264531","sourceNumber":"264531","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Qual o anticorpo mais provavelmente associado à forma amiopática da\ndermatomiosite?","options":{"A":"Anti-TIF-1.","B":"Anti-MDA-5.","C":"Anti-Ku.","D":"Anti-Mi-2.","E":"Anti-Scl70."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-273873","number":"273873","sourceNumber":"273873","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Você está de plantão e recebe R.J.M. 16 anos, feminino, trazidos pelos pais, pois\npassou a aumentar a frequência de crises\nconvulsivas após início do tratamento. Segundo seus\npais, há dois meses ela passou a apresentar quadro abalos musculares súbitos e rápidos em\nmembros superiores, ao despertar, associado a alterações de consciência onde parecia ficar\n\"desligada\" por segundos. Procuraram médico da atenção primária que solicitou\neletroencefalograma, tendo este os seguintes achados: Complexo ponta-onda e poliponta-onda\ngeneralizados, sendo assim prescreveu Carbamazepina 400mg/dia dividido em duas tomadas de\n12 em 12 horas. Após início do tratamento as crises passaram a aumentar de frequência. Diante do\ncaso, qual a conduta:","options":{"A":"Ajuste de dose da medicação para 600mg/dia.","B":"Ajuste da medicação para 200mg/dia.","C":"Troca da medicação para fenitoína.","D":"Troca da medicação para ácido valpróico.","E":"Troca da medicação para oxcarbazepina."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-284487","number":"284487","sourceNumber":"284487","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Sobre a síndrome de Guillain-Barré (SGB), observe as afirmações abaixo: I. Os\nindivíduos do sexo masculino correm risco\nligeiramente maior de SGB e, nos países ocidentais, os\nadultos são acometidos com maior frequência do que as crianças; II. O padrão habitual é de\nparalisia ascendente, que pode ser percebida inicialmente como sensação de peso nas pernas. A\nfraqueza surge em questão de horas a alguns dias e, muitas vezes, é acompanhada de disestesias\ncom formigamento nos membros; III. Cerca de 70% dos casos de SGB ocorrem 1 a 3 semanas\napós processo infeccioso agudo, em geral respiratório ou gastrintestinal; IV. Os achados no líquido\ncefalorraquidiano (LCR) são distintos, consistindo em nível de proteína elevado [1 a 10 g/L (100 a\n1.000 mg/dL)] sem pleocitose concomitante. O LCR é frequentemente normal quando os sintomas\nestão presentes há ? 48 horas; V. O prognóstico é pior em pacientes com lesão axonal motora e\nsensorial proximal grave. São corretas as afirmativas contidas em:","options":{"A":"Apenas I, II, III são corretas","B":"Todas são corretas exceto a afirmativa I","C":"Apenas I, II e IV são corretas","D":"Todas são corretas","E":"Todas são incorretas"},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-212497","number":"212497","sourceNumber":"212497","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"As malignidades eventualmente manifestam-se através de efeitos mediados pela\nliberação de fatores humorais com efeitos\nbiológicos diversos ou através de reações mediadas pelo\nsistema imunológico. Marque a alternativa INCORRETA em relação às síndromes paraneoplásicas.","options":{"A":"Síndrome de Eaton-Lambert caracteriza-se por fraqueza muscular distal que melhora com\ncontração mantida do membro acometido.","B":"Heliótropo corresponde a uma lesão violácea encontrada nas pálpebras e fortemente\nrelacionada à dermatopolimiosite.","C":"Rubor facial, hipotensão e diarreia são causados pela liberação maciça de serotonina na\ncirculação a partir de tumores carcinoides originados do intestino médio (origem embriológica),\nsugerindo metástases hepáticas já instaladas.","D":"Encefalite límbica corresponde a um quadro neurológico caracterizado por alterações cognitivas,\nmediada pelo surgimento de anticorpos com especificidade para componentes neuronais\nespecíficos, como o anti-HU.","E":"Hipoglicemia severa pode estar associada a malignidades através da formação de IGF-II por\ntumores mesenquimais, anticorpos anti-insulina ou comprometimento extenso e maciço do fígado\npelo tumor."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-212569","number":"212569","sourceNumber":"212569","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Menino, 10 meses, é trazido ao pronto atendimento com relato de convulsão\ntônico-clônica generalizada, ocorrida em casa, por curta duração, há 30 minutos. Sem\n\nantecedentes patológicos. Nascido de parto normal a termo, com Apgar 7 e 9. Encontra-se com Tax\n\n= 38,2°C, alerta, atento ao ambiente, choro consolável. Fontanela normotensa. A mãe encontra-se\nbastante estressada, pois a filha mais velha, de\n9 anos, ?tornou-se epiléptica depois de uma crise\nassim?. Qual a conduta apropriada ao caso relatado?","options":{"A":"Prescrever fenobarbital e solicitar eletroencefalograma.","B":"Internar pelo risco de recorrência da crise convulsiva febril e iniciar benzodiazepínico\nintermitente.","C":"Prescrever benzodiazepínico oral intermitente para próximo quadro febril e solicitar\neletroencefalograma.","D":"Prescrever benzodiazepínico oral intermitente se houver recorrência da crise convulsiva febril.","E":"Prescrever ácido valpróico e solicitar tomografia de crânio"},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-185323","number":"185323","sourceNumber":"185323","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Homem, 64 anos, avaliado por quadro de evolução nos últimos 02 meses de dificuldade\nprogressiva em falar, apesar de compreender adequadamente, acompanhado por engasgos\nfrequentes principalmente para líquidos, seguidos pelo surgimento de dificuldade progressiva em\nsubir escadas, levantar-se de cadeiras e deambular. Ao exame, foram observadas fasciculações\nfrequentes na musculatura anterior das coxas e parede abdominal, atrofia muscular moderada,\nespasticidade assimétrica de MMII (predominando à direita) e MSE, com hiper-reflexia bilateral\npatelar (mais evidentes) e bicipital/tricipital à esquerda. Babinski positivo bilateralmente. Os\nachados observados sugerem o seguinte diagnóstico:","options":{"A":"Atrofia muscular espinhal progressiva.","B":"Amiotrofia diabética.","C":"Esclerose múltipla.","D":"Esclerose lateral amiotrófica.","E":"Miastenia gravis."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-155851","number":"155851","sourceNumber":"155851","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Sobre as paralisias flácidas aguda(PFA), assinale a alternativa errada:","options":{"A":"Há 4 pontos anatômicos que quando são acometidos podem causar PFA: neurônio motor e\nmedula, raiz e nervo periférico, junção mioneural e músculo.","B":"Quando a lesão é na medula espinhal, o deficit neurológico não apresenta graduação abaixo de\ndeterminado ponto, e acima deste ponto o exame neurológico é normal , além de existirem\nmanifestações esfincterianas.","C":"Quando for na junção mioneural, ocorre preferência pelos músculos craneanos e da cintura, e\ndeficit proximal em membros; e se for pré-sináptico pode ocorrer aumento da força com o exercício\nenquanto no pós-sináptico há fatigabilidade com o exercício.","D":"No Brasil, na população acima de 20 anos, a principal causa é a poliomelite, sendo em segundo\nlugar a síndrome de Guillain Barré.","E":"Várias doenças podem manifestar-se como PFA, como por exemplo, as mielopatias\ninflamatórias como a poliomelite, e as\nmielites transversas causadas por agentes infecciosos como\no pneumococo e esquistossomose."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-155855","number":"155855","sourceNumber":"155855","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Lactente, 1 ano e 10 meses, apresenta crise epiléptica durante período febril por\nquadro gripal. A crise foi tipo clônica\nfocal, com duração média de 4 minutos e discreta sonolência\nno pós-ictal. Não havia qualquer sinal de infecção meníngea e o seu exame neurológico era\nnormal. Genitora relata evento anterior com a mesma semiologia há 3 meses. Pai com antecedente\nde crise febril. Qual a hipótese diagnóstica e melhor conduta a ser adotada?","options":{"A":"Crise febril complexa. Iniciar terapia contínua com fenobarbital e solicitar LCR,\neletroencefalograma e tomografia de encéfalo pelo\nfato de esta ser a segunda crise da criança.","B":"Crise febril simples. Não há indicação de exames complementares. Realizado apenas orientação\nsobre benignidade do quadro e uso de\nantitérmico.","C":"Crise febril complexa. Iniciar terapia intermitente com clonazepam.","D":"Crise febril simples. Solicitar eletroencefalograma e tomografia pelo risco de evolução para\nepilepsia devido à história familiar positiva.","E":"Crise febril simples. Iniciar terapia contínua com diazepam pelo fato de esta ser a segunda crise\nda criança."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-134900","number":"134900","sourceNumber":"134900","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Nos últimos anos vemos uma tendência de campanhas como o Outubro Rosa e o\nNovembro Azul para estimular a detecção\nprecoce de doenças. O Caderno de Atenção Básica\nsobre Rastreamentos, discute as recomendações do Ministério da Saúde para detecção precoce de\ndoenças. Sobre as recomendações para o rastreamento de doenças em adultos assintomáticos\nsem fatores de risco, assinale a alternativa correta:","options":{"A":"Medir a pressão arterial anual ou bianualmente nos adultos com mais de 18 anos.","B":"Realizar mamografia nas mulheres dos 40 aos 69 anos, bianualmente.","C":"Realizar PSA e toque retal anualmente para homens com mais de 50 anos.","D":"Realizar glicemia de jejum anual para homens e mulheres com mais de 35 anos.","E":"Todas as alternativas estão corretas."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-68127","number":"68127","sourceNumber":"68127","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"\"No Brasil, a maior redução entre as doenças crônicas foi registrada nas mortes por\ndoenças respiratórias (enfisema pulmonar, doença\npulmonar obstrutiva crônica, asma, etc.), o que\nequivale a uma queda média de 2,8% ao ano na taxa de mortalidade. Segundo a análise, um dos\nfatores para esse resultado é a diminuição do tabagismo no país. De 1989 a 2009, o percentual de\nfumantes na população caiu de 35% para 16,2% (fonte: portal da saúde).\" Essa pequena citação\nsintetiza a importância de políticas públicas para a saúde da população. Analise as afirmativas e\nassinale a INCORRETA:","options":{"A":"Ações, junto ao programa saúde na escola, que enfatizam os malefícios do tabagismo para a\npopulação de crianças não tabagistas, é uma ação de prevenção primária.","B":"Existem claras evidências científicas de que todo o paciente deve ser questionado sobre o\nconsumo de tabaco.","C":"O teste de Fagerström pode ajudar na definição do uso do tratamento farmacológico.","D":"A grande dificuldade para o estabelecimento de programas de apoio à cessação ao tabagismo é\no custo, já que as únicas opções terapêuticas\nsão os medicamentos nicotínicos e a bupropiona.","E":"Pacientes que estão nas fases pré-contemplativa e contemplativa precisam ser avaliados, não\nse perdendo a oportunidade de informar sobre os\nmalefícios do tabagismo e de identificar as\nbarreiras que impedem a realização de tentativas de cessação do consumo de tabaco."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-71571","number":"71571","sourceNumber":"71571","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"A população brasileira vem envelhecendo rapidamente, impondo ao sistema de saúde\ngrandes desafios. Em relação a abordagem ao\nidoso é INCORRETO afirmar que:","options":{"A":"A realização de programa de exercícios para o equilíbrio é uma das medidas eficazes para\nprevenção de quedas em idosos.","B":"Os pacientes com mais de 65 anos devem fazer uso de vacina pneumocócica.","C":"Os idosos com mais de 80 anos, que vivem sozinhos, socialmente isolados e que contam com\npoucos recursos econômicos estão em maior\nsituação de risco.","D":"Todos os pacientes idosos que sofreram quedas devem ter suas medicações revisadas e\nalteradas em caso de necessidade.","E":"Idosos que tiveram o teste do sussurro positivo devem ser encaminhados ao\notorrinolaringologista para avaliação do conduto auditivo."},"answer":"E","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-71540","number":"71540","sourceNumber":"71540","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Paciente do sexo feminino, 71 anos, antecedentes de fratura de fêmur com\nosteossíntese há 2 anos, doença arterial\ncoronária submetida e insuficiência cardíaca diastólica. Há\ncinco dias internou na unidade de terapia intensiva por broncopneumonia e insuficiência\nrespiratória, tendo sido necessário ventilação mecânica. Há dois dias respira espontaneamente\ncom suplemento de oxigênio por máscara. Desde então, apresenta períodos com sonolência\nexcessiva, dificuldade de manter a atenção, pensamento desorganizado. Qual das seguintes\nestratégias é recomendada para prevenir e tratar o delirium em pacientes idosos?","options":{"A":"Sedativos devem ser administrados durante todo o período de hospitalização.","B":"O repouso durante o dia deve ser encorajado.","C":"Próteses auditivas devem ser removidas para evitar distração excessiva.","D":"Utensílios para contenção física deve ser evitados.","E":"Durante este período, deve-se evitar contato com familiares tendo em vista que isso acarreta\nmais angústia e agitação."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-65928","number":"65928","sourceNumber":"65928","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"A respeito da atenção à saúde da Pessoa Idosa, pode-se afirmar, EXCETO:","options":{"A":"A depressão é bastante prevalente entre pessoas idosas, sendo mais frequente em homens e\npessoas institucionalizadas.","B":"A escala de Lawton é um dos métodos utilizados para a avaliação das atividades instrumentais\ndiárias ? AIVD.","C":"As quedas representam um sério problema para as pessoas idosas e estão relacionadas a\nelevados índices de morbimortalidade.","D":"Recomenda-se à pessoa idosa a administração de dose anual de vacina contra Influenza, a\natualização da vacina dupla adulto - dT e pelo menos uma dose de vacina antipneumocócica, que\ndeve se seguir de reforço após 5 anos no caso de idosos institucionalizados e não vacinados.","E":"Na avaliação da pessoa idosa devem ser investigadas sistematicamente as doenças\ncardiovasculares, Diabetes e suas complicações,\ndéficits sensoriais, afecções osteoarticualres e\ndéficits cognitivos."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-71569","number":"71569","sourceNumber":"71569","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Homem assintomático, de 70 anos de idade, chega ao seu consultório porque sua\npressão arterial era de 176/86 mmHg, em\ntriagem feita num centro de atendimento a idosos. Você\nconstata hipertensão em duas ocasiões adicionais. A terapia inicial deve ser:","options":{"A":"Inibidor da enzima conversora de angiotensina.","B":"Bloqueador do canal de cálcio.","C":"Diurético.","D":"Betabloqueador.","E":"Vasodilatador de ação central."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-49970","number":"49970","sourceNumber":"49970","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Para os idosos, é considerado normal o IMC (Índice de Massa Corporal), de:","options":{"A":"23 a 28.","B":"18 a 25.","C":"28 a 30.","D":"25 a 30.","E":"35 a 40."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-49968","number":"49968","sourceNumber":"49968","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Analise as assertivas abaixo, marcando V, se verdadeira, ou F, se falsa. ( )\nSenescência é o termo utilizado para se\nreferir às alterações orgânicas, morfológicas e funcionais,\nseguidas de afecções, que ocorrem com o processo de envelhecimento; ( ) Intelectualmente,\ndizemos que uma pessoa está envelhecendo quando começa a ter lapsos de memória, dificuldade\nde aprendizado e falhas de atenção; ( ) Pesquisar sangue oculto nas fezes anualmente é uma das\nações que devem ser realizadas visando a promoção da saúde do idoso; ( ) A permanência na\nvida laboral ativa piora a qualidade de vida do idoso; ( ) A desnutrição proteicocalórica é rara na\nterceira idade; ( ) A xerostomia é uma das alterações mais frequentes na mucosa bucal do idoso e\npode ser agravada ou provocada pelas medicações hipotensoras. Assinale a alternativa correta:","options":{"A":"V, V, F, V, F, F.","B":"V, F, F, F, V, V.","C":"F, V, V, V, F, F.","D":"F, V, V, F, F, V.","E":"V, V, V, V, V, V."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-351048","number":"351048","sourceNumber":"351048","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"O estado de mal epiléptico (EME) é a emergência neurológica mais frequente em\ncrianças e o tempo está relacionado com alta mortalidade e morbidade. Sobre esta situação\nassinale a alternativa correta.","options":{"A":"Todo paciente com EME deve realizar exame de neuroimagem.","B":"A etiologia mais frequente de EME na infância é por síndromes epilépticas complexas ou\nmetabólicas.","C":"O fenobarbital não é recomendado como terapia de primeira escolha na urgência devido aos\nseus efeitos colaterais.","D":"O tempo no qual o tratamento deve ser agressivo para prevenir as consequências a longo prazo\né de 60 minutos.","E":"O tempo no qual se considera uma crise como anormalmente prolongada e que determina o\ninício do tratamento medicamentoso é de 10 minutos."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-351043","number":"351043","sourceNumber":"351043","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Escolar de 6 anos inicia com perda visual, ataxia, déficits motores e sensitivos,\nevolução rapidamente progressiva ao longo de\ndias, com crises convulsivas e alterações do\ncomportamento. Tomografia de crânio normal e ressonância magnética (RM) com grandes lesões\nem T2 com aspecto de massa bilaterais, multifocais, confluente e com edema, com realce de\ncontraste na substância branca e cinzenta dos hemisférios cerebrais, cerebelo e tronco encefálico.\nRealizada pulsoterapia com metilprednisolona por 5 dias com melhora clínica importante. Com base\nna principal hipótese diagnóstica analise as assertivas abaixo e a relação entre elas. I ? Exames de\ncontrole por RM 3 a 12 meses após devem mostrar melhora importante. PORQUE II ? Lesões\nnovas ou aumentadas em T2 devem impulsionar à reavaliação para pesquisa de outras etiologias,\ncomo esclerose múltipla. A respeito destas asserções, assinale a opção correta.","options":{"A":"As asserções I e II são proposições verdadeiras, e a II é uma justificativa da I.","B":"As asserções I e II são proposições verdadeiras, mas a II não é uma justificativa da I.","C":"A asserção I é uma proposição verdadeira, e a II é uma proposição falsa.","D":"A asserção I é uma proposição falsa, e a II é uma proposição verdadeira.","E":"As asserções I e II são proposições falsas."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-322093","number":"322093","sourceNumber":"322093","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Adolescente após quadro de infecção viral desenvolve paralisia de membros inferiores\ne após de membros superiores. Ao exame\napresenta paralisia facial periférica, oftalmoplegia, ataxia\ne arreflexia. Líquor com proteína de 200mg/dl, 3 células. Pensando no provável diagnóstico, qual a\nterapia a ser instituída?","options":{"A":"Plasmaférese.","B":"Doxiciclina oral.","C":"Aciclovir endovenoso.","D":"Imunoglobulina endovenosa.","E":"Pulsoterapia com corticoides."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-322087","number":"322087","sourceNumber":"322087","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"O estado de mal epiléptico (EME) é uma emergência pediátrica e a precocidade no\ndiagnóstico e no tratamento mantém relação direta com a melhora do prognóstico, reduzindo a\nmorbidade neurológica e a mortalidade. Sobre o manejo do EME na infância, analise as assertivas\nabaixo. I ? A definição de EME refratário é o que deixou de responder à terapia com pelo menos\nduas classes de medicações. II ? A terapia inicial de primeira linha deve ser realizada com um\nbenzodiazepínico, em qualquer idade. III ? A terapia subsequente de segunda linha geralmente se\nfaz com fenobarbital. Sobre esta situação selecione a opção correta.","options":{"A":"As afirmativas I e II são verdadeiras. A afirmativa III é falsa.","B":"As afirmativas I e III são verdadeiras. A afirmativa II é falsa.","C":"As afirmativas II e III são verdadeiras. A afirmativa I é falsa.","D":"As afirmativas I, II e III são verdadeiras.","E":"As afirmativas I, II e III são falsas."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-322073","number":"322073","sourceNumber":"322073","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Mulher, 48 anos, portadora de hipertensão arterial e dislipidemia. Faz uso contínuo de\nsinvastatina 40 mg/dia, losartana 50 mg/dia, Hctz 25 mg/ dia. Queixa-se de dores musculares\nindefinidas e fraqueza muscular (ao escovar os dentes e pentear os cabelos) há aproximadamente\n6 meses. Traz exames com dosagens creatina quinase elevada e anticorpos anti-Jo-1 positivos.\n\nQue achados são mais prováveis na evolução deste caso?","options":{"A":"Achados compativeis com tireoidite auto-imune, manifestando-se com tireotoxicose tipo I ou II e\nfrequente evolução para o hipotireoidismo primário.","B":"Positividade de títulos de imunoglobulinas estimulantes da tireoide e de anticorpos dirigidos\ncontra partículas de reconhecimento de sinais (anti SRP).","C":"A ocorrência de fenômeno de Raynaud e artrite, podendo sinalizar a evolução para quadro grave\nde doença intersticial pulmonar progressiva.","D":"A positividade do FAN e de anticorpos dirigidos contra partículas de reconhecimento de sinais\n(anti SRP), reforçando a associação de miopatia induzida por estatinas.","E":"A melhora do quadro de fraqueza muscular com a retirada da sinvastatina mesmo mantendo\nvalores elevados de CPK e a pesquisa negativa de anticorpos contra a 3-hidrox-3-metilglutaril\ncoenzima A."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-295680","number":"295680","sourceNumber":"295680","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Menina de 7 anos chega ao pronto atendimento com queixas de fraqueza, mialgia e\nparestesias em membros inferiores. Relata antecedentes de quadro diarreico há 10 dias, sem sinais\nde gravidade. Ao exame físico apresenta fraqueza muscular simétrica e arreflexia de membros\ninferiores. Nervos cranianos sem alterações. Sobre esta situação selecione a opção CORRETA. I ?\nO exame do liquor pode ser normal na primeira semana da doença. II ? A infecção original mais\nprovável é o Campylobacter jejuni. III ? Os pacientes com progressão lenta poderão simplesmente\nser observados quanto à estabilização e à remissão espontânea sem tratamento medicamentoso.","options":{"A":"As afirmativas I e II são verdadeiras. A afirmativa III é falsa.","B":"As afirmativas I e III são verdadeiras. A afirmativa II é falsa.","C":"As afirmativas II e III são verdadeiras. A afirmativa I é falsa.","D":"As afirmativas I, II e III são verdadeiras.","E":"As afirmativas I, II e III são falsas."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-295714","number":"295714","sourceNumber":"295714","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Em relação aos aspectos epidemiológicos da esclerose múltipla, assinale a opção\ncorreta. I - Desde a metade do século XX o\nnumero de casos de esclerose múltipla tem aumentado\nsignificativamente em diversas regiões do mundo; II - Nos homens o início da doença geralmente é\nmais precoce, antes dos 20 anos; III - A incidência da doença em crianças menores de 10 anos é\nmuito pequena.","options":{"A":"As afirmativas I e II são verdadeiras. A afirmativa III é falsa.","B":"As afirmativas I e III são verdadeiras. A afirmativa II é falsa.","C":"As afirmativas II e III são verdadeiras. A afirmativa I é falsa.","D":"As afirmativas I, II e III são verdadeiras.","E":"As afirmativas I, II e III são falsas."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-257460","number":"257460","sourceNumber":"257460","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Pré escolar de 4 anos inicia com dormência e parestesia, seguidos de fraqueza em\nmembros inferiores. Relata um quadro de\ndiarreia ocorrido há 10 dias com recuperação espontânea\nem dois dias. Ao exame físico observa-se hiporreflexia em membros inferiores. Exame do líquido\ncefalorraquidiano mostra aumento de proteínas, glicose normal e ausência de pleiocitose. Sobre\nesta situação, analise as alternativas abaixo. I ? Um sintoma muito comum nos quadros iniciais é a\ndor nos músculos. II ? Deve ser iniciado o tratamento com imunoglobulina nestes casos desde os\nestágios iniciais. III ? Podem ocorrer sintomas disautonômicos, como bradi ou taquicardia, hipo ou\nhipertensão. Estão corretas as assertivas","options":{"A":"I apenas.","B":"I e II apenas.","C":"I e III apenas.","D":"II e III apenas.","E":"I, II e III."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-257515","number":"257515","sourceNumber":"257515","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Paciente de 27 anos, economista apresentou um episódio de dor ocular unilateral com\nalteração da visão que durou 4 dias, não procurou tratamento devido ficar assintomática. Cerca de\n2 anos após este episódio apresentou quadro de déficit motor em membro inferior unilateral,\nrealizado ressonância magnética (RM) cerebral que foi compatível com esclerose múltipla e\niniciou-se tratamento com uma DMD (droga modificadora da doença). Após seis meses de\ntratamento a paciente estava clinicamente estável e uma nova RM de encéfalo foi realizada.\n\nPraticamente inalterada sem lesões Gd+ ou novas lesões em T2, porém foi descrita presença de\ndiscreta atrofia do parênquima cerebral. A conduta mais correta é","options":{"A":"manter o tratamento iniciado.","B":"iniciar terapia de neuroreabilitação.","C":"mudar para DMD mais potente por falha terapêutica.","D":"encaminhar nova RM, pois o resultado do novo exame não é confiável.","E":"pulsoterapia seriada mensal, com perspectiva futura de uso de Ocrelizumabe."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-13-232672","number":"232672","sourceNumber":"232672","collectionBlock":"med:med-clinica-medica-med-clm-13","collectionLabel":"MED · MED CLM 13","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 13","subtopic":"","stem":"Lactente de 13 meses iniciou com crises epilépticas tônico-clônicas generalizadas, foi\natendido na emergência onde foi medicado com benzodiazepínicos e em seguida com fenitoína,\nsem resolução do episódio após 20 minutos. Em relação ao caso, analise as assertivas abaixo. I -\nPodemos considerar que o paciente apresenta um estado de mal epiléptico refratário. PORQUE II -\nNão houve resposta ao tratamento com a utilização de duas classes de medicamentos.","options":{"A":"As asserções I e II são proposições verdadeiras, e a segunda e? uma justificativa da primeira.","B":"As asserções I e II são proposições verdadeiras, mas a segunda não e? uma justificativa da\nprimeira.","C":"A asserção I e? uma proposição verdadeira e a asserção II e? uma proposição falsa.","D":"A asserção I e? uma proposição falsa e a asserção II e? uma proposição verdadeira.","E":"As asserções I e II são proposições falsas."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 13/MED CLM 13.txt","sourceLabel":"MED · MED CLM 13","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 13","MED"],"answerSource":"explicit","commentDeferred":true}]};
